INSERT INTO public.topics (id, name, category, icon, is_public, description)
INSERT INTO public.words (topic_id, word, phonetic, pos, meaning, example_sentence, lesson_name, lesson_order, word_order)
VALUES
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abase', '/əˈbeɪs/', 'v.', 'Hạ thấp phẩm giá, làm nhục', 'Refusing to abase himself before the military tribunal, the dissident author maintained an unyielding posture of moral defiance.', 'Lesson 1', 1, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abash', '/əˈbæʃ/', 'v.', 'Làm bối rối, làm ngượng ngùng', 'Neither the scathing criticism of the press nor the icy reception from parliament could abash the outspoken reformer.', 'Lesson 1', 1, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abate', '/əˈbeɪt/', 'v.', 'Làm dịu đi, thuyên giảm, lắng xuống', 'Meteorologists cautioned coastal residents that even if the tropical storm''s gale-force winds should abate, catastrophic storm surges remained imminent.', 'Lesson 1', 1, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abbreviate', '/əˈbriːvieɪt/', 'v.', 'Rút ngắn, viết tắt', 'Constrained by the prohibitive cost per word on transatlantic telegraph cables, foreign correspondents had to abbreviate their battlefield dispatches without sacrificing strategic clarity.', 'Lesson 1', 1, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abdicate', '/ˈæbdɪkeɪt/', 'v.', 'Thoái vị, từ bỏ quyền lực', 'Faced with widespread mutiny among the imperial armed forces and the imminent collapse of the capital, the emperor was pressured to abdicate his throne.', 'Lesson 1', 1, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abduction', '/æbˈdʌkʃn/', 'n.', 'Sự bắt cóc, chiếm đoạt người trái phép', 'The clandestine abduction of the reformist senator sparked widespread outrage and ignited weeks of protest outside the presidential palace.', 'Lesson 1', 1, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aberrant', '/æˈberənt/', 'adj.', 'Lệch lạc, khác thường so với quy chuẩn', 'Evolutionary biologists discovered that the aberrant migratory behavior of the alpine finches was a direct phenotypic response to unseasonably warm winters.', 'Lesson 1', 1, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abet', '/əˈbet/', 'v.', 'Tiếp tay, xúi giục làm điều xấu', 'The forensic audit revealed that regional bank directors had conspired to abet the fraudulent venture by falsifying liquidity disclosures.', 'Lesson 1', 1, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abeyance', '/əˈbeɪəns/', 'n.', 'Tình trạng tạm hoãn, đình chỉ', 'With the outbreak of the civil war, construction on the transcontinental railway fell into abeyance until federal funding could be restored.', 'Lesson 1', 1, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abhor', '/əbˈhɔːr/', 'v.', 'Ghê tởm, căm ghét tột độ', 'Enlightenment philosophers such as Voltaire came to abhor religious persecution, advocating instead for universal toleration and civil liberty.', 'Lesson 1', 1, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abject', '/ˈæbdʒekt/', 'adj.', 'Hèn hạ, khốn cùng, cùng cực', 'Living in abject squalor on the periphery of the industrial boomtown, the displaced miners organized one of the earliest labor unions in the region.', 'Lesson 1', 1, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abjure', '/əbˈdʒʊr/', 'v.', 'Tuyên thệ từ bỏ, khước từ trang trọng', 'Summoned before the ecclesiastical court, the astronomer refused to abjure his empirical findings regarding the orbital mechanics of planetary bodies.', 'Lesson 1', 1, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ablution', '/əˈbluːʃn/', 'n.', 'Lễ tẩy trần, việc tắm rửa thanh tẩy', 'Archaeological excavations at the temple complex revealed stone conduits designed specifically for the ritual ablution of priests prior to sacrifice.', 'Lesson 1', 1, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abnegation', '/ˌæbnɪˈɡeɪʃn/', 'n.', 'Sự từ bỏ quyền lợi, sự quên mình', 'The ascetic monk’s life was defined by profound abnegation, renouncing all hereditary wealth and titles to minister to the destitute.', 'Lesson 1', 1, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abolish', '/əˈbɑːlɪʃ/', 'v.', 'Bãi bỏ, hủy bỏ (luật lệ, tập tục)', 'The newly ratified constitutional amendment sought to abolish feudal land tenure and redistribute arable acreage among peasant farmers.', 'Lesson 1', 1, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abominable', '/əˈbɑːmɪnəbl/', 'adj.', 'Đáng ghê tởm, tồi tệ kinh khủng', 'Frederick Douglass delivered searing orations detailing the abominable cruelties inherent in the institution of chattel slavery.', 'Lesson 1', 1, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'absorb', '/əbˈzɔːrb/', 'v.', 'Hấp thụ, tiếp thu, thẩm thấu', 'Vast oceanic carbon sinks absorb roughly a quarter of all anthropogenic emissions, yet this uptake comes at the cost of accelerating acidification.', 'Lesson 1', 1, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abstain', '/əbˈsteɪn/', 'v.', 'Kiêng nhịn, bỏ phiếu trắng', 'Adhering to a strict code of judicial impartiality, the supreme court justice chose to abstain from deliberations involving her former law firm.', 'Lesson 1', 1, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abstemious', '/æbˈstiːmiəs/', 'adj.', 'Tiết chế, điều độ, đạm bạc', 'Despite reigning over one of Europe''s wealthiest empires, the monarch maintained an abstemious regimen of simple fare and early morning physical drills.', 'Lesson 1', 1, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abstinence', '/ˈæbstɪnəns/', 'n.', 'Sự kiêng khem, sự tiết chế', 'Early public health advocates argued that voluntary abstinence from distilled spirits would drastically diminish poverty and urban crime rates.', 'Lesson 1', 1, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abstract', '/ˈæbstrækt/', 'adj.', 'Trừu tượng, mang tính lý thuyết', 'Theoretical physicists often manipulate abstract mathematical constructs in multidimensional space years before experimentalists find empirical verification.', 'Lesson 1', 1, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abstruse', '/æbˈstruːs/', 'adj.', 'Khó hiểu, uyên thâm, thâm thúy', 'Wittgenstein’s early treatise presents an abstruse logical framework that confounded even his closest colleagues at Cambridge.', 'Lesson 1', 1, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abundant', '/əˈbʌndənt/', 'adj.', 'Dồi dào, phong phú', 'Glacial runoff throughout the spring months guaranteed an abundant freshwater supply for the terraced agriculture of the Andean highlands.', 'Lesson 1', 1, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abusive', '/əˈbjuːsɪv/', 'adj.', 'Lăng mạ, sỉ nhục, ngược đãi', 'Investigative journalists exposed the abusive working conditions within the sweatshops, where underage laborers endured twelve-hour shifts without ventilation.', 'Lesson 1', 1, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abut', '/əˈbʌt/', 'v.', 'Tiếp giáp với, nằm sát cạnh', 'In colonial New England towns, private farmlands were mapped to directly abut the town common, ensuring equitable grazing access for all settlers.', 'Lesson 1', 1, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abysmal', '/əˈbɪzməl/', 'adj.', 'Cực kỳ tồi tệ, thê thảm', 'The expedition was doomed by abysmal logistics, as inadequate provisions and faulty navigational charts left the crew stranded in the polar ice.', 'Lesson 1', 1, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abyss', '/əˈbɪs/', 'n.', 'Vực thẳm, khoảng trống vô tận', 'Torn between diplomatic compromise and total war, the prime minister warned that another misstep would plunge the continent into an abyss of mutual destruction.', 'Lesson 1', 1, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'academic', '/ˌækəˈdemɪk/', 'adj.', 'Mang tính học thuật, lý thuyết', 'Since the opposing general had already signed an unconditional surrender, any retrospective debate over strategic maneuvers was rendered purely academic.', 'Lesson 1', 1, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accede', '/əkˈsiːd/', 'v.', 'Đồng ý, nhượng bộ, chấp thuận', 'Surrounded by advancing allied forces and facing civilian insurrection, the beleaguered regent had no choice but to accede to the armistice terms.', 'Lesson 1', 1, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accelerate', '/əkˈseləreɪt/', 'v.', 'Thúc đẩy, làm tăng tốc độ', 'The invention of the steam locomotive served to accelerate the economic integration of frontier territories into global trade networks.', 'Lesson 1', 1, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accentuate', '/əkˈsentʃueɪt/', 'v.', 'Làm nổi bật, nhấn mạnh', 'The stark contrast between the whitewashed colonnades and the deep crimson portico served to accentuate the dramatic proportions of the neoclassical facade.', 'Lesson 1', 1, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accessible', '/əkˈsesəbl/', 'adj.', 'Dễ tiếp cận, dễ hiểu', 'By replacing arcane Latin terminology with clear vernacular prose, the pioneering physician made preventative medicine accessible to rural practitioners.', 'Lesson 1', 1, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accessory', '/əkˈsesəri/', 'n.', 'Phụ kiện, người tòng phạm', 'Under maritime criminal statutes, any merchant who knowingly provisions an illegal blockade runner can be prosecuted as an accessory to treason.', 'Lesson 1', 1, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acclaim', '/əˈkleɪm/', 'v.', 'Hoan nghênh, ca ngợi nồng nhiệt', 'Literary critics across the globe acclaimed her evocative memoir for illuminating the harrowing realities of political exile with unflinching honesty.', 'Lesson 1', 1, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acclimate', '/ˈækləmeɪt/', 'v.', 'Thích nghi với môi trường mới', 'Biologists noted that high-altitude species develop enlarged lung capacities to help them acclimate to the hypobaric pressures of the alpine zone.', 'Lesson 1', 1, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acclivity', '/əˈklɪvəti/', 'n.', 'Dốc ngược, con dốc hướng lên', 'The weary pack mules struggled to haul heavy supply wagons up the steep acclivity leading to the mountain pass.', 'Lesson 1', 1, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accolade', '/ˈækəleɪd/', 'n.', 'Giải thưởng danh giá, sự tán dương', 'Although the mathematician shunned public attention, her groundbreaking proof of the topology conjecture earned her the highest accolade in the field.', 'Lesson 1', 1, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accommodate', '/əˈkɑːmədeɪt/', 'v.', 'Điều chỉnh để đáp ứng, cung cấp chỗ ở', 'The urban transit authority redesigned underground platforms to accommodate the dramatic surge in daily commuter volume projected for the coming decade.', 'Lesson 1', 1, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accomplice', '/əˈkɑːmplɪs/', 'n.', 'Kẻ đồng lõa, tòng phạm', 'During the treason trial, prosecutors demonstrated that the telegraph operator had acted as a willing accomplice by relaying encrypted military codes to enemy agents.', 'Lesson 1', 1, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accord', '/əˈkɔːrd/', 'n.', 'Hiệp định, sự đồng thuận', 'After months of contentious negotiations in Geneva, the rival factions signed a bilateral accord that mandated a phased withdrawal of heavy artillery.', 'Lesson 1', 1, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accost', '/əˈkɔːst/', 'v.', 'Tiếp cận và bắt chuyện đường đột, sấn tới', 'As the governor departed the statehouse, an agitated assembly of disenfranchised factory workers moved to accost him regarding unpaid wages.', 'Lesson 1', 1, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accoutre', '/əˈkuːtər/', 'v.', 'Trang bị đồ dùng, mặc quân phục ấn tượng', 'Quartermasters were ordered to accoutre every infantry battalion with reinforced wool greatcoats and cold-weather provisions prior to the alpine campaign.', 'Lesson 1', 1, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accretion', '/əˈkriːʃn/', 'n.', 'Sự bồi tụ dần dần, sự tích tụ thêm lớp', 'A barrier reef expands over millennia through the continuous accretion of calcium carbonate secreted by colonies of microscopic coral polyps.', 'Lesson 1', 1, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'accrue', '/əˈkruː/', 'v.', 'Tích lũy dồn lại, sinh sôi theo thời gian', 'Substantial environmental dividends will accrue to municipalities that convert municipal bus fleets from fossil fuels to electric power.', 'Lesson 1', 1, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acerbity', '/əˈsɜːrbəti/', 'n.', 'Sự chua chát, gay gắt (trong lời nói)', 'The literary critic was notorious for the relentless acerbity of her reviews, which frequently reduced aspiring novelists to tears.', 'Lesson 1', 1, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acetic', '/əˈsiːtɪk/', 'adj.', 'Có vị chua của giấm, thuộc về axit axetic', 'Prolonged exposure to oxygen spoils vintage wine by encouraging acetobacter proliferation, resulting in a sharp, acetic flavor reminiscent of vinegar.', 'Lesson 1', 1, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acidulous', '/əˈsɪdʒələs/', 'adj.', 'Hơi chua, châm biếm sâu cay', 'Beneath her polished aristocratic demeanor lay an acidulous wit that subtly undermined the self-importance of the royal court.', 'Lesson 1', 1, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acknowledge', '/əkˈnɑːlɪdʒ/', 'v.', 'Thừa nhận, công nhận', 'Even the staunch defenders of laissez-faire capitalism had to acknowledge that unchecked monopolies ultimately stifle market innovation.', 'Lesson 1', 1, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acme', '/ˈækmi/', 'n.', 'Đỉnh cao, tột đỉnh, thời hoàng kim', 'Architects often cite the Parthenon as the acme of Classical Doric design, exemplifying harmonious proportions and subtle optical refinements.', 'Lesson 1', 1, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acoustics', '/əˈkuːstɪks/', 'n.', 'Độ vang âm, đặc tính âm học', 'Sound engineers retrofitted the amphitheater with convex acoustic baffles to optimize the hall''s acoustics for symphonic performances.', 'Lesson 1', 1, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acquiesce', '/ˌækwiˈɛs/', 'v.', 'Bằng lòng, chấp thuận miễn cưỡng mà không phản đối', 'Faced with overwhelming public outcry and the threat of an impending senate inquiry, the embattled minister felt compelled to acquiesce to the committee''s stringent demands.', 'Lesson 1', 1, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acquire', '/əˈkwaɪər/', 'v.', 'Thu được, giành được, tiếp thu', 'Through decades of meticulous archival research across European capitals, the historian managed to acquire an unrivaled collection of Renaissance diplomatic correspondence.', 'Lesson 1', 1, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acquittal', '/əˈkwɪtəl/', 'n.', 'Sự trắng án, phán quyết vô tội', 'Despite the prosecution''s impassioned closing arguments, the sudden appearance of verifiable alibi evidence secured a unanimous acquittal for the wrongly accused dissident.', 'Lesson 1', 1, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acrid', '/ˈækrɪd/', 'adj.', 'Hăng nồng, cay xè, gắt', 'An acrid plume of sulfur and charred timbers lingered over the industrial district for days after the catastrophic refinery explosion.', 'Lesson 1', 1, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'advocate', '/ˈædvəkeɪt/', 'v.', 'Ủng hộ, chủ trương, biện hộ', 'Early abolitionist leaders did not merely condemn the morality of servitude; they traveled across the country to advocate for immediate emancipation and constitutional reform.', 'Lesson 1', 1, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aerie', '/ˈɛri/', 'n.', 'Tổ chim săn mồi trên đỉnh núi cao', 'Perched precariously upon a windswept granite crag, the golden eagle guarded its aerie against predatory hawks circling below.', 'Lesson 1', 1, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aesthetic', '/ɛsˈθɛtɪk/', 'adj.', 'Có tính thẩm mỹ, thuộc về cái đẹp', 'The Bauhaus movement rejected ornate Victorian embellishments, championing an aesthetic philosophy where functional utility dictated every architectural form.', 'Lesson 1', 1, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affable', '/ˈæfəbəl/', 'adj.', 'Niềm nở, ân cần, dễ gần', 'Behind the ambassador''s affable demeanor and genial parlor humor lay an extraordinarily shrewd negotiator capable of outmaneuvering his diplomatic rivals.', 'Lesson 1', 1, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affected', '/əˈfɛktɪd/', 'adj.', 'Điệu bộ, giả tạo, làm bộ làm tịch', 'Critics dismissed the playwright''s affected dialogue, noting that his aristocrats spoke with an exaggerated, melodramatic pomp that felt utterly detached from human reality.', 'Lesson 1', 1, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affidavit', '/ˌæfəˈdeɪvɪt/', 'n.', 'Bản khai có tuyên thệ', 'The whistleblower submitted a notarized affidavit detailing how corporate executives had systematically falsified emissions records to deceive federal regulators.', 'Lesson 1', 1, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affiliation', '/əˌfɪliˈeɪʃən/', 'n.', 'Sự liên kết, sự sáp nhập, sự gắn bó với một tổ chức', 'To preserve editorial objectivity, the investigative journalist renounced any formal political affiliation before covering the contentious national election.', 'Lesson 1', 1, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affinity', '/əˈfɪnɪti/', 'n.', 'Sự đồng cảm tự nhiên, sự cuốn hút, mối gắn kết tương đồng', 'From his earliest childhood in the rural Appalachian hills, the botanist felt an innate affinity for wildflowers, spending entire seasons cataloging rare mountain flora.', 'Lesson 1', 1, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affirmation', '/ˌæfərˈmeɪʃən/', 'n.', 'Lời khẳng định, sự xác nhận', 'The treatise concludes with a passionate affirmation of universal human rights, declaring that liberty is inherent to all individuals regardless of sovereignty.', 'Lesson 1', 1, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affix', '/əˈfɪks/', 'v.', 'Đính vào, gắn vào, dán vào', 'Before the royal decree could become binding law across the provinces, the imperial chancellor had to affix the sovereign''s golden wax seal to the parchment.', 'Lesson 1', 1, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affliction', '/əˈflɪkʃən/', 'n.', 'Nỗi thống khổ, tai ương, nỗi đau xót', 'In nineteenth-century literature, consumption was often romanticized as a tragic, ethereal malady rather than the agonizing pulmonary affliction it truly was.', 'Lesson 1', 1, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affluence', '/ˈæfluəns/', 'n.', 'Sự giàu có, sự sung túc', 'Despite the visible signs of post-war affluence in the burgeoning suburbs, urban economists noted that deep pockets of poverty persisted largely unaddressed.', 'Lesson 1', 1, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'affront', '/əˈfrʌnt/', 'n.', 'Sự lăng nhục, sự xúc phạm công khai', 'The foreign delegate viewed the host nation''s abrupt dismissal of the proposed maritime treaty as a deliberate affront to his country''s sovereign dignity.', 'Lesson 1', 1, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aftermath', '/ˈæftərˌmæθ/', 'n.', 'Hậu quả, giai đoạn hệ lụy', 'In the turbulent aftermath of the monetary collapse, municipal governments struggled to maintain basic civic infrastructure amidst widespread rioting.', 'Lesson 1', 1, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agenda', '/əˈʤɛndə/', 'n.', 'Chương trình nghị sự, nội dung thảo luận', 'Restoring oceanic biodiversity topped the summit''s diplomatic agenda, compelling participating nations to negotiate binding caps on commercial fishing quotas.', 'Lesson 1', 1, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agent', '/ˈeɪʤənt/', 'n.', 'Tác nhân, người đại diện', 'Glacial meltwater acts as a powerful erosive agent, carving deep valleys into ancient bedrock and reshaping mountainous terrain over millennia.', 'Lesson 1', 1, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agglomeration', '/əˌɡlɑməˈreɪʃən/', 'n.', 'Sự kết tụ, sự tích tụ thành khối', 'The megacity expanded not through coherent municipal planning, but as an unruly agglomeration of disparate semi-rural hamlets and industrial enclaves.', 'Lesson 1', 1, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aggrandize', '/əˈɡrænˌdaɪz/', 'v.', 'Làm tăng quyền lực, mở rộng thanh thế', 'Historians argue that the monarch launched costly foreign wars less to protect national borders than to aggrandize his personal dynasty on the global stage.', 'Lesson 1', 1, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aggregate', '/ˈæɡrɪɡət/', 'n.', 'Tổng thể, khối kết tụ, tập hợp', 'Viewed in isolation, each small economic fluctuation seemed inconsequential, but taken in the aggregate, they heralded a profound structural recession.', 'Lesson 1', 1, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acrimonious', '/ˌækrɪˈmoʊniəs/', 'adj.', 'Gay gắt, cay cú, chua chát', 'Months of acrimonious floor debate over electoral redistricting shattered any remaining semblance of bipartisan cooperation in the legislative assembly.', 'Lesson 1', 1, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acrophobia', '/ˌækrəˈfoʊbiə/', 'n.', 'Chứng sợ độ cao', 'Paralyzed by severe acrophobia, the surveyor found it impossible to cross the narrow suspension bridge suspended hundreds of feet above the rocky gorge.', 'Lesson 1', 1, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'actuarial', '/ˌæktʃuˈɛriəl/', 'adj.', 'Thuộc tính toán bảo hiểm, thống kê rủi ro', 'Insurance underwriters rely heavily on rigorous actuarial models that analyze demographic data, life expectancy tables, and historical morbidity trends.', 'Lesson 1', 1, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'actuate', '/ˈæktʃuˌeɪt/', 'v.', 'Thúc đẩy, kích hoạt, vận hành', 'The mechanical sensor is designed to actuate an emergency cooling mechanism whenever internal reactor core temperatures surpass critical thresholds.', 'Lesson 1', 1, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acuity', '/əˈkjuɪti/', 'n.', 'Sự sắc bén, sự thấu suốt, thị lực hoặc thính lực tinh tường', 'Even well into her nineties, the philosopher demonstrated astonishing intellectual acuity, dismantling intricate metaphysical paradoxes with effortless clarity.', 'Lesson 1', 1, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acumen', '/əˈkjuːmən/', 'n.', 'Sự nhạy bén, đầu óc tinh tường', 'Possessing exceptional commercial acumen, the venture capitalist anticipated the collapse of speculative tech stocks months before traditional market analysts did.', 'Lesson 1', 1, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'acute', '/əˈkjuːt/', 'adj.', 'Sâu sắc, cấp tính, dữ dội', 'The protracted drought precipitated an acute food shortage across the arid basin, threatening millions of subsistence farmers with imminent starvation.', 'Lesson 1', 1, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adage', '/ˈædɪʤ/', 'n.', 'Châm ngôn, tục ngữ', 'The diplomat reminded the restless young officers of the ancient adage that haste often breeds failure, counseling patience during the sensitive bilateral talks.', 'Lesson 1', 1, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adamant', '/ˈædəmənt/', 'adj.', 'Kiên quyết, sắt đá, không suy chuyển', 'Despite fierce lobbying from fossil fuel executives, the prime minister remained adamant that carbon reduction benchmarks would not be watered down.', 'Lesson 1', 1, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adapt', '/əˈdæpt/', 'v.', 'Thích nghi, biến đổi để phù hợp', 'Evolutionary biologists noted how swiftly the arctic fox managed to adapt its hunting strategies as shrinking pack ice disrupted traditional seal habitats.', 'Lesson 1', 1, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aboriginal', '/ˌæbəˈrɪʤɪnəl/', 'adj.', 'Bản địa, thuộc thời sơ khai', 'Archaeologists uncovered complex irrigation channels demonstrating that the region''s aboriginal inhabitants had mastered water management centuries before European arrival.', 'Lesson 1', 1, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abortive', '/əˈbɔːrtɪv/', 'adj.', 'Sớm thất bại, không thành, dở dang', 'After an abortive attempt to storm the heavily fortified garrison, the rebel forces retreated into the dense mountain foliage to regroup.', 'Lesson 1', 1, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abrade', '/əˈbreɪd/', 'v.', 'Mài mòn, làm trầy xước', 'Over eons, airborne dust particles propelled by relentless desert winds gradually abrade even the hardest sandstone formations into delicate spires.', 'Lesson 1', 1, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abrasive', '/əˈbreɪsɪv/', 'adj.', 'Gay gắt, lỗ mãng, thô bạo', 'Though universally respected for his diagnostic brilliance, the head surgeon''s abrasive bedside manner alienated patients and demoralized the nursing staff.', 'Lesson 1', 1, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'addendum', '/əˈdɛndəm/', 'n.', 'Phần bổ sung, phụ lục', 'In an addendum appended to the environmental impact report, lead investigators acknowledged newly gathered data regarding downstream pesticide runoff.', 'Lesson 1', 1, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'addiction', '/əˈdɪkʃən/', 'n.', 'Sự nghiện ngập, thói quen lệ thuộc', 'Neuroscientists have demonstrated that chronic behavioral addiction alters dopamine receptor density in the brain, impairing impulse control and rational decision-making.', 'Lesson 1', 1, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'addle', '/ˈædəl/', 'v.', 'Làm rối trí, làm mê muội', 'Prolonged sleep deprivation began to addle the sentry''s judgment, causing him to mistake swaying tree branches for an advancing enemy patrol.', 'Lesson 1', 1, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'address', '/əˈdrɛs/', 'v.', 'Giải quyết, chú trọng xử lý, phát biểu trước', 'The congressional subcommittee convened an extraordinary session to address systemic vulnerabilities in the nation''s electrical power grid.', 'Lesson 1', 1, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adept', '/əˈdɛpt/', 'adj.', 'Thành thạo, tinh thông, điêu luyện', 'Renowned as an exceptionally adept orator, Frederick Douglass wielded vivid metaphors and scathing logic to lay bare the moral hypocrisy of slavery.', 'Lesson 1', 1, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adhere', '/ədˈhɪər/', 'v.', 'Bám dính, tuân thủ nghiêm ngặt', 'Physicians are ethically bound to adhere to the Hippocratic oath, placing the welfare and autonomy of their patients above pecuniary interests.', 'Lesson 1', 1, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adherent', '/ədˈhɪərənt/', 'n.', 'Người ủng hộ, tín đồ trung thành', 'As an ardent adherent of laissez-faire economic theory, the theorist vigorously opposed any government intervention in free market mechanisms.', 'Lesson 1', 1, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adjacent', '/əˈʤeɪsənt/', 'adj.', 'Liền kề, kề bên, giáp ranh', 'The zoning board prohibited commercial real estate development on parcel land immediately adjacent to the fragile wetland sanctuary.', 'Lesson 1', 1, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adjunct', '/ˈæʤʌŋkt/', 'n.', 'Phần bổ trợ, vật phụ trợ', 'In traditional clinical psychology, behavioral therapy was long considered merely an adjunct to pharmaceutical interventions, though modern practitioners treat them as equal pillars.', 'Lesson 1', 1, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'admonish', '/ədˈmɑːnɪʃ/', 'v.', 'Khuyên răn, cảnh cáo, khiển trách', 'The federal judge felt obliged to admonish the lead attorney after repeated attempts to introduce inadmissible hearsay into the courtroom.', 'Lesson 1', 1, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'admonition', '/ˌædməˈnɪʃən/', 'n.', 'Lời khuyên răn, lời khiển trách cảnh báo', 'Heeding his mentor''s solemn admonition regarding the perils of academic complacency, the young doctoral candidate redoubled his research efforts.', 'Lesson 1', 1, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adorn', '/əˈdɔːrn/', 'v.', 'Tô điểm, trang hoàng', 'Intricate frescoes and gilded mosaics adorn the vaulted ceilings of the Byzantine cathedral, reflecting candlelight into luminous spiritual motifs.', 'Lesson 1', 1, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adroit', '/əˈdrɔɪt/', 'adj.', 'Khéo léo, tài tình, mau lẹ', 'Through an adroit series of diplomatic maneuvers, the prime minister managed to avert an armed standoff while preserving his nation''s strategic alliances.', 'Lesson 1', 1, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adulation', '/ˌædʒəˈleɪʃən/', 'n.', 'Sự tán dương quá mức, sự nịnh bợ', 'Unaccustomed to such uncritical public adulation, the reserved scientist insisted that the medical breakthrough belonged to the entire research consortium rather than to him alone.', 'Lesson 2', 2, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adulterate', '/əˈdʌltəreɪt/', 'v.', 'Làm giả, làm cho kém chất lượng bằng cách pha tạp', 'Unscrupulous merchants during the famine attempted to adulterate bags of flour with fine chalk dust to artificially inflate their dwindling inventory.', 'Lesson 2', 2, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aggressor', '/əˈɡrɛsər/', 'n.', 'Kẻ xâm lược, bên phát động tấn công trước', 'By launching a sudden preemptive naval strike without formal provocation, the bellicose empire indisputably established itself as the aggressor in the escalating war.', 'Lesson 2', 2, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aghast', '/əˈɡæst/', 'adj.', 'Kinh ngạc, sửng sốt, kinh hãi', 'The assembly of ambassadors stood aghast as the foreign minister abruptly declared his government''s intention to repudiate the fifty-year-old nonaggression treaty.', 'Lesson 2', 2, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agility', '/əˈdʒɪləti/', 'n.', 'Sự nhanh nhẹn, tính linh hoạt về thể chất hoặc tư duy', 'Navigating sudden macroeconomic turbulence demanded not merely deep capital reserves, but also exceptional strategic agility from the corporation''s executive leadership.', 'Lesson 2', 2, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abridge', '/əˈbrɪdʒ/', 'v.', 'Rút gọn, lược bớt nội dung, hạn chế quyền lợi', 'Civil libertarians argued before the Supreme Court that the proposed emergency statute would dangerously abridge fundamental First Amendment rights of peaceful assembly.', 'Lesson 2', 2, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abrogate', '/ˈæbrəɡeɪt/', 'v.', 'Bãi bỏ hoặc hủy bỏ hiệu lực của một đạo luật hay hiệp ước', 'Following the coup d''état, the newly established regime acted swiftly to abrogate the maritime boundaries agreed upon in the previous decade''s diplomatic pact.', 'Lesson 2', 2, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'abscond', '/æbˈskɑnd/', 'v.', 'Bỏ trốn, lẩn trốn để tránh bị phát giác hay bắt giữ', 'Realizing that federal forensic auditors had traced the fictitious offshore accounts, the rogue financier attempted to abscond aboard a private vessel before dawn.', 'Lesson 2', 2, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'absolute', '/ˈæbsəlut/', 'adj.', 'Tuyệt đối, hoàn toàn, không bị giới hạn', 'Seventeenth-century apologists for divine right claimed that the monarch''s authority was absolute, brooking no interference from parliamentary assemblies or judiciary rulings.', 'Lesson 2', 2, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'absolve', '/əbˈzɑlv/', 'v.', 'Xá tội, tuyên bố vô tội, miễn trừ trách nhiệm', 'The discovery of unredacted diplomatic cables did not absolve the colonial administrator of complicity in the severe repressions that followed the provincial uprising.', 'Lesson 2', 2, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'advent', '/ˈædvɛnt/', 'n.', 'Sự xuất hiện, sự ra đời của một thời kỳ hoặc phát minh quan trọng', 'The advent of mechanised printing in fifteenth-century Europe profoundly democratized religious debate and undermined the monopolistic authority of scholastic scribes.', 'Lesson 2', 2, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adventitious', '/ˌædvɛnˈtɪʃəs/', 'adj.', 'Tình cờ, ngẫu nhiên, từ bên ngoài đưa vào', 'Evolutionary biologists determined that the sudden surge in the island''s beetle population was not an innate adaptation, but an adventitious consequence of ballast soil dumped by cargo ships.', 'Lesson 2', 2, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adversary', '/ˈædvərˌsɛri/', 'n.', 'Đối thủ, kẻ địch', 'Though profoundly respectful of one another in private correspondence, the two constitutional attorneys proved ferocious adversaries whenever arguing landmark appeals before the bench.', 'Lesson 2', 2, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adverse', '/ædˈvərs/', 'adj.', 'Bất lợi, có hại, ngược chiều', 'Despite persistently adverse climatic conditions characterized by prolonged droughts and saline soil, the agricultural cooperative harvested a resilient yield of hybrid millet.', 'Lesson 2', 2, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'adversity', '/ædˈvərsəti/', 'n.', 'Nghịch cảnh, hoàn cảnh khó khăn gian truân', 'Frederick Douglass famously attested that enduring profound personal adversity, far from breaking his spirit, fortified his lifelong resolve to struggle against institutional bondage.', 'Lesson 2', 2, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'advocacy', '/ˈædvəkəsi/', 'n.', 'Sự vận động, sự bênh vực hoặc ủng hộ công khai cho một chính sách', 'Rachel Carson''s fearless public advocacy catalyzed widespread environmental consciousness and ultimately compelled the federal government to prohibit the agricultural spraying of DDT.', 'Lesson 2', 2, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agitate', '/ˈædʒɪteɪt/', 'v.', 'Kích động, làm xáo động, cổ động quần chúng', 'Discontented industrial workers began to openly agitate for collective bargaining rights and an eight-hour workday through clandestine underground leaflets.', 'Lesson 2', 2, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agnostic', '/æɡˈnɑstɪk/', 'n.', 'Người theo thuyết bất khả tri', 'Describing himself as a resolute agnostic, the Victorian naturalist argued that cosmic origins lay forever outside the reach of sensory observation and empirical confirmation.', 'Lesson 2', 2, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'agrarian', '/əˈɡrɛriən/', 'adj.', 'Thuộc về nông nghiệp, ruộng đất', 'Thomas Jefferson championed an agrarian republic where self-reliant yeoman farmers would serve as virtuous guardians against the corruptions of urban industrialism.', 'Lesson 2', 2, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alacrity', '/əˈlækrəti/', 'n.', 'Sự sốt sắng, sự hăng hái và nhanh nhẹn', 'Anticipating an imminent counterattack from the flank, the seasoned cavalry scouts carried out the general''s retreat orders with disciplined alacrity.', 'Lesson 2', 2, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alchemy', '/ˈælkəmi/', 'n.', 'Giả kim thuật, phép biến đổi kỳ diệu', 'Isaac Newton spent decades secretly immersed in the symbolic literature of alchemy, seeking universal cosmological truths alongside his mathematical formulations of optics and gravitation.', 'Lesson 2', 2, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alcove', '/ˈælkoʊv/', 'n.', 'Hốc tường, góc thụt vào trong phòng', 'Tucked away in a shadowy alcove of the monastery library, the illuminator labored under candle-light to gild the borders of the vellum Psalter.', 'Lesson 2', 2, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alias', '/ˈeɪliəs/', 'n.', 'Bí danh, tên giả', 'Operating under the innocuous alias of a traveling linen merchant, the intelligence officer moved undetected across fortified enemy territory.', 'Lesson 2', 2, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alienate', '/ˈeɪliəneɪt/', 'v.', 'Làm cho xa lánh, cô lập, làm mất thiện cảm', 'The autocratic director''s dismissive attitude toward junior researchers threatened to alienate the laboratory''s brightest talent and derail the pharmaceutical project.', 'Lesson 2', 2, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alimentary', '/ˌæləˈmɛntəri/', 'adj.', 'Thuộc về dinh dưỡng, thức ăn hoặc bộ máy tiêu hóa', 'Comparative physiologists noted that ruminants possess an intricately specialized alimentary tract capable of extracting vital carbohydrates from fibrous forage.', 'Lesson 2', 2, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alimony', '/ˈæləmoʊni/', 'n.', 'Khoản tiền cấp dưỡng sau khi ly hôn', 'Under the formal divorce settlement ratified by the magistrate, the shipping magnate was mandated to remit substantial monthly alimony to maintain his ex-spouse''s estate.', 'Lesson 2', 2, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allay', '/əˈleɪ/', 'v.', 'Làm dịu đi, xua tan, trấn an nỗi lo sợ', 'Seeking to allay widespread fears of a banking collapse, the treasury secretary held a nationally televised address outlining comprehensive liquidity guarantees.', 'Lesson 2', 2, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allege', '/əˈlɛdʒ/', 'v.', 'Cáo buộc, khẳng định khi chưa có bằng chứng xác thực', 'State prosecutors allege that executives at the chemical conglomerate intentionally concealed toxic effluent discharge reports from regional environmental regulators.', 'Lesson 2', 2, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allegiance', '/əˈlidʒəns/', 'n.', 'Lòng trung thành, sự tận tụy gắn bó', 'Torn between familial allegiance to his confederate birthplace and constitutional fidelity to the Union, the naval officer faced an excruciating moral crossroads.', 'Lesson 2', 2, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allegory', '/ˈæləɡɔri/', 'n.', 'Truyện ngụ ngôn, biểu tượng chứa đựng ý nghĩa ẩn dụ', 'Plato''s famed Allegory of the Cave uses the dramatic journey from subterranean shadow into daylight to symbolize the philosophical awakening of the human soul.', 'Lesson 2', 2, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alleviate', '/əˈlivieɪt/', 'v.', 'Làm nhẹ bớt, làm giảm bớt nỗi đau hoặc khó khăn', 'International relief organizations dispatched mobile water purification units to alleviate acute sanitary crises throughout the earthquake-stricken province.', 'Lesson 2', 2, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alliteration', '/əˌlɪtəˈreɪʃən/', 'n.', 'Phép điệp phụ âm đầu', 'The Anglo-Saxon bard skillfully employed alliteration rather than modern rhyming schemes to imbue Beowulf with rhythmic solemnity during oral recitations.', 'Lesson 2', 2, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allocate', '/ˈæləkeɪt/', 'v.', 'Phân bổ, chỉ định nguồn lực cho một mục đích nhất định', 'The parliamentary budget committee agreed to allocate substantial capital endowments directly to municipal transit authorities rather than suburban highway expansions.', 'Lesson 2', 2, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'alloy', '/ˈælɔɪ/', 'n.', 'Hợp kim', 'Aerospace engineers selected a specialized titanium-aluminum alloy whose remarkable strength-to-weight ratio could withstand the intense thermal friction of supersonic atmospheric re-entry.', 'Lesson 2', 2, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allude', '/əˈlud/', 'v.', 'Nói bóng gió, ám chỉ gián tiếp', 'In her seminal critique of modern capitalism, the sociologist chose only to allude to earlier Marxist doctrine rather than explicitly invoke its contentious nomenclature.', 'Lesson 2', 2, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allure', '/əˈlʊr/', 'n.', 'Sức lôi cuốn, sự quyến rũ mê hoặc', 'The seductive allure of instant maritime wealth drew hundreds of impoverished European sailors onto perilous voyages into uncharted waters across the South Pacific.', 'Lesson 2', 2, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'allusion', '/əˈluʒən/', 'n.', 'Lời ám chỉ, điển tích hoặc dẫn chiếu gián tiếp', 'Herman Melville''s Moby-Dick opens with a deliberate Biblical allusion when the narrator implores the reader to ''Call me Ishmael,'' establishing his outsider status.', 'Lesson 2', 2, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aloft', '/əˈlɔft/', 'adv.', 'Ở trên cao, trên không trung', 'Powerful thermal updrafts rising from the sun-drenched canyon floor enabled the Andean condor to remain aloft for hours without expending energy to flap its wings.', 'Lesson 2', 2, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aloof', '/əˈluf/', 'adj.', 'Xa cách, hững hờ, lãnh đạm', 'Though revered for his intellectual brilliance, the diplomatic envoy remained aloof from local social circles, preferring the detached tranquility of his embassy study.', 'Lesson 2', 2, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'altercation', '/ˌɔltərˈkeɪʃən/', 'n.', 'Cuộc cãi cọ ầm ĩ, sự xung đột gay gắt nơi công cộng', 'What commenced as a routine trade negotiation abruptly deteriorated into a loud altercation between the envoys, prompting security personnel to intervene immediately.', 'Lesson 2', 2, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'altruistic', '/ˌæltruˈɪstɪk/', 'adj.', 'Vị tha, nhân hậu, vì lợi ích của người khác', 'Skeptical political scientists questioned whether the foreign superpower''s massive developmental aid represented a genuinely altruistic initiative or merely an instrument of geopolitical leverage.', 'Lesson 2', 2, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amalgamate', '/əˈmælɡəmeɪt/', 'v.', 'Hợp nhất, kết hợp thành một tổ chức thống nhất', 'Under the national industrial reorganization act, independent regional railway lines were compelled to amalgamate into a single centralized transit syndicate.', 'Lesson 2', 2, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amass', '/əˈmæs/', 'v.', 'Tích lũy, cóp nhặt số lượng lớn theo thời gian', 'Through decades of meticulous archival excavation across continental libraries, the paleographer managed to amass the world''s most exhaustive collection of Carolingian deeds.', 'Lesson 2', 2, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ambidextrous', '/ˌæmbɪˈdɛkstrəs/', 'adj.', 'Thuận cả hai tay, khéo léo cả hai tay như nhau', 'Because microscopic vascular surgery demands millimeter precision at awkward anatomical angles, surgeons who are naturally ambidextrous hold a formidable technical advantage.', 'Lesson 2', 2, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ambience', '/ˈæmbiəns/', 'n.', 'Không khí, bầu không gian đặc trưng của một nơi', 'The crackling hearth, towering mahogany bookshelves, and subdued amber lighting imparted to the college common room a cozy, contemplative ambience.', 'Lesson 2', 2, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ambiguous', '/æmˈbɪɡjuəs/', 'adj.', 'Mơ hồ, nhập nhằng, không rõ ràng', 'The treaty''s deliberately ambiguous phrasing regarding maritime sovereign boundaries laid the groundwork for severe territorial disputes decades after its signing.', 'Lesson 2', 2, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ambivalence', '/æmˈbɪvələns/', 'n.', 'Sự mâu thuẫn trong tư tưởng hoặc cảm xúc', 'Ecological historians have documented society''s deep-seated ambivalence toward nuclear power, acknowledging its carbon neutrality while remaining terrified of radioactive catastrophe.', 'Lesson 2', 2, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amble', '/ˈæmbəl/', 'v.', 'Đi dạo thong thả, tản bộ thảnh thơi', 'Unbothered by the bustling commerce of the harbor, the elderly philosopher would amble along the coastal seawall each afternoon, lost in speculative meditation.', 'Lesson 2', 2, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ambulatory', '/ˈæmbjələˌtɔri/', 'adj.', 'Có thể đi lại được, không phải nằm một chỗ', 'Modern post-operative protocols urge joint replacement patients to become ambulatory within twenty-four hours to stimulate systemic circulation and expedite recovery.', 'Lesson 2', 2, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ameliorate', '/əˈmiljəreɪt/', 'v.', 'Cải thiện, làm cho tốt hơn, xoa dịu tình trạng xấu', 'Public health reformers in nineteenth-century London constructed deep subterranean sewer networks to ameliorate the catastrophic urban spread of cholera and typhus.', 'Lesson 2', 2, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amenable', '/əˈmiːnəbəl/', 'adj.', 'Dễ bảo, sẵn sàng lắng nghe hoặc tiếp thu', 'Although the conservative faction initially resisted regulatory reform, party leaders proved amenable to a compromise once provisions protecting small businesses were incorporated.', 'Lesson 2', 2, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amend', '/əˈmend/', 'v.', 'Sửa đổi, bổ sung (văn bản, luật lệ)', 'Recognizing that the Articles of Confederation had established a central government too feeble to levy taxes, delegates assembled in Philadelphia to amend the young nation''s constitutional charter.', 'Lesson 2', 2, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amenities', '/əˈmenətiz/', 'n.', 'Tiện nghi, tiện ích sinh hoạt', 'Urban sociologists observed that while historic tenement quarters lacked basic modern amenities such as indoor plumbing and adequate ventilation, they fostered remarkably resilient communal networks.', 'Lesson 2', 2, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amiable', '/ˈeɪmiəbəl/', 'adj.', 'Thân thiện, hòa nhã, dễ mến', 'Even during high-stakes diplomatic crises, the ambassador maintained an amiable disposition, disarming contentious adversaries with genuine warmth and self-effacing humor.', 'Lesson 2', 2, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amicable', '/ˈæmɪkəbəl/', 'adj.', 'Hòa giải, thân thiện, không có hiềm khích', 'Following months of fraught corporate litigation, the competing software firms reached an amicable settlement that safeguarded proprietary patents without stifling market competition.', 'Lesson 2', 2, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amiss', '/əˈmɪs/', 'adj.', 'Sai sót, bất thường, có trục trặc', 'When astronomical observations of Uranus revealed systematic orbital deviations, nineteenth-century celestial cartographers surmised that something was amiss with their calculations, hinting at the gravitational pull of an undiscovered planet.', 'Lesson 2', 2, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amity', '/ˈæmɪti/', 'n.', 'Tình hữu nghị, quan hệ hòa hảo', 'The Treaty of Ghent did more than formally conclude hostilities; it inaugurated two centuries of unbroken amity and unfortified border peace between the neighboring nations.', 'Lesson 2', 2, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amnesia', '/æmˈniːʒə/', 'n.', 'Chứng mất trí nhớ', 'The cultural historian argued that the victorious empire succumbed to a selective moral amnesia, willfully effacing from its public school curriculum the atrocities committed during colonial expansion.', 'Lesson 2', 2, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amnesty', '/ˈæmnəsti/', 'n.', 'Lệnh ân xá, sự tha tội tập thể', 'In an effort to facilitate post-war national reconciliation, the provisional council granted a conditional amnesty to insurgent soldiers who agreed to surrender their arms and swear allegiance to the republic.', 'Lesson 2', 2, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amoral', '/eɪˈmɔːrəl/', 'adj.', 'Phi luân lý, không bận tâm đến đạo đức', 'Political realists insist that international diplomacy operates within an essentially amoral framework, where nation-states are driven by geopolitical survival rather than altruistic ideals.', 'Lesson 2', 2, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amorous', '/ˈæmərəs/', 'adj.', 'Đa tình, chan chứa tình yêu nam nữ', 'In Shakespeare''s romantic comedies, courtly lovers frequently express their amorous longing through elaborate poetic conceits that border on self-parody.', 'Lesson 2', 2, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amorphous', '/əˈmɔːrfəs/', 'adj.', 'Vô định hình, không có cấu trúc xác định', 'Before the establishment of rigorous legal codification, maritime custom remained an amorphous collection of regional traditions and unwritten seafaring conventions.', 'Lesson 2', 2, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amphibian', '/æmˈfɪbiən/', 'n.', 'Động vật lưỡng cư', 'Because its permeable skin readily absorbs pollutants from both terrestrial runoff and aquatic habitats, the spotted salamander serves as a sentinel amphibian signaling early wetland degradation.', 'Lesson 2', 2, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amphitheater', '/ˈæmfəˌθiːətər/', 'n.', 'Nhà hát vòng tròn, đấu trường bậc thang', 'Carved directly into the limestone hillside of Epidaurus, the ancient Greek amphitheater boasted acoustic properties so extraordinary that an actor''s whisper on stage resonated clearly in the uppermost rows.', 'Lesson 2', 2, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ample', '/ˈæmpəl/', 'adj.', 'Dư dả, phong phú, rộng rãi', 'The discovery of pollen grains preserved deep within the lake sediment provided ample paleobotanical evidence that the arid valley once supported lush temperate forests.', 'Lesson 2', 2, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amplify', '/ˈæmpləfaɪ/', 'v.', 'Khuếch đại, tăng cường, thổi phồng', 'Echo chambers within digital communication networks tend to amplify partisan grievances, distorting moderate civic discourse into radical ideological confrontation.', 'Lesson 2', 2, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amputate', '/ˈæmpjʊteɪt/', 'v.', 'Cắt cụt (bộ phận cơ thể)', 'Prior to the advent of sterile surgical techniques and effective anesthesia, Civil War field doctors were compelled to amputate shattered limbs within minutes to thwart fatal bacterial infections.', 'Lesson 2', 2, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'amulet', '/ˈæmjʊlət/', 'n.', 'Bùa hộ mệnh', 'Archaeologists excavating the dynastic necropolis unearthed a faience amulet shaped like the eye of Horus, which the ancient embalmers had placed upon the deceased''s chest to ward off malevolent spirits.', 'Lesson 2', 2, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anachronistic', '/əˌnækrəˈnɪstɪk/', 'adj.', 'Sai lệch thời đại, lỗi thời', 'Literary critics derided the historical dramatist for inserting anachronistic egalitarian philosophies into the dialogue of fourteenth-century feudal barons.', 'Lesson 2', 2, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'analgesic', '/ˌænəlˈdʒiːzɪk/', 'n.', 'Thuốc giảm đau', 'Ethnobotanists discovered that indigenous tribes along the Amazon basin had long utilized the bark of the cinchona tree not only to mitigate malarial fevers but also as a potent natural analgesic.', 'Lesson 2', 2, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'analogous', '/əˈnæləɡəs/', 'adj.', 'Tương tự, tương đồng về bản chất', 'The evolutionary biologist demonstrated that the sonar capabilities of microbats and oceanic dolphins are analogous adaptations that evolved along separate phylogenetic lineages to navigate murky environments.', 'Lesson 2', 2, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'analogy', '/əˈnælədʒi/', 'n.', 'Sự tương tự, phép loại suy', 'To illustrate how gravity warps the fabric of the cosmos, the theoretical physicist drew an intuitive analogy between mass curving four-dimensional spacetime and a bowling ball depressing a trampoline.', 'Lesson 2', 2, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anarchist', '/ˈænərkɪst/', 'n.', 'Người theo chủ nghĩa vô chính phủ', 'Unlike social democrats who sought to capture legislative power through parliamentary elections, the nineteenth-century anarchist Peter Kropotkin advocated for the voluntary dissolution of all coercive state apparatuses.', 'Lesson 2', 2, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anarchy', '/ˈænərki/', 'n.', 'Tình trạng vô chính phủ, sự hỗn loạn vô trật tự', 'When the occupying legions abruptly withdrew from the borderlands, the sudden collapse of administrative authority plunged the merchant cities into civil war and commercial anarchy.', 'Lesson 2', 2, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anathema', '/əˈnæθəmə/', 'n.', 'Điều ghê tởm, thứ bị bài trừ nguyền rủa', 'To early republican theorists steeped in the virtues of Spartan frugality, the ostentatious wealth and hereditary titles of monarchical courts were an intolerable anathema.', 'Lesson 2', 2, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ancestry', '/ˈænsestri/', 'n.', 'Tổ tiên, dòng dõi', 'By mapping ancient genome variations among indigenous populations, paleoanthropologists have illuminated prehistoric migratory corridors and traced the maternal ancestry of modern Polynesians.', 'Lesson 2', 2, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anchor', '/ˈæŋkər/', 'n.', 'Mỏ neo, chỗ dựa vững chắc', 'During the economic volatility following the currency devaluations, the gold standard had functioned as a psychological anchor, reassuring wary investors of underlying institutional stability.', 'Lesson 2', 2, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ancillary', '/ˈænsəleri/', 'adj.', 'Phụ trợ, bổ trợ', 'While the federal grant was primarily earmarked for constructing the particle accelerator, researchers allocated a modest portion for ancillary laboratory infrastructure, including cryogenic cooling tanks.', 'Lesson 2', 2, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anecdote', '/ˈænɪkdoʊt/', 'n.', 'Giai thoại, câu chuyện ngắn minh họa', 'In his autobiography, Benjamin Franklin deployed a self-deprecating anecdote about paying too much for a childhood whistle to encapsulate his hard-learned maxims on prudence and temperance.', 'Lesson 2', 2, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anemia', '/əˈniːmiə/', 'n.', 'Bệnh thiếu máu', 'Routine hematological screening of the remote alpine community revealed a widespread microcytic anemia, largely attributable to a regional diet deficient in bioavailable dietary iron.', 'Lesson 2', 2, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anesthetic', '/ˌænəsˈθetɪk/', 'n.', 'Thuốc gây mê, thuốc gây tê', 'The public demonstration of diethyl ether as an operative anesthetic at Massachusetts General Hospital in 1846 permanently liberated surgical practice from the agonizing screams of conscious patients.', 'Lesson 2', 2, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anguish', '/ˈæŋɡwɪʃ/', 'n.', 'Nỗi đau đớn, nỗi thống khổ cùng cực', 'In his melancholic war memoirs, the veteran conveyed the existential anguish of having survived artillery bombardments that decimated his closest companions.', 'Lesson 2', 2, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'angular', '/ˈæŋɡjələr/', 'adj.', 'Góc cạnh, gầy gò xương xẩu', 'Departing sharply from the fluid, organic ornamentation of Art Nouveau, Bauhaus architecture embraced functionalist aesthetics defined by severe right angles and stark, angular masonry.', 'Lesson 2', 2, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'animated', '/ˈænəmeɪtɪd/', 'adj.', 'Sôi nổi, đầy sức sống, hào hứng', 'The town hall meeting was marked by an animated exchange between municipal preservationists and commercial real estate developers regarding the rezoning of the historic waterfront.', 'Lesson 2', 2, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'animosity', '/ˌænəˈmɑːsəti/', 'n.', 'Lòng thù oán, sự ác cảm sâu sắc', 'Despite concluding a formal armistice, lingering sectarian animosity between the border provinces threatened to undermine long-term reconstruction efforts.', 'Lesson 2', 2, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'animus', '/ˈænɪməs/', 'n.', 'Sự thù hằn, ác ý, động cơ thù địch', 'The appellate judiciary struck down the municipal zoning ordinance after internal correspondences confirmed that the council''s decision was motivated by sectarian animus rather than legitimate public interest.', 'Lesson 2', 2, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'annals', '/ˈænəlz/', 'n.', 'Biên niên sử, hồ sơ ghi chép lịch sử', 'Hypatia of Alexandria’s pioneering contributions to mathematical astronomy earned her a revered, albeit tragic, renown in the annals of late classical scholarship.', 'Lesson 2', 2, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'annex', '/əˈneks/', 'v.', 'Thôn tính, sáp nhập lãnh thổ', 'Emboldened by a fragmented opposition and mineral-rich territories along its western border, the militaristic empire moved decisively to annex the defenseless border state.', 'Lesson 2', 2, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'annihilate', '/əˈnaɪəleɪt/', 'v.', 'Tiêu diệt hoàn toàn, hủy diệt', 'In particle physics, when a positron encounters an electron, their opposite electric charges cause them to annihilate each other, releasing their total invariant mass as high-energy gamma rays.', 'Lesson 2', 2, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'annotate', '/ˈænəteɪt/', 'v.', 'Chú thích, giải thích bổ sung cho văn bản', 'Before releasing the critical scholarly edition of Milton''s Paradise Lost, the literary philologist spent decades annotating obscure theological references and Latinate syntax.', 'Lesson 2', 2, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'annuity', '/əˈnuːəti/', 'n.', 'Tiền niên kim, khoản trợ cấp hàng năm', 'To guarantee her financial independence after retiring from the academy, the mathematician invested a portion of her royalties into a fixed annuity that disbursed quarterly stipends.', 'Lesson 2', 2, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'annul', '/əˈnʌl/', 'v.', 'Hủy bỏ, bãi bỏ hiệu lực pháp lý', 'When judicial scrutiny revealed that the disputed deed of sale had been executed under severe duress, the chancellor acted immediately to annul the transaction.', 'Lesson 2', 2, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anoint', '/əˈnɔɪnt/', 'v.', 'Xức dầu thánh, chỉ định chính thức', 'During the sacred rites at Reims, the archbishop used holy chrism to anoint the French king, thereby signifying that sovereign authority was sanctified by heavenly prerogative.', 'Lesson 2', 2, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anomalous', '/əˈnɑːmələs/', 'adj.', 'Bất thường, dị thường, lệch chuẩn', 'When laboratory instruments registered an anomalous surge in gamma radiation, the nuclear physicists immediately halted the particle collision experiment to inspect the detector sensors.', 'Lesson 2', 2, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anomaly', '/əˈnɑːməli/', 'n.', 'Sự bất thường, hiện tượng dị thường', 'The unexpected observation of liquid water plumes erupting from Saturn''s icy moon Enceladus constituted a geological anomaly that dramatically altered models of planetary habitability.', 'Lesson 2', 2, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anonymity', '/ˌænəˈnɪməti/', 'n.', 'Tình trạng ẩn danh, tính chất vô danh', 'Fearing corporate retribution from the pharmaceutical manufacturer, the clinical trial whistleblower insisted on absolute anonymity when delivering internal safety reports to federal regulators.', 'Lesson 2', 2, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anonymous', '/əˈnɑːnəməs/', 'adj.', 'Ẩn danh, nặc danh, không rõ tên tuổi', 'Published in 1776 under an anonymous byline, Thomas Paine’s radical pamphlet Common Sense galvanized colonial colonists toward an irrevocable declaration of independence.', 'Lesson 2', 2, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antagonism', '/ænˈtæɡənɪzəm/', 'n.', 'Sự thù địch, sự đối kháng lẫn nhau', 'The persistent geopolitical antagonism between the two maritime superpowers transformed minor territorial disputes in the South Pacific into potential flashpoints for global conflict.', 'Lesson 2', 2, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antecede', '/ˌæntɪˈsiːd/', 'v.', 'Xảy ra trước, đi trước về thời gian hoặc thứ tự', 'Geological evidence confirms that single-celled cyanobacteria antecede complex multicellular life by billions of years, gradually oxygenating the primordial terrestrial atmosphere.', 'Lesson 2', 2, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antecedents', '/ˌæntɪˈsiːdənts/', 'n.', 'Tiền đề lịch sử, lai lịch tổ tiên', 'Constitutional scholars trace the intellectual antecedents of the American doctrine of checks and balances directly to Montesquieu’s seminal treatise The Spirit of the Laws.', 'Lesson 2', 2, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antediluvian', '/ˌæntidɪˈluːviən/', 'adj.', 'Cổ xưa, lỗi thời, lạc hậu', 'Critics argued that the institution''s antediluvian governance structure, conceived in an era before digital communication, was incapable of addressing contemporary financial crimes.', 'Lesson 3', 3, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anthem', '/ˈænθəm/', 'n.', 'Bài ca ngợi, bài quốc ca', 'During the civil rights marches of the 1960s, the spiritual ballad evolved into a defiant anthem that unified demonstrators across racial and generational lines.', 'Lesson 3', 3, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anthology', '/ænˈθɑːlədʒi/', 'n.', 'Tuyển tập văn học, tuyển tập tác phẩm nghệ thuật', 'The university press released an authoritative anthology of Harlem Renaissance poetry, shedding light on previously neglected female authors who shaped early modernist aesthetics.', 'Lesson 3', 3, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anthropocentric', '/ˌænθrəpoʊˈsɛntrɪk/', 'adj.', 'Lấy con người làm trung tâm', 'Environmental philosophers criticize anthropocentric worldviews for treating nature purely as an extractive resource rather than an intricate system of interdependent organisms.', 'Lesson 3', 3, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anthropoid', '/ˈænθrəpɔɪd/', 'adj.', 'Dạng người, giống người', 'Fossilized cranial fragments unearthed in the Rift Valley provided crucial clues regarding the evolutionary divergence of early anthropoid primates.', 'Lesson 3', 3, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anthropologist', '/ˌænθrəˈpɑːlədʒɪst/', 'n.', 'Nhà nhân chủng học', 'Immersing herself within the remote pastoralist community, the cultural anthropologist documented how oral genealogies preserve kinship structures across successive generations.', 'Lesson 3', 3, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anthropomorphic', '/ˌænθrəpəˈmɔːrfɪk/', 'adj.', 'Nhân hóa, mang đặc điểm của con người', 'While ancient mythologies frequently attributed anthropomorphic emotions like jealousy and wrath to celestial deities, modern ethologists caution against projecting human motivations onto animal behavior.', 'Lesson 3', 3, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'anticlimax', '/ˌæntiˈklaɪmæks/', 'n.', 'Sự hụt hẫng, đoạn kết gây thất vọng sau kịch tính', 'After weeks of sensational media buildup surrounding the clandestine summit, the non-binding, vague joint communique felt like a profound anticlimax to political observers.', 'Lesson 3', 3, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antidote', '/ˈæntidoʊt/', 'n.', 'Thuốc giải độc, biện pháp khắc phục, liều thuốc hóa giải', 'Scholars of democratic theory argue that a vigilant, well-funded independent press serves as the most effective antidote to institutional corruption.', 'Lesson 3', 3, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antipathy', '/ænˈtɪpəθi/', 'n.', 'Ác cảm, sự căm ghét sâu sắc', 'The diplomat''s longstanding antipathy toward multilateral treaties complicated negotiations, threatening to derail the delicate ceasefire agreement.', 'Lesson 3', 3, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antiquated', '/ˈæntɪkweɪtɪd/', 'adj.', 'Cũ kỹ, lỗi thời, cổ lỗ sĩ', 'The municipal transit authority struggled to prevent recurring delays because its antiquated signaling infrastructure relied on electromechanical relays dating back to the 1940s.', 'Lesson 3', 3, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antiseptic', '/ˌæntiˈsɛptɪk/', 'adj.', 'Khử trùng, vô trùng', 'Joseph Lister''s revolutionary insistence on applying carbolic acid as an antiseptic agent drastically curtailed postoperative infections in Victorian hospitals.', 'Lesson 3', 3, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'antithesis', '/ænˈtɪθəsɪs/', 'n.', 'Sự tương phản, mặt đối lập trực tiếp, phép đối chọi', 'The candidate presented his modest agrarian background as the absolute antithesis of the cosmopolitan elitism embodied by his political rival.', 'Lesson 3', 3, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apathy', '/ˈæpəθi/', 'n.', 'Sự thờ ơ, lãnh đạm, vô cảm', 'Civic leaders warned that widespread voter apathy among younger demographics posed a graver peril to democratic legitimacy than active partisanship.', 'Lesson 3', 3, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ape', '/eɪp/', 'v.', 'Bắt chước, nhại lại một cách ngô nghê', 'Early provincial portraitists frequently sought to ape the grandiose European court style, producing stiff canvases that lacked the psychological depth of the masters.', 'Lesson 3', 3, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aperture', '/ˈæpərtʃər/', 'n.', 'Khe hở, lỗ hở, khẩu độ thấu kính', 'By narrowing the optical aperture of the telescope, astronomers minimized peripheral diffraction and sharpened the resolution of distant binary stars.', 'Lesson 3', 3, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apex', '/ˈeɪpɛks/', 'n.', 'Đỉnh cao, tột đỉnh, điểm cao nhất', 'Reaching the apex of her architectural career, she was commissioned to design the national capitol building, synthesizing neoclassical elegance with modern structural engineering.', 'Lesson 3', 3, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aphasia', '/əˈfeɪʒə/', 'n.', 'Chứng mất ngôn ngữ do tổn thương não', 'Following a severe stroke in the left frontal lobe, the patient developed Broca''s aphasia, retaining the ability to comprehend spoken dialogue but struggling to articulate coherent sentences.', 'Lesson 3', 3, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aphorism', '/ˈæfərɪzəm/', 'n.', 'Cách ngôn, châm ngôn ngắn gọn súc tích', 'Benjamin Franklin''s Poor Richard''s Almanack gained lasting renown by distilling complex virtues of frugality and industriousness into memorable aphorisms.', 'Lesson 3', 3, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apiary', '/ˈeɪpiˌɛri/', 'n.', 'Khu nuôi ong, vườn tổ ong', 'To investigate colony collapse disorder, agricultural researchers installed monitoring sensors throughout an experimental apiary to track hive temperature and worker bee foraging patterns.', 'Lesson 3', 3, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aplomb', '/əˈplɑːm/', 'n.', 'Sự điềm tĩnh, tự tin, đĩnh đạc', 'Even under relentless interrogation by the legislative oversight committee, the defense minister maintained his aplomb, responding to each accusation with measured precision.', 'Lesson 3', 3, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apocalyptic', '/əˌpɑːkəˈlɪptɪk/', 'adj.', 'Mang tính chất tận thế, thảm họa diệt vong', 'Nineteenth-century Romantic literature often expressed apocalyptic visions of industrial civilization, depicting cities swallowed by blackened skies and unchecked mechanical greed.', 'Lesson 3', 3, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apocryphal', '/əˈpɑːkrɪfəl/', 'adj.', 'Không có thật, ngụy tạo, nghi vấn về tính xác thực', 'Historians have concluded that the charming anecdote about George Washington cutting down the cherry tree is largely apocryphal, fabricated by an early biographer to illustrate filial piety.', 'Lesson 3', 3, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apogee', '/ˈæpədʒiː/', 'n.', 'Đỉnh cao, thời kỳ hoàng kim, điểm cực đại', 'The Pax Romana represented the apogee of Roman imperial administration, during which extensive trade networks flourished under a unified legal code.', 'Lesson 3', 3, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apolitical', '/ˌeɪpəˈlɪtɪkəl/', 'adj.', 'Phi chính trị, không màng chính trị', 'Despite operating in an increasingly polarized climate, the humanitarian relief agency remained resolutely apolitical, delivering medical aid strictly according to clinical need.', 'Lesson 3', 3, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apologist', '/əˈpɑːlədʒɪst/', 'n.', 'Người biện hộ, người bảo vệ quan điểm', 'As an outspoken apologist for laissez-faire capitalism, the economist authored treatises arguing that government deregulation inevitably spurs technological innovation.', 'Lesson 3', 3, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apostate', '/əˈpɑːsteɪt/', 'n.', 'Kẻ bỏ đạo, người bội giáo, người phản trắc', 'Branded an apostate after defecting from the authoritarian regime, the former party diplomat published a scathing memoir revealing state surveillance secrets.', 'Lesson 3', 3, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apotheosis', '/əˌpɑːθiˈoʊsɪs/', 'n.', 'Sự tôn sùng đỉnh điểm, sự thần thánh hóa, đỉnh cao mẫu mực', 'Critics hailed the maestro''s final symphony as the apotheosis of late Romantic composition, blending sweeping orchestral motifs with profound metaphysical themes.', 'Lesson 3', 3, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'appall', '/əˈpɔːl/', 'v.', 'Làm kinh hãi, làm kinh ngạc, gây phẫn nộ', 'The investigative report on squalid tenement housing continued to appall reform-minded legislators, catalyzing the passage of the first municipal building codes.', 'Lesson 3', 3, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apparatus', '/ˌæpəˈrætəs/', 'n.', 'Thiết bị, bộ máy, hệ thống máy móc chuyên dụng', 'To measure metabolic rates at high altitudes, physiologists designed a portable respiratory apparatus capable of recording oxygen uptake under extreme weather conditions.', 'Lesson 3', 3, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apparition', '/ˌæpəˈrɪʃən/', 'n.', 'Bóng ma, ảo ảnh, hiện tượng ma quái', 'In Shakespeare’s Macbeth, the bloody apparition of Banquo disrupts the royal banquet, serving as an external manifestation of the usurper''s tormented conscience.', 'Lesson 3', 3, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'appease', '/əˈpiːz/', 'v.', 'Nhân nhượng, xoa dịu, làm nguôi giận', 'Hoping to appease the militant faction threatening to fracture the parliamentary coalition, the prime minister conceded substantial control over the regional security portfolio.', 'Lesson 3', 3, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'appellation', '/ˌæpəˈleɪʃən/', 'n.', 'Tên gọi, danh xưng, danh hiệu', 'Earned through his uncompromising rhetoric on the senate floor, the appellation of ''the Great Compromiser'' clung to Henry Clay throughout his legislative career.', 'Lesson 3', 3, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'append', '/əˈpɛnd/', 'v.', 'Đính kèm, gắn thêm, viết thêm vào cuối', 'The legal counsel decided to append an explanatory codicil to the draft treaty to clarify ambiguities regarding territorial water jurisdiction.', 'Lesson 3', 3, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apprehension', '/ˌæprɪˈhɛnʃən/', 'n.', 'Sự lo âu, mối e ngại; sự lĩnh hội, sự bắt giữ', 'A palpable sense of apprehension gripped the coastal residents as meteorological buoys reported wind speeds exceeding Category 5 thresholds.', 'Lesson 3', 3, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apprenticeship', '/əˈprɛntɪsʃɪp/', 'n.', 'Thời gian học việc, sự tập sự nghề', 'Before establishing his own renowned printing press in Philadelphia, Benjamin Franklin endured a rigorous apprenticeship under his older brother in Boston.', 'Lesson 3', 3, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apprise', '/əˈpraɪz/', 'v.', 'Thông báo, báo cho biết', 'The intelligence liaison met secretly with the prime minister each dawn to apprise the administration of covert troop movements along the contested border.', 'Lesson 3', 3, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'approbation', '/ˌæprəˈbeɪʃən/', 'n.', 'Sự tán thành, sự chấp thuận, lời ngợi khen', 'The young architect''s unconventional museum design earned unanimous approbation from the royal commission, defying predictions that traditionalists would veto it.', 'Lesson 3', 3, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'appropriate', '/əˈproʊprieɪt/', 'v.', 'Chiếm đoạt, chiếm dụng làm của riêng', 'During wartime occupation, military commanders often move to appropriate civilian rail networks and fuel depots for strategic logistics.', 'Lesson 3', 3, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apropos', '/ˌæprəˈpoʊ/', 'adj.', 'Thích hợp, đúng lúc, thích đáng', 'The professor introduced a timely historical analogy, noting that Thucydides'' insights into geopolitical rivalry were remarkably apropos to contemporary foreign relations.', 'Lesson 3', 3, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aptitude', '/ˈæptɪtuːd/', 'n.', 'Năng khiếu, tố chất, khả năng bẩm sinh', 'From an early age, Ada Lovelace demonstrated an astonishing aptitude for analytical mathematics, enabling her to formulate the first algorithmic sequence for Babbage''s engine.', 'Lesson 3', 3, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aquatic', '/əˈkwætɪk/', 'adj.', 'Sống dưới nước, thủy sinh', 'Agricultural runoff containing synthetic fertilizers triggered severe eutrophication, depleting dissolved oxygen and suffocating delicate aquatic flora and fauna.', 'Lesson 3', 3, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aquiline', '/ˈækwɪlaɪn/', 'adj.', 'Khoằm như mỏ đại bàng, có hình dáng chim ưng', 'Roman portrait busts often emphasized an aquiline nose and a sharp jawline to convey aristocratic authority and martial determination.', 'Lesson 3', 3, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arable', '/ˈærəbəl/', 'adj.', 'Có thể trồng trọt được, màu mỡ canh tác được', 'Over centuries of intensive irrigation, progressive soil salinization rendered formerly arable alluvial plains unsuitable for grain production.', 'Lesson 3', 3, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arbiter', '/ˈɑːrbɪtər/', 'n.', 'Người phán xử, trọng tài phân xử', 'As the Supreme Court evolved into the final arbiter of constitutional intent, its rulings fundamentally reshaped federalist balances of power throughout the twentieth century.', 'Lesson 3', 3, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arbitrary', '/ˈɑːrbɪtrɛri/', 'adj.', 'Tùy tiện, độc đoán, chuyên quyền', 'Enlightenment thinkers vehemently denounced monarchical absolutism, arguing that citizens should be governed by systematic laws rather than the arbitrary decrees of a sovereign.', 'Lesson 3', 3, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'application', '/ˌæplɪˈkeɪʃən/', 'n.', 'Sự ứng dụng, tính thực tiễn, sự chuyên tâm', 'While theoretical quantum mechanics initially seemed abstract, its practical application in semiconductor engineering revolutionized modern computing.', 'Lesson 3', 3, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apposite', '/ˈæpəzɪt/', 'adj.', 'Thích hợp, đúng lúc, xác đáng', 'In his dissenting opinion, the jurist quoted an apposite passage from the Federalist Papers to demonstrate that the majority ruling contradicted the Framers'' original intent.', 'Lesson 3', 3, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'appraise', '/əˈpreɪz/', 'v.', 'Đánh giá, định giá, thẩm định phẩm chất', 'Before the museum board committed public endowments to purchase the disputed canvas, independent curators were summoned to rigorously appraise its provenance and physical condition.', 'Lesson 3', 3, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'appreciate', '/əˈpriːʃieɪt/', 'v.', 'Đánh giá cao, hiểu rõ giá trị; gia tăng giá trị', 'Economists observed that while consumer electronics depreciate rapidly due to technological obsolescence, scarce urban real estate tends to appreciate consistently over economic cycles.', 'Lesson 3', 3, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'apprehend', '/ˌæprɪˈhend/', 'v.', 'Bắt giữ; lĩnh hội, thấu hiểu', 'Philosophers have long debated whether human consciousness can truly apprehend the fundamental nature of time, or merely perceive its fleeting manifestations.', 'Lesson 3', 3, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'asinine', '/ˈæsɪnaɪn/', 'adj.', 'Ngu ngốc, ngớ ngẩn, vô nghĩa', 'The editorial condemned the municipal council''s decision to demolish the historic library as an asinine blunder that sacrificed irreplaceable heritage for short-term parking revenue.', 'Lesson 3', 3, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arbitrator', '/ˈɑːrbɪtreɪtər/', 'n.', 'Trọng tài, người phân xử', 'When negotiations between the steelworkers'' union and management deadlocked, both parties agreed to submit their grievances to a neutral federal arbitrator.', 'Lesson 3', 3, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arboretum', '/ˌɑːrbəˈriːtəm/', 'n.', 'Vườn ươm cây, vườn bách thảo cây gỗ', 'Ecologists at the university''s arboretum collected seed specimens from endangered temperate hardwoods to bolster ex-situ conservation efforts.', 'Lesson 3', 3, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arcade', '/ɑːrˈkeɪd/', 'n.', 'Mái vòm cuốn, dãy hành lang vòm', 'Sunlight filtered through the high stone arches of the medieval arcade, illuminating the cloister walk where generations of scholars had paced in contemplation.', 'Lesson 3', 3, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arcane', '/ɑːrˈkeɪn/', 'adj.', 'Huyền bí, bí truyền, ít người hiểu', 'Decoding the statutory framework required navigating an impenetrable thicket of arcane tax regulations that even seasoned corporate accountants struggled to interpret.', 'Lesson 3', 3, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'archaeology', '/ˌɑːrkiˈɑːlədʒi/', 'n.', 'Khảo cổ học', 'Advances in satellite lidar imaging have revolutionized maritime archaeology, allowing researchers to pinpoint submerged Bronze Age settlements without disturbing fragile seabed sediments.', 'Lesson 3', 3, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'archaic', '/ɑːrˈkeɪɪk/', 'adj.', 'Cổ xưa, lỗi thời', 'Legal scholars argued that the eighteenth-century maritime statute relied on archaic terminology that created unnecessary ambiguity in modern commercial disputes.', 'Lesson 3', 3, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'archetype', '/ˈɑːrkɪtaɪp/', 'n.', 'Hình mẫu nguyên thủy, nguyên mẫu điển hình', 'Literary theorists identify the wandering exile as an enduring archetype that surfaces across cultural traditions, from Homeric epics to contemporary diaspora fiction.', 'Lesson 3', 3, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'archipelago', '/ˌɑːrkɪˈpeləɡoʊ/', 'n.', 'Quần đảo', 'Geographic isolation among the volcanic islands of the Galápagos archipelago fostered accelerated speciation, providing Charles Darwin with pivotal evidence for natural selection.', 'Lesson 3', 3, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'archives', '/ˈɑːrkaɪvz/', 'n.', 'Kho lưu trữ, tài liệu lưu trữ lịch sử', 'Sifting through centuries of diplomatic dispatches in the national archives, the biographer uncovered unredacted correspondence that overturned the accepted narrative of the treaty.', 'Lesson 3', 3, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ardent', '/ˈɑːrdnt/', 'adj.', 'Nồng nhiệt, cuồng nhiệt, tha thiết', 'An ardent champion of civil liberties, Frederick Douglass wielded oratorical power to galvanize abolitionist sentiment and demand immediate emancipation.', 'Lesson 3', 3, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arduous', '/ˈɑːrdʒuəs/', 'adj.', 'Gian khổ, gay go, đòi hỏi nhiều nỗ lực', 'The exploratory expedition embarked on an arduous trek across glaciated mountain passes, contending with subzero blizzards and dwindling rations.', 'Lesson 3', 3, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aria', '/ˈɑːriə/', 'n.', 'Khúc độc ca trong nhạc kịch opera', 'The soprano concluded the tragic third act of the opera with a haunting aria that captured the heroine''s despair and held the concert hall in spellbound silence.', 'Lesson 3', 3, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arid', '/ˈærɪd/', 'adj.', 'Khô cằn, cằn cỗi', 'Xerophytic succulents have evolved specialized water-storing tissues and waxy cuticles to minimize transpiration across the arid expanses of the Atacama Desert.', 'Lesson 3', 3, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aristocracy', '/ˌærɪˈstɑːkrəsi/', 'n.', 'Tầng lớp quý tộc, giới quý tộc', 'The French Revolution fundamentally eroded the hereditary privileges of the landed aristocracy, dismantling the feudal estate system in favor of civic egalitarianism.', 'Lesson 3', 3, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'armada', '/ɑːrˈmɑːdə/', 'n.', 'Hạm đội chiến thuyền', 'Severe Atlantic tempests decimated the Spanish armada before it could mount an invasion of the English coast, altering naval supremacy throughout Western Europe.', 'Lesson 3', 3, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aromatic', '/ˌærəˈmætɪk/', 'adj.', 'Thơm nồng, có mùi hương đặc trưng', 'Centuries of maritime commerce flourished as merchant fleets transported aromatic spices such as clove, cinnamon, and nutmeg from distant Southeast Asian archipelagos to European ports.', 'Lesson 3', 3, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arousal', '/əˈraʊzl/', 'n.', 'Sự kích thích, trạng thái hưng phấn hoặc tỉnh táo', 'Neurobiological research indicates that abrupt environmental threats trigger autonomic arousal, elevating heart rates and mobilizing glucose stores for immediate physical response.', 'Lesson 3', 3, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arraign', '/əˈreɪn/', 'v.', 'Luận tội, đưa ra xét xử trước tòa', 'Federal magistrates moved to formally arraign the executive on multiple counts of wire fraud, unsealing an indictment that alleged decades of systemic embezzlement.', 'Lesson 3', 3, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'array', '/əˈreɪ/', 'n.', 'Dãy, mảng, sự sắp đặt ấn tượng', 'The observatory commissioned an expansive array of radio antennas designed to detect faint electromagnetic emissions originating from the dawn of the cosmic epoch.', 'Lesson 3', 3, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arrears', '/əˈrɪrz/', 'n.', 'Tiền nợ đọng, các khoản nợ quá hạn', 'Burdened by plunging commodity prices and punitive tariffs, the debtor republic fell hopelessly into arrears on its international bond payments.', 'Lesson 3', 3, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arrest', '/əˈrest/', 'v.', 'Ngăn chặn, làm ngừng trệ; bắt giữ', 'Timely administration of experimental therapeutic antibodies managed to arrest tumor proliferation, halting cellular division before metastasis could occur.', 'Lesson 3', 3, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arrogance', '/ˈærəɡəns/', 'n.', 'Sự kiêu ngạo, tính ngạo mạn', 'In classical Athenian drama, the protagonist''s overweening arrogance—known as hubris—inevitably incurs divine retribution and brings ruin upon the royal household.', 'Lesson 3', 3, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arroyo', '/əˈrɔɪoʊ/', 'n.', 'Lòng suối cạn, mương khô vùng bán khô hạn', 'A sudden cloudburst over the dry plateau transformed the sunbaked arroyo into a violent torrent of muddy runoff within minutes.', 'Lesson 3', 3, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'arsenal', '/ˈɑːrsənl/', 'n.', 'Kho vũ khí, nguồn tài nguyên dự trữ', 'In their battle against antimicrobial resistance, synthetic biologists are expanding the medical arsenal by engineering phage-derived enzymes that pierce bacterial biofilms.', 'Lesson 3', 3, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'articulate', '/ɑːrˈtɪkjuleɪt/', 'v.', 'Diễn đạt lưu loát, bày tỏ rõ ràng; phát âm rành mạch', 'In her landmark manifesto, the philosopher sought to articulate a coherent framework of rights that reconciled personal autonomy with communal obligations.', 'Lesson 3', 3, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'artifact', '/ˈɑːrtɪfækt/', 'n.', 'Hiện vật khảo cổ, cổ vật', 'Microscopic analysis of the Neolithic obsidian artifact revealed microscopic plant residues, demonstrating that early hunter-gatherers engaged in deliberate grain cultivation.', 'Lesson 3', 3, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'artifice', '/ˈɑːrtɪfɪs/', 'n.', 'Mưu mẹo, mưu xảo, mánh khóe khôn khéo', 'The veteran diplomat saw straight through the ambassador''s suave artifice, discerning that the non-aggression proposal was merely a calculated tactic to delay military mobilization.', 'Lesson 3', 3, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'artisan', '/ˈɑːrtəzn/', 'n.', 'Nghệ nhân, thợ thủ công lành nghề', 'Long before factory assembly lines standardized production, every bespoke timepiece was crafted by a master artisan who individually calibrated each cog and escapement.', 'Lesson 3', 3, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'artless', '/ˈɑːrtləs/', 'adj.', 'Chân thật, chất phác, không mưu mô', 'The diarist''s artless prose possessed a direct, unaffected sincerity that conveyed the emotional reality of wartime rationing far more movingly than rhetorical speeches.', 'Lesson 3', 3, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ascendancy', '/əˈsendənsi/', 'n.', 'Uy thế, vị thế thống trị, quyền chi phối', 'During the fifth century BCE, the maritime ascendancy of the Delian League established Athens as the unquestioned hegemon of the Aegean basin.', 'Lesson 3', 3, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ascertain', '/ˌæsərˈteɪn/', 'v.', 'Xác minh, tìm hiểu cho chắc chắn', 'Epidemiologists traced contact networks across three provinces to ascertain the initial source of transmission during the early weeks of the outbreak.', 'Lesson 3', 3, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ascetic', '/əˈsetɪk/', 'adj.', 'Khổ hạnh, khắc khổ', 'Rejecting the opulent comforts of his noble birth, Prince Siddhartha adopted an ascetic discipline of fasting and meditation beneath the Bodhi tree.', 'Lesson 3', 3, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ascribe', '/əˈskraɪb/', 'v.', 'Gán cho, quy cho', 'Pioneering climatologists ascribe accelerating ice-sheet detachment to the intrusion of warming circumpolar deep water beneath Antarctic ice shelves.', 'Lesson 3', 3, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aseptic', '/eɪˈseptɪk/', 'adj.', 'Vô trùng, vô khuẩn', 'Joseph Lister revolutionized nineteenth-century hospital medicine by introducing aseptic surgical techniques that drastically reduced fatal postoperative septicemia.', 'Lesson 3', 3, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ashen', '/ˈæʃn/', 'adj.', 'Tái mét, xám như tro', 'Stunned by the unexpected collapse of the banking consortium, the finance minister emerged from the emergency cabinet meeting looking drawn and ashen.', 'Lesson 3', 3, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aspire', '/əˈspaɪər/', 'v.', 'Khao khát, hướng tới mục tiêu cao đẹp', 'Developing nations frequently aspire to diversify their industrial output, seeking to transition from agrarian reliance toward semiconductor manufacturing.', 'Lesson 3', 3, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assail', '/əˈseɪl/', 'v.', 'Tấn công dồn dập, chỉ trích dữ dội', 'Parliamentary critics continued to assail the deregulation bill, warning that stripping environmental oversight would cause irreversible ecological harm.', 'Lesson 3', 3, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assay', '/əˈseɪ/', 'v.', 'Phân tích định lượng, thử nghiệm hàm lượng', 'Using inductively coupled plasma mass spectrometry, the geochemists moved to assay the core samples for trace concentrations of platinum-group metals.', 'Lesson 3', 3, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assent', '/əˈsent/', 'n.', 'Sự ưng thuận, sự đồng ý, sự chuẩn y', 'Under the unwritten British constitution, a bill approved by both Houses of Parliament cannot acquire the force of statute until it receives the monarch''s formal assent.', 'Lesson 3', 3, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assert', '/əˈsɜːrt/', 'v.', 'Khẳng định, quả quyết, xác quyết', 'Revisionist historians assert that the economic stagnation of the era was driven primarily by monetary deflation rather than agricultural crop failure.', 'Lesson 3', 3, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assessment', '/əˈsesmənt/', 'n.', 'Sự đánh giá, sự ước định', 'The environmental agency published an exhaustive environmental impact assessment detailing how the proposed hydroelectric dam would fragment riverine spawning grounds.', 'Lesson 3', 3, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assiduous', '/əˈsɪdʒuəs/', 'adj.', 'Cần mẫn, siêng năng, chuyên cần', 'Only through assiduous decipherment of faded papyrus fragments was the philologist able to reconstruct the lost stanzas of the Sapphic hymn.', 'Lesson 3', 3, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assimilate', '/əˈsɪməleɪt/', 'v.', 'Đồng hóa, tiếp thu và hòa nhập', 'Sociologists observed how successive waves of immigrants managed to assimilate into the urban workforce while steadfastly maintaining their religious institutions and native idioms.', 'Lesson 3', 3, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assuage', '/əˈsweɪdʒ/', 'v.', 'Làm dịu bớt, xoa dịu, làm nguôi ngoai', 'Seeking to assuage investor panic following the sudden liquidity crisis, the central bank governor pledged an unconditional guarantee on interbank deposits.', 'Lesson 3', 3, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assumption', '/əˈsʌmpʃn/', 'n.', 'Giả định, sự suy đoán chưa được chứng minh', 'The econometric model unravels if one challenges the foundational assumption that consumers possess complete transparency regarding future price trends.', 'Lesson 3', 3, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'assurance', '/əˈʃʊrəns/', 'n.', 'Lời cam đoan, sự bảo đảm; sự tự tin', 'Despite diplomatic assurances that military maneuvers were routine exercises, neighboring nations reinforced their border garrisons in anticipation of a potential incursion.', 'Lesson 3', 3, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'asteroid', '/ˈæstərɔɪd/', 'n.', 'Tiểu hành tinh', 'Spectroscopic data gathered by interplanetary probes suggest that the carbonaceous asteroid contains organic molecules dating back to the formation of the solar nebula.', 'Lesson 3', 3, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'astigmatism', '/əˈstɪɡmətɪzəm/', 'n.', 'Chứng loạn thị', 'Specialized corneal topography maps the irregular corneal curvature responsible for severe astigmatism, allowing surgeons to customize laser refractive corrections.', 'Lesson 3', 3, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'astral', '/ˈæstrəl/', 'adj.', 'Thuộc về các vì sao, thuộc tinh tú', 'Ancient navigators across the Polynesian archipelago relied on subtle astral alignments and ocean swells to traverse thousands of miles of open water.', 'Lesson 4', 4, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'astringent', '/əˈstrɪndʒənt/', 'adj.', 'Làm se da; sắc sảo, gay gắt', 'The essayist’s astringent critique of contemporary political discourse spared neither party, dissecting their empty rhetoric with surgical precision.', 'Lesson 4', 4, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'askance', '/əˈskæns/', 'adv.', 'Nghi ngờ, ngờ vực', 'Established physicists initially looked askance at the young researcher’s radical hypothesis, doubting that quantum coherence could persist at room temperature.', 'Lesson 4', 4, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'askew', '/əˈskjuː/', 'adj.', 'Nghiêng, xiên xẹo, lệch lạc', 'After the moderate tremor rattled the gallery, several Renaissance portraits hung noticeably askew against the marble walls.', 'Lesson 4', 4, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'asperity', '/æˈspɛrəti/', 'n.', 'Sự gay gắt, sự khắc nghiệt', 'Startled by the uncharacteristic asperity in the diplomat’s tone, the envoys recognized that formal negotiations had reached an impasse.', 'Lesson 4', 4, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aspirant', '/əˈspaɪərənt/', 'n.', 'Người có tham vọng, người khao khát vươn tới danh vọng', 'In Renaissance Florence, every aspirant to the master painters'' guild spent grueling years grinding pigments and copying classical sculpture.', 'Lesson 4', 4, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'astronomical', '/ˌæstrəˈnɒmɪkl/', 'adj.', 'Vô cùng lớn, khổng lồ; thuộc thiên văn học', 'Constructing the deep-space particle detector demanded an astronomical outlay of capital that necessitated cost-sharing among a dozen sovereign nations.', 'Lesson 4', 4, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'astute', '/əˈstjuːt/', 'adj.', 'Sắc sảo, tinh khôn, nhạy bén', 'An astute observer of constitutional jurisprudence, the legal scholar predicted the appellate court’s ruling long before deliberations concluded.', 'Lesson 4', 4, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'asunder', '/əˈsʌndər/', 'adv.', 'Rời ra từng mảnh, tan tác', 'The sectarian conflict tore the fragile parliamentary coalition asunder, plunging the republic into months of administrative paralysis.', 'Lesson 4', 4, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'asylum', '/əˈsaɪləm/', 'n.', 'Nơi tị nạn, sự bảo hộ chính trị', 'Facing arbitrary detention under the martial decree, the investigative journalist was forced to seek diplomatic asylum within a neutral embassy.', 'Lesson 4', 4, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'asymmetric', '/ˌeɪsɪˈmɛtrɪk/', 'adj.', 'Không đối xứng, bất cân xứng', 'Strategic analysts observed that the insurgent conflict represented an asymmetric engagement, pitting guerrilla agility against conventional mechanized armor.', 'Lesson 4', 4, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atavism', '/ˈætəvɪzəm/', 'n.', 'Sự lại giống, sự xuất hiện lại đặc tính tổ tiên', 'Paleontologists cited the occasional development of pelvic bones in modern baleen whales as a compelling morphological atavism pointing to terrestrial ancestors.', 'Lesson 4', 4, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atheistic', '/ˌeɪθiˈɪstɪk/', 'adj.', 'Vô thần, không tin vào thần linh', 'Radical Enlightenment materialists advanced an atheistic philosophy that rejected divine providence in favor of mechanistic determinism.', 'Lesson 4', 4, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atlas', '/ˈætləs/', 'n.', 'Tập bản đồ', 'The navigator consulted a leather-bound seventeenth-century maritime atlas to decipher the antiquated depictions of treacherous Atlantic shoals.', 'Lesson 4', 4, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atone', '/əˈtoʊn/', 'v.', 'Chuộc lỗi, đền bù tội lỗi', 'In an earnest effort to atone for past environmental destruction, the industrial manufacturer allocated half of its annual profits to wetland reforestation.', 'Lesson 4', 4, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atrocity', '/əˈtrɒsəti/', 'n.', 'Sự tàn bạo, tội ác ghê rợn', 'International war crimes tribunals meticulously documented every wartime atrocity to ensure that the commanding officers could be prosecuted under global treaties.', 'Lesson 4', 4, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atrophy', '/ˈætrəfi/', 'v.', 'Hao mòn, teo đi do không sử dụng', 'Without frequent exposure to challenging analytical tasks, a student''s capacity for complex mathematical reasoning can gradually atrophy.', 'Lesson 4', 4, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'attain', '/əˈteɪn/', 'v.', 'Đạt được, giành được', 'Only after decades of rigorous experimental trial did the research team attain the stable thermonuclear containment required for clean energy.', 'Lesson 4', 4, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'attentive', '/əˈtɛntɪv/', 'adj.', 'Chăm chú, lưu tâm, chu đáo', 'The master watchmaker remained exquisitely attentive to the minute friction between the interlocking brass escapement gears.', 'Lesson 4', 4, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'attenuate', '/əˈtɛnjuˌeɪt/', 'v.', 'Làm yếu đi, làm giảm bớt cường độ', 'Coastal wetlands and mangrove fringes serve as crucial buffers that attenuate the kinetic force of incoming tsunami waves.', 'Lesson 4', 4, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'attest', '/əˈtɛst/', 'v.', 'Chứng thực, làm chứng cho', 'The deep wear patterns on the excavated stone grindstones attest to centuries of continuous grain processing by Neolithic villagers.', 'Lesson 4', 4, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'attribute', '/əˈtrɪbjuːt/', 'v.', 'Quy cho, gán cho là do', 'Epidemiologists attribute the precipitous decline in infant mortality during the nineteenth century primarily to municipal sanitation reforms.', 'Lesson 4', 4, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'attrition', '/əˈtrɪʃn/', 'n.', 'Sự hao mòn dần, sự tiêu hao sinh lực', 'The protracted trench warfare along the Western Front devolved into an agonizing campaign of attrition that decimated an entire generation.', 'Lesson 4', 4, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'atypical', '/ˌeɪˈtɪpɪkl/', 'adj.', 'Không điển hình, khác thường', 'Because the stellar spectra displayed atypical absorption spikes, the astrophysicists suspected that an unseen exoplanet was occluding the star.', 'Lesson 4', 4, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'audacious', '/ɔːˈdeɪʃəs/', 'adj.', 'Táo bạo, liều lĩnh, quả cảm', 'Galileo’s audacious defense of heliocentrism openly challenged the prevailing Ptolemaic orthodoxy enforced by the Roman Inquisition.', 'Lesson 4', 4, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'audit', '/ˈɔːdɪt/', 'n.', 'Sự kiểm toán, cuộc kiểm tra sổ sách kế toán', 'An independent regulatory audit uncovered pervasive accounting discrepancies that had artificially inflated the bank’s reported quarterly earnings.', 'Lesson 4', 4, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'auditory', '/ˈɔːdətɔːri/', 'adj.', 'Thuộc thính giác', 'Marine biologists discovered that anthropogenic sonar noise causes acute auditory trauma in deep-diving cetaceans, disrupting their echolocation.', 'Lesson 4', 4, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'augment', '/ɔːɡˈmɛnt/', 'v.', 'Gia tăng, tăng cường, bổ sung', 'To augment their sparse domestic agricultural yields, early industrial city-states established extensive grain import networks across the Mediterranean.', 'Lesson 4', 4, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'augury', '/ˈɔːɡjəri/', 'n.', 'Điềm báo, sự báo trước', 'In classical antiquity, Roman magistrates rarely undertook major military campaigns without first consulting diviners to interpret augury from animal entrails.', 'Lesson 4', 4, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'august', '/ɔːˈɡʌst/', 'adj.', 'Uy nghiêm, trang trọng, khả kính', 'The newly inaugurated chancellor addressed the august assembly of Nobel laureates and university provosts with heartfelt humility.', 'Lesson 4', 4, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aureole', '/ˈɔːriˌoʊl/', 'n.', 'Hào quang, quầng sáng', 'During total solar eclipses, the lunar disc momentarily obscures the photosphere, unveiling the sun''s ghostly aureole shimmering against the darkness.', 'Lesson 4', 4, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'auroral', '/ɔːˈrɔːrəl/', 'adj.', 'Thuộc về cực quang, rực rỡ như rạng đông', 'Coronal mass ejections from the sun triggered breathtaking auroral displays that bathed the subpolar tundra in ribbons of vibrant luminescence.', 'Lesson 4', 4, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'auspicious', '/ɔːˈspɪʃəs/', 'adj.', 'Thuận lợi, có điềm lành, hứa hẹn may mắn', 'The ratification of the non-proliferation treaty was universally lauded as an auspicious milestone for postwar multilateral diplomacy.', 'Lesson 4', 4, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'austere', '/ɔːˈstɪr/', 'adj.', 'Khắc khổ, mộc mạc, nghiêm nghị', 'The monastic community embraced an austere lifestyle, deliberately eschewing material comforts in favor of silent meditation and labor.', 'Lesson 4', 4, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'authenticate', '/ɔːˈθɛntɪkeɪt/', 'v.', 'Xác thực, chứng thực tính chân thật', 'Through forensic ink dating and provenance analysis, the museum conservator was able to authenticate the unsigned manuscript as an early work by Mary Shelley.', 'Lesson 4', 4, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'authoritarian', '/əˌθɔːrəˈtɛriən/', 'adj.', 'Độc đoán, chuyên chế', 'Political theorists caution that when a government systematically curtails judicial independence and suppresses free assembly, it veers dangerously toward authoritarian governance.', 'Lesson 4', 4, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'authoritative', '/əˈθɔːrətətɪv/', 'adj.', 'Có thẩm quyền, chuẩn xác, đáng tin cậy', 'Historians still consider Edward Gibbon’s monumental chronicle to be an authoritative, if stylistically idiosyncratic, treatise on late Roman decline.', 'Lesson 4', 4, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'autocratic', '/ˌɔːtəˈkrætɪk/', 'adj.', 'Độc tài, chuyên quyền, toàn quyền', 'The monarch’s autocratic dissolution of parliament sparked widespread civilian defiance, precipitating a constitutional crisis that reshaped British democracy.', 'Lesson 4', 4, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'automaton', '/ɔːˈtɒmətən/', 'n.', 'Người máy, cỗ máy tự động, người hành động máy móc', 'Eighteenth-century inventor Jacques de Vaucanson stunned the European nobility by exhibiting an ornate mechanical automaton capable of playing intricate melodies on a flute.', 'Lesson 4', 4, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'autonomous', '/ɔːˈtɒnəməs/', 'adj.', 'Tự trị, độc lập, tự chủ', 'Deep-sea exploration often requires autonomous underwater submersibles capable of charting uncharted oceanic trenches without real-time human guidance.', 'Lesson 4', 4, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'autopsy', '/ˈɔːtɒpsi/', 'n.', 'Sự khám nghiệm tử thi', 'The coroner’s meticulous autopsy confirmed that the deceased diplomat had ingested lethal doses of arsenic several hours before collapsing.', 'Lesson 4', 4, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'auxiliary', '/ɔːɡˈzɪljəri/', 'adj.', 'Phụ trợ, bổ trợ, dự phòng', 'When severe lightning crippled the regional power grid, the metropolitan hospital immediately transitioned to auxiliary diesel generators to preserve neonatal life-support systems.', 'Lesson 4', 4, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avalanche', '/ˈævəlæntʃ/', 'n.', 'Tuyết lở, sự dồn dập ồ ạt', 'The sudden collapse of the major investment bank triggered an avalanche of panic across European credit markets, wiping out billions in equity overnight.', 'Lesson 4', 4, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avarice', '/ˈævərɪs/', 'n.', 'Lòng tham lam, tính hám của', 'Gilded Age muckrakers relentlessly castigated the unrestrained avarice of industrial monopolists who hoarded vast fortunes while suppressing workers'' wages.', 'Lesson 4', 4, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avenge', '/əˈvɛndʒ/', 'v.', 'Báo thù, rửa hận', 'Consumed by an obsessive drive to avenge his comrades'' execution, the revolutionary commander rejected all offers of ceasefire and resumed his guerrilla offensive.', 'Lesson 4', 4, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'averse', '/əˈvɜːrs/', 'adj.', 'Không thích, ác cảm, ngần ngại', 'Risk-averse pension fund trustees favored conservative sovereign bonds over volatile equities, prioritizing capital preservation over speculative yields.', 'Lesson 4', 4, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aversion', '/əˈvɜːrʒn/', 'n.', 'Sự ác cảm, sự ghét bỏ', 'Behavioral psychologists demonstrate that conditioned gustatory aversion develops rapidly in mammals as an evolutionary defense against ingesting toxic vegetation.', 'Lesson 4', 4, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avert', '/əˈvɜːrt/', 'v.', 'Ngăn chặn, ngoảnh đi, phòng tránh', 'Swift diplomatic de-escalation by multilateral mediators managed to avert an imminent border clash between the two nuclear-armed states.', 'Lesson 4', 4, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'aviary', '/ˈeɪviɛri/', 'n.', 'Chuồng chim lớn, khu nuôi chim', 'The zoological foundation constructed a climate-controlled aviary spanning five acres to safeguard breeding pairs of critically endangered tropical quetzals.', 'Lesson 4', 4, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avid', '/ˈævɪd/', 'adj.', 'Khao khát, say mê, tha thiết', 'An avid bibliophile and classical scholar, Thomas Jefferson amassed thousands of rare volumes that eventually formed the founding collection of the Library of Congress.', 'Lesson 4', 4, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avocation', '/ˌævoʊˈkeɪʃən/', 'n.', 'Sở thích phụ, nghề tay trái', 'Although he derived his steady income from a mundane post in the municipal land registry, his true passion was his avocation as an amateur entomologist, which found him traversing the Appalachian ridges every autumn to catalog elusive moth species.', 'Lesson 4', 4, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avow', '/əˈvaʊ/', 'v.', 'Tuyên bố công khai, thừa nhận thẳng thắn', 'Standing before the hostile parliamentary committee, the reformist senator refused to recant his earlier writings, choosing instead to avow his unwavering commitment to universal suffrage.', 'Lesson 4', 4, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'avuncular', '/əˈvʌŋkjələr/', 'adj.', 'Ân cần như chú bác, thân thiện và độ lượng', 'With his warm laughter, ready humor, and avuncular demeanor, the elder statesman possessed a rare gift for putting intimidated young diplomats at ease during tense multilateral summits.', 'Lesson 4', 4, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'awe', '/ɔː/', 'n.', 'Sự kính sợ, lòng tôn kính xen lẫn kinh ngạc', 'Gazing into the unfathomable depths of the oceanic trench through the submersible''s viewport, the oceanographers were hushed into profound awe by the eerie luminescence of undiscovered hydrothermal fauna.', 'Lesson 4', 4, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'awry', '/əˈraɪ/', 'adj.', 'Hỏng bét, chệch hướng ngoài dự tính', 'The military expedition went disastrously awry when unseasonal blizzards choked the mountain passes, cutting off the supply train and stranding the vanguard deep inside hostile territory.', 'Lesson 4', 4, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'axiom', '/ˈæksiəm/', 'n.', 'Tiên đề, chân lý hiển nhiên', 'Classical economics long operated on the foundational axiom that market participants behave as rational agents seeking to maximize their individual utility, a premise now vigorously challenged by behavioral scientists.', 'Lesson 4', 4, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'azure', '/ˈæʒər/', 'adj.', 'Xanh biếc như da trời quang đãng', 'As the morning fog burned away above the Aegean archipelago, the passengers looked out upon an azure expanse of sea that matched the flawless clarity of the Mediterranean summer sky.', 'Lesson 4', 4, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'babble', '/ˈbæbəl/', 'v.', 'Nói lảm nhảm, bập bẹ khó hiểu', 'In his delirium, the feverish cartographer began to babble disjointed phrases about subterranean caverns and lost rivers, startling the bedside physicians with his incoherent ramblings.', 'Lesson 4', 4, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bacchanalian', '/ˌbækəˈneɪliən/', 'adj.', 'Say sưa chè chén, thác loạn cuồng hoan', 'Puritan chroniclers of the early Massachusetts settlement sternly condemned May Day festivities around the Maypole, depicting the harmless dance as a bacchanalian revel that encouraged debauchery and lawlessness.', 'Lesson 4', 4, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'badger', '/ˈbædʒər/', 'v.', 'Làm phiền, mè nheo nài nỉ liên tục', 'Tenacious consumer advocates continued to badger regulatory officials with Freedom of Information requests until the agency finally released the withheld safety trials for the new pesticide.', 'Lesson 4', 4, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'badinage', '/ˌbædəˈnɑːʒ/', 'n.', 'Sự bông đùa, lời trêu đùa dí dỏm', 'Beneath the sparkling badinage and seemingly effortless repartée that charmed guests at the embassy reception, rival diplomats were subtly probing each other for geopolitical concessions.', 'Lesson 4', 4, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'baffle', '/ˈbæfəl/', 'v.', 'Làm bối rối, làm lúng túng khó hiểu', 'The sudden, synchronized collapse of ancient Bronze Age civilizations across the eastern Mediterranean continues to baffle historians, who have proposed everything from systemic drought to sudden barbarian incursions.', 'Lesson 4', 4, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bait', '/beɪt/', 'v.', 'Khiêu khích, chọc tức hoặc nhử mồi', 'During cross-examination, the cunning prosecutor attempted to bait the defendant into an angry outburst, knowing that a display of volatile temper would destroy his facade of mild innocence.', 'Lesson 4', 4, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'baleful', '/ˈbeɪlfəl/', 'adj.', 'Đe dọa tai ương, hiểm ác gở gắm', 'As the rival clan leaders converged in the castle courtyard to sign the uneasy armistice, they exchanged baleful glares that betrayed a lingering hunger for bloody retribution.', 'Lesson 4', 4, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'balk', '/bɔːk/', 'v.', 'Chùn bước, ngần ngại từ chối thực hiện', 'While most town councilors supported constructing the civic theater, fiscally conservative members began to balk when architectural revisions escalated the projected budget threefold.', 'Lesson 4', 4, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ballast', '/ˈbæləst/', 'n.', 'Đối trọng dằn thăng bằng, vật làm vững chắc', 'In eighteenth-century transatlantic trade, merchant ships returning from the West Indies without complete cargoes took aboard river stones and pig iron to serve as ballast, keeping the hulls stable against turbulent Atlantic swells.', 'Lesson 4', 4, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'balm', '/bɑːm/', 'n.', 'Thuốc xoa dịu, niềm an ủi vỗ về', 'To the shell-shocked veterans returning from the trenches of the Somme, the tranquil seclusion of the English countryside offered a spiritual balm that gradual medical treatments could not replicate.', 'Lesson 4', 4, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'balmy', '/ˈbɑːmi/', 'adj.', 'Êm dịu, ấm áp dễ chịu', 'A balmy evening breeze drifted off the gulf waters, carrying the sweet aroma of blooming jasmine and coaxing residents onto their verandas long after dusk had fallen.', 'Lesson 4', 4, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'banal', '/bəˈnæl/', 'adj.', 'Tầm thường, sáo rỗng thiếu độc đáo', 'Critics lamented that the novelist had abandoned the lyrical originality of her debut work in favor of a formulaic mystery saturated with banal tropes and predictable twists.', 'Lesson 4', 4, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bandy', '/ˈbændi/', 'v.', 'Bàn tán qua lại, đôi co lời lẽ', 'Partisan commentators on evening news broadcasts routinely bandy about inflammatory catchphrases without pausing to interrogate the intricate socio-economic facts behind the policy debate.', 'Lesson 4', 4, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bane', '/beɪn/', 'n.', 'Nguyên nhân nỗi khổ, tai họa đeo đẳng', 'The relentless encroaching of invasive kudzu vine has become the perennial bane of southern foresters, suffocating native oak saplings and blanketing whole woodland hillsides.', 'Lesson 4', 4, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bantering', '/ˈbæntərɪŋ/', 'adj.', 'Trêu đùa hóm hỉnh, đùa cợt nhẹ nhàng', 'The playwright infused the opening act with a brisk, bantering dialogue between the two estranged sisters, masking their simmering childhood resentments beneath sharp, witty barbs.', 'Lesson 4', 4, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'barb', '/bɑːrb/', 'n.', 'Lời mỉa mai châm chọc, ngạnh nhọn', 'Though couched in polite academic phraseology, the reviewer''s closing barb—questioning whether the historian had even consulted primary archives—inflicted severe damage on the author''s professional standing.', 'Lesson 4', 4, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bard', '/bɑːrd/', 'n.', 'Thi sĩ, người ngâm thơ sử thi', 'Before epic narratives were transcribed onto vellum, the Gaelic bard traveled from chieftain to chieftain, reciting genealogies and heroic ballads preserved solely through oral tradition.', 'Lesson 4', 4, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'baroque', '/bəˈroʊk/', 'adj.', 'Cầu kỳ hoa mỹ, phong cách Ba-rốc', 'The interior of the Austrian basilica was an extravagant masterpiece of baroque ornamentation, overwhelming the senses with swirling marble cherubs, trompe-l’œil ceiling frescoes, and heavy gold leaf.', 'Lesson 4', 4, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bestow', '/bɪˈstoʊ/', 'v.', 'Ban tặng, trao tặng vinh dự', 'In gratitude for the scholar’s lifetime spent cataloging indigenous dialects, the sovereign chose to bestow upon him the realm’s highest civilian order of merit.', 'Lesson 4', 4, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'betroth', '/bɪˈtroʊð/', 'v.', 'Hứa hôn, đính ước', 'In late medieval diplomacy, dynastic treaties frequently required a monarch to betroth his infant heir to a foreign princess, using the sacred promise of marriage to secure military non-aggression.', 'Lesson 4', 4, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'barrage', '/bəˈrɑːʒ/', 'n.', 'Loạt dồn dập, trận mưa tới tấp', 'Facing a relentless barrage of hostile inquiries from reporters regarding offshore tax shelters, the corporate spokesperson abruptly terminated the press conference.', 'Lesson 4', 4, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'barren', '/ˈbærən/', 'adj.', 'Cằn cỗi, trơ trụi không sinh sản', 'Centuries of ruthless deforestation and subsequent topsoil erosion converted the once lush Peloponnesian hillside into a barren landscape where only resilient thistle and scrub could survive.', 'Lesson 4', 4, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'barricade', '/ˈbærɪkeɪd/', 'n.', 'Chướng ngại vật, hàng rào chắn phòng thủ', 'Erecting an impromptu barricade of cobblestones, overturned wagons, and timber balks across the boulevard, the student revolutionaries braced themselves for the impending cavalry charge.', 'Lesson 4', 4, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'barterer', '/ˈbɑːrtərər/', 'n.', 'Người đổi chác hàng hóa, người giao thương không tiền mặt', 'Operating far beyond the frontiers of the empire where imperial mint was useless, the cunning barterer exchanged salt cakes and tempered iron blades for beaver pelts and medicinal roots.', 'Lesson 4', 4, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bask', '/bæsk/', 'v.', 'Phơi mình tận hưởng sự ấm áp, đắm mình trong vinh quang', 'Following the international symposium where her clean-energy breakthrough was unveiled, the physicist allowed herself a rare moment to bask in the unanimous acclaim of her colleagues.', 'Lesson 4', 4, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bastion', '/ˈbæstʃən/', 'n.', 'Thành trì vững chắc, pháo đài kiên cố', 'Throughout the upheaval of civil war, the secluded mountaintop monastery remained a steadfast bastion of classical literacy, diligently preserving ancient Greek manuscripts from destruction.', 'Lesson 4', 4, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bate', '/beɪt/', 'v.', 'Kìm nén, làm giảm bớt cường độ', 'Seeing that his harsh reproaches were only driving his grieving daughter further into isolation, the father resolved to bate his sternness and listen with gentle patience.', 'Lesson 4', 4, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bauble', '/ˈbɔːbəl/', 'n.', 'Đồ trang sức hào nhoáng rẻ tiền, vật trang trí vô giá trị', 'The stoic philosopher urged his disciples to despise the gilded court bauble and the fleeting insignia of worldly office, focusing instead upon the enduring wealth of the soul.', 'Lesson 4', 4, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bawdy', '/ˈbɔːdi/', 'adj.', 'Tục tĩu tếu táo, tiếu lâm dâm dã', 'In the rowdier scenes of Elizabethan tavern comedies, playwrights indulged in bawdy puns and ribald double entendres that delighted the boisterous groundlings in the pit.', 'Lesson 4', 4, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beam', '/biːm/', 'v.', 'Cười rạng rỡ, phát tín hiệu rạng ngời', 'Upon seeing her daughter walk across the stage to receive the university’s highest academic accolade, the matriarch could not help but beam with profound maternal pride.', 'Lesson 4', 4, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beatific', '/ˌbiːəˈtɪfɪk/', 'adj.', 'Phúc lạc rạng ngời, ngập tràn phúc lành', 'Even as the storm raged violently against the sanctuary windows, a beatific composure remained upon the countenance of the abbess as she continued her quiet evening prayers.', 'Lesson 4', 4, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beatitude', '/biˈætɪtuːd/', 'n.', 'Hạnh phúc tối thượng, phúc lành thiêng liêng', 'In Dante’s Paradiso, the blessed souls dwell in a state of celestial beatitude, experiencing an ecstatic communion that transcends mortal comprehension.', 'Lesson 4', 4, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bedizen', '/bɪˈdaɪzən/', 'v.', 'Trang điểm lòe loẹt, diện đồ diêm dúa', 'Satirizing the vanity of the nouveau riche, the Victorian novelist described how the pompous baroness loved to bedizen herself in gaudy silks and oversized imitation pearls for every public occasion.', 'Lesson 4', 4, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bedraggle', '/bɪˈdræɡəl/', 'v.', 'Làm lấm lem ướt sũng, làm nhếch nhác', 'The sudden thunderstorm threatened to bedraggle the velvet capes and feathered tricorn hats worn by the royal guard during the outdoor parade.', 'Lesson 4', 4, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beeline', '/ˈbiːlaɪn/', 'n.', 'Đường thẳng tắp, lộ trình ngắn nhất', 'The moment the dismissal bell rang on the final afternoon of term, triumphant schoolchildren made a frantic beeline for the village swimming pond.', 'Lesson 4', 4, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'befuddle', '/bɪˈfʌdəl/', 'v.', 'Làm bối rối hoang mang, làm mê muội đầu óc', 'The convoluted syntax and contradictory clauses of the nineteenth-century tax statute served only to befuddle ordinary merchants attempting to comply with its demands.', 'Lesson 4', 4, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beget', '/bɪˈɡɛt/', 'v.', 'Gây ra, sinh ra, làm nảy sinh', 'Historians of the Weimar Republic observed that punitive postwar reparations served only to beget deep societal resentment, which subsequently fostered violent ideological extremism.', 'Lesson 4', 4, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'begrudge', '/bɪˈɡrʌdʒ/', 'v.', 'Ghen tị tiếc rẻ, không cam lòng cho hưởng', 'Though the bitter rivals had contested every grant for decades, neither scientist could begrudge the other the Nobel recognition deserved for such rigorous immunological research.', 'Lesson 4', 4, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beguile', '/bɪˈɡaɪl/', 'v.', 'Quyến rũ mê hoặc, đánh lừa ngọt ngào', 'With melodic cadence and alluring promises of swift prosperity, the charlatan managed to beguile desperate villagers into investing their life savings in nonexistent gold mines.', 'Lesson 4', 4, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'behemoth', '/bɪˈhiːməθ/', 'n.', 'Quái vật khổng lồ, thế lực to lớn áp đảo', 'Small family-owned pharmacies across the nation found it impossible to compete with the wholesale pricing power of the multinational retail behemoth.', 'Lesson 4', 4, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'belabor', '/bɪˈleɪbər/', 'v.', 'Giải thích dông dài, nhắc đi nhắc lại quá mức', 'Conscious that his audience of experienced oncologists already understood tumor staging protocols, the keynote speaker refrained from belaboring basic concepts and focused directly on novel therapies.', 'Lesson 4', 4, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bogus', '/ˈboʊɡəs/', 'adj.', 'Giả mạo, không có thật', 'Archaeologists quickly identified the purported Phoenician tablet as a bogus artifact, pointing out that its modern chisel marks and anachronistic syntax betrayed a nineteenth-century forgery.', 'Lesson 4', 4, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'belated', '/bɪˈleɪtɪd/', 'adj.', 'Chậm trễ, muộn màng hơn dự tính', 'The government’s belated implementation of quarantine protocols failed to stem the contagion, as the pathogen had already infiltrated neighboring provinces weeks before.', 'Lesson 4', 4, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beleaguer', '/bɪˈliːɡər/', 'v.', 'Bao vây, quấy rối, dồn vào thế khó', 'A protracted maritime embargo continued to beleaguer the coastal republic, severing vital supply routes and exhausting its civilian reserves.', 'Lesson 5', 5, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'belie', '/bɪˈlaɪ/', 'v.', 'Gây ấn tượng sai lệch, mâu thuẫn với', 'Her composed, impassive demeanor belied the acute anxiety she harbored regarding the impending parliamentary vote of no confidence.', 'Lesson 5', 5, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'belittle', '/bɪˈlɪtl/', 'v.', 'Coi nhẹ, xem thường, hạ thấp giá trị', 'Traditional critics sought to belittle the poet’s innovative vernacular style, dismissing her verses as mere ephemeral novelties rather than enduring literature.', 'Lesson 5', 5, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bellicose', '/ˈbelɪkoʊs/', 'adj.', 'Hiếu chiến, thích gây hấn', 'The seasoned diplomat warned that bellicose declarations from the border commanders would derail delicate peace talks and provoke an unintended regional war.', 'Lesson 5', 5, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'belligerent', '/bəˈlɪdʒərənt/', 'adj.', 'Hung hăng, thù địch, tham chiến', 'International mediators urged both belligerent states to declare an immediate ceasefire and permit humanitarian convoys into contested provinces.', 'Lesson 5', 5, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bemoan', '/bɪˈmoʊn/', 'v.', 'Than vãn, thương tiếc, phàn nàn', 'In his philosophical treatise, the essayist bemoaned the erosion of civic virtue in an era increasingly dominated by commercial self-interest.', 'Lesson 5', 5, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bemused', '/bɪˈmjuːzd/', 'adj.', 'Bối rối, ngơ ngác, lúng túng', 'Confronted by the paradoxical results of the subatomic collision, the astrophysicist wore a bemused expression as existing theoretical models collapsed.', 'Lesson 5', 5, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'benediction', '/ˌbenɪˈdɪkʃn/', 'n.', 'Lời chúc phúc, lễ ban phước', 'As the congregation bowed in solemn reverence, the venerable bishop raised his trembling hands to deliver the parting benediction.', 'Lesson 5', 5, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'benefactor', '/ˈbenɪfæktər/', 'n.', 'Nhà hảo tâm, người bảo trợ', 'Without the generous endowment from an anonymous benefactor, the fledgling conservatory would have been forced to shutter its tuition-free youth orchestra.', 'Lesson 5', 5, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beneficial', '/ˌbenɪˈfɪʃl/', 'adj.', 'Có lợi, hữu ích', 'Field studies revealed that the periodic flooding was immensely beneficial to the riparian ecosystem, depositing nutrient-rich silt that rejuvenated native flora.', 'Lesson 5', 5, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beneficiary', '/ˌbenɪˈfɪʃieri/', 'n.', 'Người thụ hưởng', 'Under the provisions of the agrarian land reform, displaced tenant farmers became the primary beneficiaries of parcels subdivided from feudal estates.', 'Lesson 5', 5, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'benevolent', '/bəˈnevələnt/', 'adj.', 'Nhân từ, rộng lượng, thiện tâm', 'Enlightenment philosophers posited that even an absolute sovereign must govern as a benevolent patriarch dedicated to the welfare of the commonwealth.', 'Lesson 5', 5, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'benign', '/bɪˈnaɪn/', 'adj.', 'Lành tính, hiền hòa, không gây hại', 'Although early colonial surveys mischaracterized the tropical climate as benign, subsequent expeditions suffered devastating losses to endemic swamp fevers.', 'Lesson 5', 5, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bent', '/bent/', 'n.', 'Khuynh hướng tự nhiên, thiên hướng, năng khiếu', 'Displaying a distinct mechanical bent from an early age, the young inventor spent hours disassembling clockwork mechanisms in her father’s workshop.', 'Lesson 5', 5, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bequeath', '/bɪˈkwiːð/', 'v.', 'Để lại qua di chúc, truyền lại', 'The constitutional delegates recognized their historic imperative not merely to quiet contemporary factions, but to bequeath a stable republic to posterity.', 'Lesson 5', 5, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'berate', '/bɪˈreɪt/', 'v.', 'Mắng mỏ thậm tệ, quở trách gay gắt', 'The imperious magistrate paused the trial proceedings to fiercely berate the defense counsel for repeatedly violating court protocols.', 'Lesson 5', 5, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bereavement', '/bɪˈriːvmənt/', 'n.', 'Nỗi đau mất người thân, tang chế', 'Following the devastating influenza epidemic, the isolated hamlet endured a prolonged period of bereavement, with nearly every household draped in mourning cloth.', 'Lesson 5', 5, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bereft', '/bɪˈreft/', 'adj.', 'Bị tước đoạt, thiếu vắng, trơ trọi', 'Bereft of financial backing and public sympathy, the dissident publication was forced to suspend its investigative printing operations.', 'Lesson 5', 5, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'berserk', '/bərˈzɜːrk/', 'adj.', 'Cuồng loạn, phát điên, mất kiểm soát', 'Historical chronicles describe how frontline warriors, driven berserk by battlefield adrenaline, shattered enemy phalanxes with relentless, reckless fury.', 'Lesson 5', 5, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beseech', '/bɪˈsiːtʃ/', 'v.', 'Khẩn cầu, van nài, tha thiết nài xin', 'Clad in rags and desperate for grain, the starving townsfolk knelt before the governor''s carriage to beseech him for emergency relief.', 'Lesson 5', 5, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'beset', '/bɪˈset/', 'v.', 'Bủa vây, đeo bám, gây rắc rối liên tục', 'Beset by skyrocketing hyperinflation and persistent labor strikes, the provisional government struggled to maintain public order across industrial centers.', 'Lesson 5', 5, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'besiege', '/bɪˈsiːdʒ/', 'v.', 'Bao vây, vây hãm', 'The advancing imperial legion planned to besiege the rebel fortress throughout the winter months, cutting off aqueducts and starving the garrison.', 'Lesson 5', 5, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'besmirch', '/bɪˈsmɜːrtʃ/', 'v.', 'Làm ố danh, bôi nhọ danh dự', 'Political adversaries circulated defamatory pamphlets in a calculated attempt to besmirch the chancellor''s upright reputation before election day.', 'Lesson 5', 5, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bestial', '/ˈbestiəl/', 'adj.', 'Dã man, tàn bạo như thú dữ', 'Eyewitness testimonies presented at the tribunal documented the bestial conditions inside the penal colony, where prisoners were routinely denied basic medical sustenance.', 'Lesson 5', 5, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'betoken', '/bɪˈtoʊkən/', 'v.', 'Báo hiệu, là điềm báo của', 'The sudden departure of foreign envoys and the heightened patrols along the frontier betokened a breakdown in diplomatic negotiations.', 'Lesson 5', 5, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'betray', '/bɪˈtreɪ/', 'v.', 'Phản bội, để lộ bí mật', 'Although the witness maintained an impassive expression under cross-examination, his nervous cadence betrayed an underlying fear of perjury.', 'Lesson 5', 5, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bevy', '/ˈbevi/', 'n.', 'Một đàn, một nhóm đông, một tốp', 'The academic conference attracted an illustrious bevy of economists and demographers, all eager to debate the structural ramifications of global trade pacts.', 'Lesson 5', 5, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'biased', '/ˈbaɪəst/', 'adj.', 'Thiên vị, có định kiến', 'Critics dismissed the pharmaceutical company''s internal clinical review as inherently biased because it omitted negative trial data regarding drug efficacy.', 'Lesson 5', 5, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bicameral', '/baɪˈkæmərəl/', 'adj.', 'Lưỡng viện (có hai viện lập pháp)', 'Under the new constitutional framework, the young republic established a bicameral legislature to balance proportional popular representation against regional autonomy.', 'Lesson 5', 5, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bicker', '/ˈbɪkər/', 'v.', 'Cãi vã lặt vặt, tranh cãi vụn vặt', 'While coalition leaders continued to bicker over cabinet appointments and protocol, severe grain shortages left the capital teetering on riots.', 'Lesson 5', 5, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'biennial', '/baɪˈeniəl/', 'adj.', 'Hai năm một lần, kéo dài hai năm', 'Botanists noted that the biennial plant allocates all energy to root and leaf development in its inaugural year, reserving flowering and seed production for its second.', 'Lesson 5', 5, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bigotry', '/ˈbɪɡətri/', 'n.', 'Sự cố chấp, thói hẹp hòi mù quáng', 'The abolitionist orator condemned institutionalized bigotry, arguing that a nation founded on universal equality could not long survive while sanctioning ethnic oppression.', 'Lesson 5', 5, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bilious', '/ˈbɪliəs/', 'adj.', 'Cáu kỉnh, gắt gỏng, khó tính', 'Known for his bilious temper and acerbic commentary, the veteran parliamentarian frequently alienated prospective allies with stinging personal insults.', 'Lesson 5', 5, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bilk', '/bɪlk/', 'v.', 'Lừa đảo chiếm đoạt, quỵt nợ', 'Financial regulators uncovered a sophisticated offshore shell company engineered to bilk vulnerable pensioners out of their retirement savings.', 'Lesson 5', 5, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'billowing', '/ˈbɪloʊɪŋ/', 'adj.', 'Cuồn cuộn, bồng bềnh dâng lên', 'Dense plumes of billowing smoke poured from the foundry smokestacks, casting a permanent dark veil over the sprawling nineteenth-century industrial basin.', 'Lesson 5', 5, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bivouac', '/ˈbɪvuæk/', 'n.', 'Lán trại dã chiến, điểm đóng quân tạm thời', 'Stymied by darkness and sudden subzero temperatures, the reconnaissance patrol established a makeshift bivouac behind a granite ridge.', 'Lesson 5', 5, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bizarre', '/bɪˈzɑːr/', 'adj.', 'Kỳ quái, lập dị, dị thường', 'Marine biologists cataloged bizarre abyssal organisms capable of withstanding crushing hydrostatic pressures while generating their own bioluminescent light.', 'Lesson 5', 5, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blanch', '/blæntʃ/', 'v.', 'Tái mét, nhạt màu, làm cho trắng', 'The seasoned defense minister did not blanch when presented with intercepted intelligence outlining the adversary''s mobilization along the northern border.', 'Lesson 5', 5, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bland', '/blænd/', 'adj.', 'Nhạt nhẽo, vô vị, tẻ nhạt', 'Architectural critics criticized the monolithic glass towers as bland additions that stripped the historic waterfront of its vernacular charm.', 'Lesson 5', 5, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blandishment', '/ˈblændɪʃmənt/', 'n.', 'Lời đường mật, sự tán tỉnh dỗ dành', 'Resolute in her environmental stance, the congresswoman resisted the lucrative blandishments of fossil fuel lobbyists attempting to weaken regulatory standards.', 'Lesson 5', 5, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blare', '/bler/', 'v.', 'Vang inh ỏi, kêu ầm ĩ', 'Emergency klaxons began to blare throughout the naval shipyard as storm waters breached the exterior retaining seawall.', 'Lesson 5', 5, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blasphemy', '/ˈblæsfəmi/', 'n.', 'Lời báng bổ, sự xúc phạm thần thánh', 'In seventeenth-century Europe, natural philosophers whose empirical observations contradicted ecclesiastical dogma were frequently persecuted under charges of heresy and blasphemy.', 'Lesson 5', 5, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blatant', '/ˈbleɪtnt/', 'adj.', 'Trắng trợn, rành rành, hiển nhiên', 'The leaked municipal memo revealed a blatant disregard for safety regulations, documenting that building inspectors routinely accepted kickbacks to approve faulty foundations.', 'Lesson 5', 5, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bleak', '/bliːk/', 'adj.', 'Ảm đạm, hoang vắng, u ám', 'Confronted by persistent drought and dwindling grain silos, the agrarian province faced a bleak winter of food rationing and economic depression.', 'Lesson 5', 5, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blighted', '/ˈblaɪtɪd/', 'adj.', 'Bị tàn lụi, bị tàn phá, suy đồi', 'Municipal planners unveiled an ambitious renewal initiative aimed at reclaiming blighted industrial waterfronts and creating sustainable public parks.', 'Lesson 5', 5, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blithe', '/blaɪð/', 'adj.', 'Vô tư lự, thản nhiên đến vô tâm', 'Historians faulted the colonial administrators for their blithe indifference to localized crop failures, which ultimately precipitated a preventable famine.', 'Lesson 5', 5, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bloated', '/ˈbloʊtɪd/', 'adj.', 'Phình to, quá tải, cồng kềnh quá mức', 'Auditors warned that the agency had become a bloated bureaucracy, consuming millions in administrative overhead while delivering negligible public assistance.', 'Lesson 5', 5, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bludgeon', '/ˈblʌdʒən/', 'v.', 'Đánh bằng gậy tày, cưỡng ép thô bạo', 'Rather than building a consensus through debate, the parliamentary majority attempted to bludgeon opposition factions into acquiescing to the emergency tax decree.', 'Lesson 5', 5, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bluff', '/blʌf/', 'n.', 'Mưu mẹo lừa gạt, đòn hù dọa', 'The veteran negotiator recognized that the rival faction’s ultimatum was merely a high-stakes bluff designed to extract trade concessions without risking military engagement.', 'Lesson 5', 5, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blunder', '/ˈblʌndər/', 'n.', 'Sai lầm ngớ ngẩn, sự lỡ bước tai hại', 'Military analysts consider the uncoordinated cavalry charge a disastrous strategic blunder that turned an almost certain tactical victory into a catastrophic rout.', 'Lesson 5', 5, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'blurt', '/blɜːrt/', 'v.', 'Thốt ra một cách bất ngờ, buột miệng nói', 'Overwhelmed by intense interrogation and desperate to defend his accomplice, the young clerk blurted out the location of the hidden ledger before realizing he had sealed his own indictment.', 'Lesson 5', 5, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bluster', '/ˈblʌstər/', 'v.', 'Quát tháo ầm ĩ, đe dọa suông', 'Though the embattled prime minister blustered at the podium about imposing punitive tariffs, seasoned diplomats recognized his aggressive rhetoric as an empty mask for domestic political vulnerability.', 'Lesson 5', 5, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bode', '/boʊd/', 'v.', 'Báo trước, là điềm báo', 'The abrupt drop in seasonal agricultural yields, coupled with uncharacteristically severe early frosts, did not bode well for the fledgling colony''s prospects of surviving the impending winter.', 'Lesson 5', 5, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bohemian', '/boʊˈhiːmiən/', 'adj.', 'Phóng túng, không theo khuôn phép xã hội', 'Rejecting the rigid moral expectations of her Victorian upbringing, the avant-garde sculptor embraced a bohemian existence in Paris, prizing unfettered creative expression over middle-class respectability.', 'Lesson 5', 5, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'boisterous', '/ˈbɔɪstərəs/', 'adj.', 'Náo nhiệt, ồn ào huyên náo', 'The solemn silence of the parliamentary chamber stood in stark contrast to the boisterous crowd gathered in the square, whose rhythmic chants and celebratory clamor reverberated through the marble halls.', 'Lesson 5', 5, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bolster', '/ˈboʊlstər/', 'v.', 'Củng cố, bồi đắp, gia cố', 'To bolster her contentious hypothesis regarding avian evolution, the paleontologist presented newly excavated transitional fossils exhibiting both theropod skeletal structures and rudimentary plumage.', 'Lesson 5', 5, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bolt', '/boʊlt/', 'v.', 'Lao vụt đi, phóng nhanh; then chốt', 'Startled by the abrupt crack of thunder that shattered the afternoon stillness, the yearling bolted across the open meadow before the stable hands could secure the pasture gate.', 'Lesson 5', 5, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bombardment', '/bɑːmˈbɑːrdmənt/', 'n.', 'Sự oanh tạc dữ dội, sự dồn dập tấn công', 'Sheltered in subterranean bunkers throughout weeks of sustained artillery bombardment, the besieged garrison suffered not only devastating structural destruction but also severe psychological trauma.', 'Lesson 5', 5, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bombastic', '/bɑːmˈbæstɪk/', 'adj.', 'Khoa trương, đao to búa lớn, sáo rỗng', 'Editorial commentators dismissed the candidate''s bombastic speech as hollow grandstanding, noting that his sweeping declarations were devoid of substantive policy proposals.', 'Lesson 5', 5, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'booming', '/ˈbuːmɪŋ/', 'adj.', 'Phát triển nhanh chóng, bùng nổ mạnh mẽ', 'Spurred by the swift expansion of regional railway networks and maritime trade, the formerly secluded harbor town developed a booming commercial economy within a single decade.', 'Lesson 5', 5, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'boon', '/buːn/', 'n.', 'Mối lợi lớn, ân huệ, điều may mắn', 'The discovery of an abundant aquifer beneath the arid plateau proved to be an invaluable boon to local farmers, transforming previously barren acreage into productive farmland.', 'Lesson 5', 5, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'boorish', '/ˈbʊrɪʃ/', 'adj.', 'Thô lỗ, cục cằn, vô phép tắc', 'The aristocrat’s boorish conduct at the state banquet—interrupting guest speakers and openly mocking cultural protocols—deeply mortified his diplomatic hosts.', 'Lesson 5', 5, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'boundless', '/ˈbaʊndləs/', 'adj.', 'Vô hạn, bao la, không bờ bến', 'Gazing across the boundless expanse of the oceanic horizon from the ship’s bow, the early navigators felt both an acute sense of isolation and a profound awe at nature''s scale.', 'Lesson 5', 5, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bountiful', '/ˈbaʊntɪfəl/', 'adj.', 'Dồi dào, phong phú, trù phú', 'Benefiting from the fertile alluvial soil deposited during seasonal floods, the river valley yielded bountiful harvests that sustained extensive urban settlements throughout the bronze age.', 'Lesson 5', 5, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bourgeois', '/bʊrˈʒwɑː/', 'adj.', 'Thuộc giai cấp tư sản, thực dụng và chuộng quy ước', 'In her biting realist fiction, the nineteenth-century novelist satirized bourgeois social ambitions, depicting how a fixation on fashionable domestic display often masked profound spiritual emptiness.', 'Lesson 5', 5, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bovine', '/ˈboʊvaɪn/', 'adj.', 'Chậm chạp, đờ đẫn; thuộc loài bò', 'Confronted by the impassioned pleas of the reformist delegation, the autocratic governor responded with a bovine indifference, staring blankly ahead without uttering a word of acknowledgment.', 'Lesson 5', 5, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bowdlerize', '/ˈbaʊdləraɪz/', 'v.', 'Kiểm duyệt lược bỏ, cắt xén (sách, tài liệu)', 'Nineteenth-century school publishers routinely bowdlerized classic dramatic texts, excising ribald humor and gruesome tragedies to make them palatable to conservative Victorian sensibilities.', 'Lesson 5', 5, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'boycott', '/ˈbɔɪkɑːt/', 'v.', 'Tẩy chay phản đối', 'Seeking to dismantle systemic segregation on public transportation, community leaders organized residents to boycott the city bus lines, depriving the transit company of vital daily operating revenue.', 'Lesson 5', 5, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'braggart', '/ˈbræɡərt/', 'n.', 'Kẻ khoe khoang, kẻ khoác lác', 'Despite his constant claims of military heroism during foreign campaigns, the braggart was quickly unmasked when he panicked and fled during an actual frontier skirmish.', 'Lesson 5', 5, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brandish', '/ˈbrændɪʃ/', 'v.', 'Khua, vung vẩy (vũ khí) để đe dọa hoặc thị uy', 'Standing resolutely upon the fortress ramparts, the rebellious chieftain brandished his ancestral sword to rally his beleaguered warriors against the encroaching legion.', 'Lesson 5', 5, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bravado', '/brəˈvɑːdoʊ/', 'n.', 'Sự phô trương lòng dũng cảm, vẻ bạo dạn giả tạo', 'The young soldier''s outward display of swaggering bravado could not entirely disguise his trembling hands as the distant thunder of approaching artillery grew louder.', 'Lesson 5', 5, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brawn', '/brɔːn/', 'n.', 'Sức mạnh cơ bắp, thể lực khỏe mạnh', 'The construction of the transcontinental aqueduct required an enormous expenditure of human brawn, yet it ultimately succeeded only because of pioneering geological and hydraulic calculations.', 'Lesson 5', 5, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brazen', '/ˈbreɪzən/', 'adj.', 'Trơ trẽn, vô liêm sỉ, ngang nhiên', 'The defense contractor exhibited brazen disregard for ethical standards when audit records revealed it had deliberately billed the government for nonexistent research expenditures.', 'Lesson 5', 5, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'breach', '/briːtʃ/', 'n.', 'Sự vi phạm hợp đồng, sự phá vỡ mối quan hệ', 'The sudden deployment of naval armaments to the demilitarized perimeter was widely condemned by international observers as a flagrant breach of the non-aggression treaty.', 'Lesson 5', 5, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'breadth', '/bredθ/', 'n.', 'Bề rộng, tầm sâu rộng của hiểu biết', 'The committee commended the scholar’s monograph not merely for its meticulous archival depth, but for the remarkable breadth of disciplinary perspectives it synthesized across history, economics, and sociology.', 'Lesson 5', 5, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brevity', '/ˈbrevəti/', 'n.', 'Sự ngắn gọn, tính súc tích', 'President Lincoln’s Gettysburg Address demonstrated the enduring rhetorical power of brevity, delivering a monumental philosophical defense of democracy in scarcely three hundred words.', 'Lesson 5', 5, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brindled', '/ˈbrɪndəld/', 'adj.', 'Có vằn đốm màu nâu hoặc xám sẫm', 'Effectively camouflaged amidst the fallen leaves and sun-dappled brush, the mastiff’s brindled coat allowed it to move unseen along the forest perimeter.', 'Lesson 5', 5, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bristling', '/ˈbrɪslɪŋ/', 'adj.', 'Dựng đứng, đầy rẫy, bừng bừng tức giận', 'Bristling with resentment over being passed over for promotion, the senior analyst refused to contribute to the newly formed advisory task force.', 'Lesson 5', 5, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brittle', '/ˈbrɪtl/', 'adj.', 'Giòn, dễ vỡ, mong manh', 'Subjected to cryogenic temperatures, many conventional synthetic polymers lose their elasticity and become dangerously brittle, rendering them prone to fracturing under mechanical stress.', 'Lesson 5', 5, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'broach', '/broʊtʃ/', 'v.', 'Mở lời, đề cập một vấn đề nhạy cảm', 'Recognizing the fragile harmony within the coalition cabinet, the foreign secretary waited until the peace accord was ratified before daring to broach the contentious topic of naval disarmament.', 'Lesson 5', 5, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brochure', '/broʊˈʃʊr/', 'n.', 'Cuốn sách mỏng giới thiệu, tập tài liệu quảng cáo', 'Designed to attract prospective university matriculants, the glossy admissions brochure highlighted state-of-the-art laboratory facilities and glowing profiles of recent alumni.', 'Lesson 5', 5, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brooch', '/broʊtʃ/', 'n.', 'Trâm cài áo đính đá quý', 'Pinned gracefully to the lapel of her tailored velvet jacket, the heirloom emerald brooch was the only jewel the exiled archduchess had managed to preserve from her family estate.', 'Lesson 5', 5, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'browbeat', '/ˈbraʊbiːt/', 'v.', 'Hăm dọa, nạt nộ để áp chế', 'The authoritarian committee chairman repeatedly attempted to browbeat recalcitrant witnesses into endorsing his conclusions, cutting off their explanations with abrasive reprimands.', 'Lesson 5', 5, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'browse', '/braʊz/', 'v.', 'Xem lướt qua, duyệt nội dung hoặc tài liệu', 'Granted exclusive access to the rare book collection, the visiting medievalist spent hours browsing illuminated manuscripts to trace variations in twelfth-century monastic script.', 'Lesson 5', 5, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brunt', '/brʌnt/', 'n.', 'Gánh nặng chính, sức ép nặng nề nhất', 'Because subsistence farming communities lack insulated infrastructure, they invariably bear the brunt of prolonged droughts and climate-induced crop failures.', 'Lesson 5', 5, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'brusque', '/brʌsk/', 'adj.', 'Cộc lốc, thô lỗ, khiếm nhã', 'Accustomed to elaborate aristocratic courtesies, the royal envoy was deeply unsettled by the frontier magistrate’s brusque greeting and immediate demand for legal credentials.', 'Lesson 5', 5, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'buccaneer', '/ˌbʌkəˈnɪr/', 'n.', 'Hải tặc, kẻ cướp biển', 'Operating out of lawless Caribbean harbors such as Port Royal, seventeenth-century buccaneers raided Spanish shipping lanes under semi-official privateering commissions.', 'Lesson 5', 5, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bucolic', '/bjuːˈkɑːlɪk/', 'adj.', 'Thuộc đồng quê thanh bình, mộc mạc', 'Exhausted by the relentless pace and pollution of the industrial metropolis, the landscape painter sought solitude in a bucolic valley celebrated for its tranquil pastures and winding brooks.', 'Lesson 5', 5, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'buffet', '/ˈbʌfɪt/', 'v.', 'Vùi dập, đánh mạnh liên tiếp', 'As the hurricane made landfall, ferocious winds buffeted the coastal lighthouse, sending massive breakers crashing over its granite foundations.', 'Lesson 5', 5, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'buffoonery', '/bəˈfuːnəri/', 'n.', 'Trò hề, hành vi lố bịch gây cười', 'What began as a dignified political debate quickly degenerated into chaotic buffoonery as the candidates traded petty insults and exaggerated theatrical gestures.', 'Lesson 5', 5, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bullion', '/ˈbʊliən/', 'n.', 'Vàng hoặc bạc thỏi đúc', 'To stabilize its depreciating paper currency during the post-war crisis, the central bank transferred massive reserves of gold bullion to international depository vaults.', 'Lesson 5', 5, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bulwark', '/ˈbʊlwərk/', 'n.', 'Thành lũy bảo vệ, chỗ dựa che chở kiên cố', 'The framers of the constitution envisioned a free and uncensored press as an indispensable bulwark against the tyrannical encroachment of governmental power.', 'Lesson 5', 5, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bumptious', '/ˈbʌmpʃəs/', 'adj.', 'Tự phụ, kiêu ngạo huênh hoang', 'The bumptious young junior partner frequently interrupted senior litigators during strategy conferences, alienating colleagues with his unwarranted air of intellectual superiority.', 'Lesson 5', 5, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bungalow', '/ˈbʌŋɡəloʊ/', 'n.', 'Nhà một tầng, nhà trệt có hiên rộng', 'Constructed during the Arts and Crafts architectural movement, the charming bungalow featured exposed wooden beams, an open floor plan, and a wide sheltered porch overlooking the garden.', 'Lesson 5', 5, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bungle', '/ˈbʌŋɡəl/', 'v.', 'Làm hỏng việc do vụng về, làm hỏng bét', 'The inexperienced expedition leaders bungled the procurement of essential polar rations, inadvertently stranding the survey team without sufficient supplies for the subzero trek.', 'Lesson 5', 5, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'buoyant', '/ˈbɔɪənt/', 'adj.', 'Nổi được trên nước; lạc quan, phấn chấn', 'Despite a succession of disappointing clinical trial results, the chief researcher remained remarkably buoyant, maintaining unshakable confidence in the therapeutic viability of the underlying molecule.', 'Lesson 5', 5, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bureaucracy', '/bjʊˈrɑːkrəsi/', 'n.', 'Bộ máy quan liêu, hệ thống thủ tục hành chính phức tạp', 'Entrepreneurs hoping to launch renewable energy projects often found their initiatives stalled by a labyrinthine municipal bureaucracy that required approvals from dozens of overlapping agencies.', 'Lesson 5', 5, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'burgeon', '/ˈbɜːrdʒən/', 'v.', 'Phát triển mạnh mẽ, nở rộ, đâm chồi', 'Following the elimination of restrictive trade tariffs, cross-border commercial exchange burgeoned, propelling the sleepy frontier town into a prosperous regional trading hub.', 'Lesson 5', 5, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'burlesque', '/bɜːrˈlesk/', 'n.', 'Sự giễu nhại, thể loại hài kịch châm biếm quá lố', 'The dramatist’s latest satirical play functioned as a biting burlesque of aristocratic vanity, exaggerating high-society etiquette to expose the absurdities of aristocratic entitlement.', 'Lesson 5', 5, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'burly', '/ˈbɜːrli/', 'adj.', 'Vạm vỡ, lực lưỡng, cường tráng', 'Two burly stevedores hauled the heavy iron anchor across the wet deck, their muscular frames easily withstanding the jarring motion of the rolling cargo vessel.', 'Lesson 5', 5, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'burnish', '/ˈbɜːrnɪʃ/', 'v.', 'Đánh bóng, mài giũa để làm sáng bóng', 'Seeking to burnish his diplomatic legacy before the upcoming summit, the veteran statesman mediated a delicate ceasefire between the long-warring border nations.', 'Lesson 6', 6, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'centrifugal', '/sɛnˈtrɪfjʊɡəl/', 'adj.', 'Ly tâm, có xu hướng văng ra xa tâm', 'As the empire expanded across disparate continents, centrifugal political forces gradually eroded the central government''s authority, hastening its eventual dissolution.', 'Lesson 6', 6, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'bustle', '/ˈbʌsəl/', 'v.', 'Hối hả, rộn ràng, nhộn nhịp di chuyển', 'Merchant vessels and couriers continued to bustle through the Venetian harbor at dawn, transforming the tranquil lagoon into a labyrinth of maritime commerce.', 'Lesson 6', 6, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'buttress', '/ˈbʌtrɪs/', 'v.', 'Củng cố, chống đỡ, làm tăng sức thuyết phục', 'To buttress her controversial thesis on institutional inequality, the sociologist marshaled decades of longitudinal census data and archival records.', 'Lesson 6', 6, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'buxom', '/ˈbʊksəm/', 'adj.', 'Đầy đặn, nở nang, tràn đầy sức sống', 'Eighteenth-century Dutch portraiture frequently depicted buxom peasant women against harvest landscapes, celebrating pastoral vitality and abundance.', 'Lesson 6', 6, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cabal', '/kəˈbɑːl/', 'n.', 'Băng đảng phe phái mưu đồ bí mật', 'Suspecting that a palace cabal was covertly orchestrating a coup, the emperor dismissed his most senior ministers and placed the royal guard on high alert.', 'Lesson 6', 6, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cache', '/kæʃ/', 'n.', 'Nơi cất giấu bí mật, kho cất trữ', 'Archaeologists excavating the cliffside cave discovered a clandestine cache of bronze weapons and minted coins dating back to the late Hellenistic period.', 'Lesson 6', 6, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cacophonous', '/kəˈkɑːfənəs/', 'adj.', 'Chói tai, hỗn tạp, khó nghe', 'The pastoral stillness of the valley was suddenly shattered by the cacophonous roar of industrial steam engines and shrieking iron whistles.', 'Lesson 6', 6, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cadaver', '/kəˈdævər/', 'n.', 'Tử thi, thi hài dùng cho giải phẫu', 'During the Renaissance, anatomists like Vesalius challenged scholastic dogma by meticulously dissecting a human cadaver to observe anatomical structures firsthand.', 'Lesson 6', 6, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cadaverous', '/kəˈdævərəs/', 'adj.', 'Tái mét như tử thi, gầy gò hốc hác', 'Years of solitary confinement and malnutrition had rendered the political dissident cadaverous, with hollowed cheeks and a paper-thin complexion.', 'Lesson 6', 6, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cadence', '/ˈkeɪdəns/', 'n.', 'Nhịp điệu, ngữ điệu nhịp nhàng', 'The orator captivated the assembly not merely with forceful arguments, but with the musical cadence and rhetorical pauses of his delivery.', 'Lesson 6', 6, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cajole', '/kəˈdʒoʊl/', 'v.', 'Dụ dỗ, nịnh hót để thuyết phục', 'Despite their persistent efforts to cajole the obstinate senator with promises of committee appointments, party leaders failed to secure his decisive vote.', 'Lesson 6', 6, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'calamity', '/kəˈlæməti/', 'n.', 'Tai họa, đại họa thảm khốc', 'The sudden collapse of the national banking system precipitated an economic calamity that drove thousands of agrarian families into insolvency.', 'Lesson 6', 6, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'calculated', '/ˈkælkjəleɪtɪd/', 'adj.', 'Được tính toán kỹ lưỡng, có chủ đích', 'The general’s retreat was not a panic-stricken rout, but a calculated tactical maneuver designed to draw the enemy forces deeper into inhospitable terrain.', 'Lesson 6', 6, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caldron', '/ˈkɔːldrən/', 'n.', 'Vạc lớn, nơi sục sôi xung đột', 'By the summer of 1914, the Balkans had transformed into a geopolitical caldron of ethnic rivalry and imperial ambition awaiting a single spark.', 'Lesson 6', 6, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caliber', '/ˈkælɪbər/', 'n.', 'Phẩm chất, năng lực, tầm cỡ', 'Attracting scholars of extraordinary caliber, the nascent research institute quickly established itself as a preeminent hub for quantum physics.', 'Lesson 6', 6, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'calligraphy', '/kəˈlɪɡrəfi/', 'n.', 'Nghệ thuật thư pháp', 'In imperial China, mastery of calligraphy was regarded not merely as a decorative craft, but as a profound reflection of a scholar-official’s moral discipline.', 'Lesson 6', 6, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'callous', '/ˈkæləs/', 'adj.', 'Nhẫn tâm, vô cảm, chai sạn', 'The tenement landlord exhibited a callous indifference to the tenants'' plight, refusing to restore heating during the harshest weeks of winter.', 'Lesson 6', 6, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'callow', '/ˈkæloʊ/', 'adj.', 'Non nớt, thiếu kinh nghiệm, chưa trưởng thành', 'Entrusted with a command far beyond his capabilities, the callow subaltern struggled to maintain order among battle-hardened veteran soldiers.', 'Lesson 6', 6, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'calorific', '/ˌkæləˈrɪfɪk/', 'adj.', 'Sinh nhiệt, tạo năng lượng nhiệt', 'Anthropologists argue that the culinary transition to cooked meat increased the calorific efficiency of early hominin diets, fueling rapid brain development.', 'Lesson 6', 6, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'calumny', '/ˈkæləmni/', 'n.', 'Sự vu khống, lời phỉ báng bôi nhọ', 'Rather than addressing his opponent''s policy platform on its merits, the candidate resorted to malicious calumny in an attempt to tarnish her integrity.', 'Lesson 6', 6, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'camaraderie', '/ˌkɑːməˈrɑːdəri/', 'n.', 'Tình bạn đồng đội, sự gắn bó thân thiết', 'Enduring grueling arctic blizzards and isolation, the explorers forged a deep sense of camaraderie that sustained them throughout the harrowing expedition.', 'Lesson 6', 6, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cameo', '/ˈkæmioʊ/', 'n.', 'Vai diễn khách mời, hình chạm nổi nghệ thuật', 'The celebrated director made an unexpected cameo as a bystander in the film''s climactic railway station scene, delighting astute cinephiles.', 'Lesson 6', 6, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'camouflage', '/ˈkæməflɑːʒ/', 'n.', 'Sự ngụy trang, tài ngụy trang', 'The mottled plumage of the ptarmigan provides indispensable camouflage against the snowy tundra, shielding it from aerial raptors.', 'Lesson 6', 6, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'candor', '/ˈkændər/', 'n.', 'Sự bộc trực, tính ngay thẳng thật thà', 'The auditor was widely respected for her unvarnished candor, never hesitating to expose accounting discrepancies regardless of executive pushback.', 'Lesson 6', 6, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'canine', '/ˈkeɪnaɪn/', 'adj.', 'Thuộc loài chó, có đặc tính như loài chó', 'Paleontologists reconstructed the prehistoric predator''s lineage by comparing its prominent canine dentition with that of modern wolves.', 'Lesson 6', 6, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'canny', '/ˈkæni/', 'adj.', 'Khôn ngoan, sắc sảo, tính toán thận trọng', 'Through canny negotiations and well-timed acquisitions during economic recessions, the industrialist built an unparalleled manufacturing empire.', 'Lesson 6', 6, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catalyst', '/ˈkætəlɪst/', 'n.', 'Chất xúc tác, nhân tố thúc đẩy biến đổi', 'The publication of Thomas Paine’s ''Common Sense'' acted as a powerful catalyst, galvanizing widespread colonial sentiment in favor of outright independence.', 'Lesson 6', 6, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cant', '/kænt/', 'n.', 'Lời nói đạo đức giả, giáo điều sáo rỗng', 'Weary of the sanctimonious cant spouted by career politicians, voters gravitated toward independent candidates promising uncompromising transparency.', 'Lesson 6', 6, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cantankerous', '/kænˈtæŋkərəs/', 'adj.', 'Gắt gỏng, khó tính, ngang ngạnh', 'Known for his cantankerous temperament, the reclusive composer frequently feuded with concert hall managers and rebuffed interview requests.', 'Lesson 6', 6, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cantata', '/kənˈtɑːtə/', 'n.', 'Bản hợp xướng cantata', 'Johann Sebastian Bach composed a solemn sacred cantata for each Sunday of the liturgical calendar, weaving intricate choral polyphony with biblical texts.', 'Lesson 6', 6, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'canter', '/ˈkæntər/', 'n.', 'Nước kiệu nhỏ, bước phi thong thả của ngựa', 'Reining in the spirited thoroughbred to a steady canter, the equestrian negotiated the winding forest trail with effortless grace.', 'Lesson 6', 6, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'canto', '/ˈkæntoʊ/', 'n.', 'Khúc ca, khổ thơ lớn trong trường ca', 'In the culminating canto of the ''Inferno'', Dante and Virgil navigate the frozen ninth circle of hell before ascending to glimpse the stars once more.', 'Lesson 6', 6, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'canvass', '/ˈkænvəs/', 'v.', 'Vận động bầu cử, khảo sát ý kiến quần chúng', 'Grassroots organizers mobilized hundreds of volunteers to canvass residential districts door-to-door ahead of the crucial municipal referendum.', 'Lesson 6', 6, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'capacious', '/kəˈpeɪʃəs/', 'adj.', 'Rộng lớn, có sức chứa bao la', 'The university’s newly constructed archive featured capacious reading rooms designed to store centuries of fragile parchment manuscripts safely.', 'Lesson 6', 6, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'capitulate', '/kəˈpɪtʃəleɪt/', 'v.', 'Đầu hàng, chịu khuất phục', 'Besieged for months without fresh provisions or ammunition, the garrison commander was finally compelled to capitulate to avoid the starvation of his troops.', 'Lesson 6', 6, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caprice', '/kəˈpriːs/', 'n.', 'Tính khí thất thường, ý thích bất chợt', 'Living under absolute monarchy meant that the liberties and fortunes of subjects were perpetually subject to the monarch’s arbitrary caprice.', 'Lesson 6', 6, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'capricious', '/kəˈprɪʃəs/', 'adj.', 'Thất thường, bất thường khó đoán', 'Alpine meteorologists cautioned climbers that capricious mountain winds could instantly transform clear skies into a blinding blizzard.', 'Lesson 6', 6, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caption', '/ˈkæpʃən/', 'n.', 'Lời chú thích dưới hình ảnh, phụ đề', 'The historical photograph’s brief caption shed light on the obscure identity of the abolitionist standing beside Frederick Douglass.', 'Lesson 6', 6, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'captivate', '/ˈkæptɪveɪt/', 'v.', 'Thu hút, làm mê hoặc, làm say đắm', 'The prima ballerina continued to captivate audiences worldwide with her expressive interpretations of classical repertoire and fluid athleticism.', 'Lesson 6', 6, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'carat', '/ˈkærət/', 'n.', 'Cara (đơn vị đo trọng lượng đá quý hoặc độ tinh khiết của vàng)', 'Gemologists determined that the sapphire’s astronomical auction value was due not only to its flawless clarity, but to its rare twelve-carat mass.', 'Lesson 6', 6, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cardinal', '/ˈkɑːrdɪnəl/', 'adj.', 'Cốt yếu, căn bản, quan trọng bậc nhất', 'In investigative journalism, verifying source corroboration before publishing unverified leaks is considered a cardinal rule of professional ethics.', 'Lesson 6', 6, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cardiologist', '/ˌkɑːrdiˈɑːlədʒɪst/', 'n.', 'Bác sĩ chuyên khoa tim mạch', 'After analyzing the patient’s irregular electrocardiogram readings, the cardiologist recommended immediate surgical intervention to relieve arterial blockage.', 'Lesson 6', 6, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'careen', '/kəˈriːn/', 'v.', 'Nghiêng ngả, lao chao đảo mất kiểm soát', 'Losing traction on the slick mountain road, the heavy freight truck began to careen precariously toward the precipitous guardrail.', 'Lesson 6', 6, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caricature', '/ˈkærɪkətʃʊr/', 'n.', 'Tranh biếm họa, hình tượng châm biếm bóp méo', 'Political cartoonists of the Gilded Age often drew industrial monopolists as bloated, rapacious caricatures draped in bags of currency.', 'Lesson 6', 6, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'carnage', '/ˈkɑːrnɪdʒ/', 'n.', 'Cảnh tàn sát đẫm máu, sự thảm sát', 'Surveying the horrific carnage left on the battlefield after the artillery barrage, the young officer questioned the moral justification of the campaign.', 'Lesson 6', 6, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'carnal', '/ˈkɑːrnəl/', 'adj.', 'Thuộc về xác thịt, nhục dục trần tục', 'Medieval ascetic philosophers urged monks to transcend transient carnal desires in pursuit of enduring spiritual enlightenment.', 'Lesson 6', 6, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'carnivorous', '/kɑːrˈnɪvərəs/', 'adj.', 'Ăn thịt, ăn côn trùng (thực vật)', 'In nutrient-deficient bogs, carnivorous plants such as the pitcher plant have evolved specialized traps to capture insects and supplement their nitrogen intake.', 'Lesson 6', 6, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'carping', '/ˈkɑːrpɪŋ/', 'adj.', 'Hay soi mói, hay bắt bẻ vặt vãnh', 'Despite the unanimous critical acclaim garnered by the symphony, a few carping reviewers focused solely on negligible tempo fluctuations during the finale.', 'Lesson 6', 6, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cartographer', '/kɑːrˈtɑːɡrəfər/', 'n.', 'Nhà vẽ bản đồ, chuyên gia địa đồ', 'Employing newly refined sextants and celestial observations, the sixteenth-century cartographer drafted remarkably precise navigational charts of the Atlantic.', 'Lesson 6', 6, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cascade', '/kæˈskeɪd/', 'n.', 'Thác nước; chuỗi dồn dập, sự đổ dồn', 'A sudden failure in the subprime mortgage market triggered a cascade of financial insolvencies that quickly rippled across global banking institutions.', 'Lesson 6', 6, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'castigate', '/ˈkæstɪɡeɪt/', 'v.', 'Trừng phạt, khiển trách gay gắt', 'In his blistering editorial, the investigative journalist castigated municipal authorities for turning a blind eye to widespread industrial contamination.', 'Lesson 6', 6, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'casualty', '/ˈkæʒuəlti/', 'n.', 'Thương vong, nạn nhân; tổn thất', 'Although the battle resulted in surprisingly few military casualties, civilian infrastructure suffered catastrophic damage that required decades of reconstruction.', 'Lesson 6', 6, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cataclysm', '/ˈkætəklɪzəm/', 'n.', 'Đại hồng thủy; biến cố địa chất hoặc xã hội dữ dội', 'Paleontologists hypothesize that the Cretaceous extinction was precipitated by an extraterrestrial cataclysm that obscured sunlight and collapsed marine food webs.', 'Lesson 6', 6, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catapult', '/ˈkætəpʌlt/', 'v.', 'Phóng mạnh, đẩy vọt lên', 'The unexpected commercial success of her debut novel catapulted the recluse author into the dazzling spotlight of international literary acclaim.', 'Lesson 6', 6, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cataract', '/ˈkætərækt/', 'n.', 'Thác nước lớn; bệnh đục thủy tinh thể', 'Before modern surgical interventions were developed, an untreated cataract would inexorably cloud the lens of the human eye until complete blindness ensued.', 'Lesson 6', 6, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ceremonious', '/ˌserəˈməʊniəs/', 'adj.', 'Trịnh trọng, kiểu cách, câu nệ nghi thức', 'The ambassador greeted the visiting plenipotentiaries with ceremonious formality, observing every punctilio prescribed by court etiquette.', 'Lesson 6', 6, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catastrophe', '/kəˈtæstrəfi/', 'n.', 'Thảm họa, tai ương khốc liệt', 'The sudden breach of the earthen dam precipitated an ecological catastrophe, engulfing fragile riparian wetlands in millions of gallons of toxic residue.', 'Lesson 6', 6, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catcall', '/ˈkætkɔːl/', 'n.', 'Tiếng la ó phản đối, tiếng huýt sáo châm chọc', 'As the controversial speaker took the podium, his opening remarks were momentarily drowned out by derisive catcalls from the hostile auditorium.', 'Lesson 6', 6, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catechism', '/ˈkætəkɪzəm/', 'n.', 'Sách giáo lý vấn đáp; hệ nguyên lý căn bản', 'Reared in the austere puritanical schoolhouse, the young pupils were compelled to recite every article of the theological catechism from memory.', 'Lesson 6', 6, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'categorical', '/ˌkætəˈɡɔːrɪkl/', 'adj.', 'Tuyệt đối, khẳng định dứt khoát, không điều kiện', 'Confronted with allegations of corruption, the cabinet minister issued a categorical denial, asserting that no public funds had been misappropriated.', 'Lesson 6', 6, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cater', '/ˈkeɪtər/', 'v.', 'Phục vụ nhu cầu, chiều theo', 'Critics lamented that the news network increasingly catered to sensationalism rather than providing sober, analytical coverage of international crises.', 'Lesson 6', 6, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catharsis', '/kəˈθɑːrsɪs/', 'n.', 'Sự thanh lọc tâm hồn, sự giải tỏa cảm xúc', 'Aristotle argued that dramatic tragedy purges the audience of pity and terror, achieving an emotional catharsis that restores psychological equilibrium.', 'Lesson 6', 6, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'catholic', '/ˈkæθəlɪk/', 'adj.', 'Rộng rãi, bao quát, đa dạng nhiều lĩnh vực', 'Blessed with catholic intellectual curiosity, the Renaissance polymath authored foundational treatises in fields as disparate as botany, optics, and theology.', 'Lesson 6', 6, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caucus', '/ˈkɔːkəs/', 'n.', 'Cuộc họp kín nội bộ đảng chính trị', 'Behind the closed doors of the party caucus, rival factions engaged in intense horse-trading to secure delegate votes before the primary.', 'Lesson 6', 6, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caulk', '/kɔːk/', 'v.', 'Trét kín, xảm kín khe hở chống thấm', 'Before embarking on the transatlantic voyage, the shipwrights meticulously caulked the seams of the wooden schooner with oakum and heated pitch.', 'Lesson 6', 6, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'causal', '/ˈkɔːzl/', 'adj.', 'Thuộc quan hệ nhân quả', 'Epidemiologists emphasized that observing a strong statistical correlation between dietary habits and disease incidence does not inherently establish a causal relationship.', 'Lesson 6', 6, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'caustic', '/ˈkɔːstɪk/', 'adj.', 'Ăn mòn hóa học; châm chọc cay độc', 'The drama critic was renowned for her caustic wit, often eviscerating pretentious Broadway productions with a few sharply turned phrases.', 'Lesson 6', 6, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cavalcade', '/ˌkævlˈkeɪd/', 'n.', 'Đoàn người hoặc xe diễu hành trang trọng', 'A colorful cavalcade of equestrian performers, musicians, and heralds wound its way through the cobbled streets during the annual harvest festival.', 'Lesson 6', 6, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cavalier', '/ˌkævəˈlɪər/', 'adj.', 'Khinh khỉnh, coi thường, bừa bãi thiếu cẩn trọng', 'Environmental regulators penalized the chemical manufacturer for its cavalier attitude toward hazardous waste disposal, citing repeated safety violations.', 'Lesson 6', 6, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cavil', '/ˈkævl/', 'v.', 'Bắt bẻ vô lý, soi mói chuyện vụn vặt', 'Rather than addressing the substantive constitutional issues raised by the reform bill, opponents chose to cavil over minor syntactic ambiguities in its preamble.', 'Lesson 6', 6, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cede', '/siːd/', 'v.', 'Nhượng lại, giao nộp quyền lực hoặc lãnh thổ', 'Under the terms of the 1848 treaty, the defeated empire was coerced to cede vast swaths of its northern territories to its encroaching neighbor.', 'Lesson 6', 6, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'celebrated', '/ˈselɪbreɪtɪd/', 'adj.', 'Lừng danh, nổi tiếng và được tôn vinh', 'The celebrated ornithologist dedicated her life to cataloging endangered raptor populations across the mountainous wilderness of Central Asia.', 'Lesson 6', 6, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'celerity', '/səˈlerəti/', 'n.', 'Sự mau lẹ, tốc độ nhanh chóng', 'Recognizing the imminent threat of flooding, the corps of engineers fortified the crumbling levee with commendable celerity.', 'Lesson 6', 6, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'celestial', '/səˈlestʃl/', 'adj.', 'Thuộc về bầu trời, thiên thể; thần thánh', 'Without magnetic compasses or landmarks, early Polynesian navigators charted their oceanic voyages by observing the nightly trajectories of celestial bodies.', 'Lesson 6', 6, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'celibate', '/ˈselɪbət/', 'adj.', 'Độc thân, tiết dục, kiêng quan hệ tình dục', 'The monastic order required its members to take a solemn vow of poverty, obedience, and a celibate lifestyle dedicated entirely to religious contemplation.', 'Lesson 6', 6, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'censor', '/ˈsensər/', 'n.', 'Nhân viên kiểm duyệt', 'During wartime, the military censor systematically redacted sensitive tactical information and coordinates from soldiers'' correspondence home.', 'Lesson 6', 6, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'censorious', '/senˈsɔːriəs/', 'adj.', 'Hay chỉ trích, khắt khe săm soi', 'In her letters to her sister, Jane Austen gently satirized the censorious neighbors who scrutinized everyone''s moral conduct while overlooking their own hypocrisies.', 'Lesson 6', 6, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'censure', '/ˈsenʃər/', 'n.', 'Sự chỉ trích nghiêm khắc, lời khiển trách chính thức', 'The rogue intelligence analyst faced severe legislative censure after leaking classified documents regarding surveillance operations to the international press.', 'Lesson 6', 6, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'centigrade', '/ˈsentɪɡreɪd/', 'adj.', 'Bách phân, thang nhiệt độ Celsius', 'In their laboratory report, the physical chemists documented that the compound decomposed rapidly when ambient temperatures surpassed forty degrees centigrade.', 'Lesson 6', 6, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'centripetal', '/senˈtrɪpɪtl/', 'adj.', 'Hướng tâm, có xu hướng hút về tâm', 'In classical mechanics, the centripetal force exerted by gravity maintains planets in stable elliptical orbits around the sun.', 'Lesson 6', 6, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'centurion', '/senˈtʃʊəriən/', 'n.', 'Bách nhân đội trưởng La Mã', 'Excavations at the Roman garrison revealed a funerary monument erected in honor of a centurion who had commanded a century of the Tenth Legion.', 'Lesson 6', 6, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cerebral', '/ˈserəbrəl/', 'adj.', 'Thuộc về não bộ; thiên về lý trí và trí tuệ', 'While traditional espionage thrillers rely on kinetic combat, the author''s cerebral novel focused instead on the psychological chess match between rival decoders.', 'Lesson 6', 6, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cerebration', '/ˌserəˈbreɪʃn/', 'n.', 'Hoạt động tư duy, sự vận dụng trí óc', 'Deciphering the encrypted cuneiform tablets required months of intense cerebration and comparative philological analysis by an international team of scholars.', 'Lesson 6', 6, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'certitude', '/ˈsɜːrtɪtuːd/', 'n.', 'Sự tin chắc tuyệt đối, sự đoan chắc', 'Despite widespread skepticism among his peers, the astronomer defended his unorthodox planetary model with unshakeable certitude.', 'Lesson 6', 6, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cessation', '/seˈseɪʃn/', 'n.', 'Sự đình chỉ, sự chấm dứt hoàn toàn', 'A temporary cessation of hostilities was brokered to allow the Red Cross to deliver emergency rations and medical supplies to trapped noncombatants.', 'Lesson 6', 6, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cession', '/ˈseʃn/', 'n.', 'Sự nhượng lại quyền lợi hoặc lãnh thổ theo hòa ước', 'The territorial cession stipulated by the armistice redrew national boundaries and displaced thousands of indigenous inhabitants along the frontier.', 'Lesson 6', 6, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chafe', '/tʃeɪf/', 'v.', 'Trầy xước do cọ xát; bứt rứt, khó chịu vì bị gò ép', 'Rebellious colonists began to chafe under the onerous maritime tariffs and quartering acts imposed by Parliament without colonial representation.', 'Lesson 6', 6, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chaff', '/tʃæf/', 'n.', 'Vỏ trấu; đồ vô giá trị, rác rưởi bị loại bỏ', 'An astute investigative reporter must learn to discard misleading public relations chaff and focus strictly on substantiated financial records.', 'Lesson 6', 6, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chaffing', '/ˈtʃæfɪŋ/', 'n.', 'Sự trêu chọc thân mật, lời giễu cợt hài hước', 'Beneath the relentless intellectual chaffing between the two senior professors lay a profound mutual respect developed over three decades of collaboration.', 'Lesson 6', 6, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chagrin', '/ʃəˈɡrɪn/', 'n.', 'Nỗi thất vọng ê chề, sự bực bội vì bẽ mặt', 'Much to the chagrin of the incumbent prime minister, an unforeseen scandal caused his coalition to collapse just weeks before the general election.', 'Lesson 6', 6, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chalice', '/ˈtʃælɪs/', 'n.', 'Chén thánh, cốc tế lễ', 'During the medieval communion liturgy, the priest elevated the silver chalice containing sacramental wine before the kneeling congregation.', 'Lesson 6', 6, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chameleon', '/kəˈmiːliən/', 'n.', 'Tắc kè hoa; kẻ cơ hội dễ dàng đổi phe', 'Historians often describe the foreign minister as an opportunistic chameleon who adeptly altered his ideological commitments to survive three successive regime changes.', 'Lesson 6', 6, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'champion', '/ˈtʃæmpiən/', 'v.', 'Tích cực ủng hộ, bảo vệ và đấu tranh cho', 'Throughout her legislative career, the senator championed landmark environmental legislation designed to protect old-growth forests from commercial logging.', 'Lesson 6', 6, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'charisma', '/kəˈrɪzmə/', 'n.', 'Sức hút cá nhân, uy tín lôi cuốn quần chúng', 'The populist leader possessed an electrifying charisma that magnetized disenfranchised voters and galvanized mass rallies across the nation.', 'Lesson 6', 6, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'charlatan', '/ˈʃɑːrlətən/', 'n.', 'Kẻ bịp bợm, kẻ giả danh chuyên môn, lang băm', 'The 19th-century patent medicine salesman was eventually unmasked as a charlatan whose miraculous panacea was merely tainted well water and grain alcohol.', 'Lesson 6', 6, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chary', '/ˈtʃeri/', 'adj.', 'Thận trọng dè dặt, cảnh giác', 'Having suffered catastrophic losses during the previous market collapse, venture capitalists were exceedingly chary about investing in unproven artificial intelligence startups.', 'Lesson 6', 6, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chasm', '/ˈkæzəm/', 'n.', 'Vực sâu, hẻm núi sâu; sự chia rẽ sâu sắc', 'The ideological chasm separating the two political parties has steadily widened, paralyzing congressional negotiations on fiscal reform.', 'Lesson 6', 6, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chassis', '/ˈʃæsi/', 'n.', 'Khung gầm xe, bệ khung chịu lực', 'Engineers reinforced the vehicle''s tubular steel chassis to withstand the brutal torsional stresses encountered on off-road terrain.', 'Lesson 6', 6, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chaste', '/tʃeɪst/', 'adj.', 'Trong trắng, tiết hạnh; giản dị mộc mạc', 'Rejecting the gilded extravagances of Rococo decor, the architect adopted a chaste, austere aesthetic characterized by clean geometric lines and unadorned limestone.', 'Lesson 6', 6, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chasten', '/ˈtʃeɪsən/', 'v.', 'Trừng phạt để răn dạy, làm cho khiêm nhường hơn', 'The stinging rebuke from the senior judicial panel served to chasten the ambitious prosecutor, compelling him to observe stricter ethical boundaries.', 'Lesson 7', 7, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chastise', '/tʃæˈstaɪz/', 'v.', 'Chỉ trích gay gắt, khiển trách nặng nề', 'The congressional committee convened publicly to chastise the corporate executives for withholding crucial safety evaluations from the public.', 'Lesson 7', 7, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chauvinist', '/ˈʃoʊvɪnɪst/', 'n.', 'Kẻ theo chủ nghĩa sô-vanh, người mù quáng tôn sùng phe mình', 'In his treatise on international relations, the political theorist warned that a chauvinist often mistakes blind hostility toward foreign customs for authentic civic virtue.', 'Lesson 7', 7, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'check', '/tʃek/', 'v.', 'Kìm hãm, ngăn chặn đà phát triển', 'The constitutional framers instituted an elaborate system of divided branches to check the dangerous expansion of executive authority.', 'Lesson 7', 7, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'checkered', '/ˈtʃekərd/', 'adj.', 'Nhiều thăng trầm, đầy biến động và tì vết', 'Despite the diplomat''s checkered past, marked by ethical controversies and financial entanglements, his deep understanding of regional alliances proved indispensable.', 'Lesson 7', 7, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cherubic', '/tʃəˈruːbɪk/', 'adj.', 'Ngây thơ, phúc hậu như thiên thần', 'Beneath his cherubic countenance and gentle demeanor lay the calculating intellect of a formidable courtroom strategist.', 'Lesson 7', 7, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chicanery', '/ʃɪˈkeɪnəri/', 'n.', 'Mưu mô gian xảo, trò xảo quyệt', 'Investigative reporters uncovered an elaborate web of accounting chicanery designed to conceal the corporation''s insolvency from creditors.', 'Lesson 7', 7, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chide', '/tʃaɪd/', 'v.', 'Quở trách nhẹ nhàng, nhắc nhở bảo ban', 'The laboratory director gently chided the research fellows for skipping the secondary calibration protocols in their haste to publish.', 'Lesson 7', 7, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chimerical', '/kaɪˈmerɪkəl/', 'adj.', 'Ảo tưởng, viển vông, không tưởng', 'Prominent economists dismissed the candidate''s promise of perpetual industrial growth without inflation as a chimerical illusion.', 'Lesson 7', 7, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chisel', '/ˈtʃɪzəl/', 'v.', 'Đục đẽo; lừa đảo chiếm đoạt tiền của', 'Exploiting technical ambiguities in the probate code, the predatory broker attempted to chisel the vulnerable heirs out of their rightful inheritance.', 'Lesson 7', 7, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'choleric', '/ˈkɑːlərɪk/', 'adj.', 'Nóng nảy, hay cáu kỉnh, dễ nổi giận', 'Known for his choleric temperament, the tyrannical commander would summarily court-martial subordinates over minor infractions of camp protocol.', 'Lesson 7', 7, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'choreography', '/ˌkɔːriˈɑːɡrəfi/', 'n.', 'Nghệ thuật biên đạo múa, sự dàn dựng động tác', 'Balanchine''s avant-garde choreography dispensed with elaborate theatrical sets, focusing solely on the pure geometric precision of the dancers'' bodies.', 'Lesson 7', 7, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chortle', '/ˈtʃɔːrtəl/', 'v.', 'Cười nắc nẻ, cười khúc khích khoái chí', 'Hearing the defendant''s outlandish excuse, the seasoned magistrate began to chortle softly before composing himself to deliver the verdict.', 'Lesson 7', 7, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chronic', '/ˈkrɑːnɪk/', 'adj.', 'Kéo dài kinh niên, mãn tính, lặp đi lặp lại', 'Sociologists discovered that chronic underfunding of neighborhood municipal infrastructure directly contributed to entrenched economic stagnation.', 'Lesson 7', 7, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'chronicle', '/ˈkrɑːnɪkəl/', 'n.', 'Biên niên sử, bản ghi chép sự kiện theo thời gian', 'The medieval monk''s illuminated chronicle remains an indispensable primary source for documenting daily life and climatic shocks during the Great Famine.', 'Lesson 7', 7, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'churlish', '/ˈtʃɜːrlɪʃ/', 'adj.', 'Thô lỗ, cộc cằn, khiếm nhã', 'Critics regarded it as exceptionally churlish when the prize recipient used his acceptance speech to disparage the jurists who had honored him.', 'Lesson 7', 7, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cipher', '/ˈsaɪfər/', 'n.', 'Mật mã; người vô danh không có thực quyền', 'Bletchley Park mathematicians constructed electromechanical engines to decipher the complex rotor-based cipher generated by naval Enigma machines.', 'Lesson 7', 7, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circuitous', '/sərˈkjuːɪtəs/', 'adj.', 'Vòng vo, quanh co, không trực tiếp', 'To circumvent heavily mined arterial corridors, the supply caravan took a circuitous mountain detour that added three days to the journey.', 'Lesson 7', 7, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumlocution', '/ˌsɜːrkəmləˈkjuːʃən/', 'n.', 'Cách nói vòng vo, sự dài dòng quanh co né tránh', 'Impatient with the spokesperson''s evasive circumlocution, the press corps demanded an unvarnished statement regarding the environmental impact of the pipeline.', 'Lesson 7', 7, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumscribe', '/ˈsɜːrkəmspraɪb/', 'v.', 'Giới hạn, hạn chế phạm vi', 'The landmark Supreme Court ruling sought to circumscribe the state''s power to regulate private digital communications without a warrant.', 'Lesson 7', 7, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumspect', '/ˈsɜːrkəmspekt/', 'adj.', 'Thận trọng, dè dặt, cảnh giác', 'Given the precarious geopolitical climate, the ambassador maintained a circumspect neutrality throughout the multi-state summit.', 'Lesson 7', 7, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'circumvent', '/ˌsɜːrkəmˈvent/', 'v.', 'Né tránh, lách luật, vượt qua khôn khéo', 'Multinational conglomerates routinely establish shell corporations in offshore tax havens to circumvent strict domestic revenue statutes.', 'Lesson 7', 7, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cistern', '/ˈsɪstərn/', 'n.', 'Bể chứa nước, bể trữ nước mưa', 'During prolonged summer droughts, the Mediterranean hilltop village relied exclusively on rainwater collected within a subterranean stone cistern.', 'Lesson 7', 7, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'citadel', '/ˈsɪtədəl/', 'n.', 'Thành trì, pháo đài kiên cố', 'Perched menacingly atop the rocky promontory, the medieval citadel commanded an unhindered defensive view of the entire harbor.', 'Lesson 7', 7, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cite', '/saɪt/', 'v.', 'Trích dẫn, viện dẫn chứng cứ', 'In her landmark paper on cognitive development, the psychologist cited extensive longitudinal studies spanning over four decades.', 'Lesson 7', 7, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clairvoyant', '/klerˈvɔɪənt/', 'n.', 'Người có khả năng thấu thị, người tiên tri', 'Although dismissing supernatural phenomena, the historian noted how the nineteenth-century spiritualist posed as a clairvoyant to sway impressionable aristocrats.', 'Lesson 7', 7, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clamber', '/ˈklæmbər/', 'v.', 'Leo trèo nhọc nhằn bằng cả tay chân', 'Weighed down by their heavy observational packs, the botanists had to clamber over slick basalt boulders to reach the rare alpine flora.', 'Lesson 7', 7, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clamor', '/ˈklæmər/', 'n.', 'Tiếng la ó ầm ĩ, sự phản đối kịch liệt từ đám đông', 'Despite the rising public clamor for immediate regulatory intervention, the legislature delayed voting on the sweeping tariff proposal.', 'Lesson 7', 7, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clandestine', '/klænˈdestɪn/', 'adj.', 'Lén lút, bí mật, bất minh', 'A clandestine meeting between factional emissaries took place in an unassuming border inn to negotiate the terms of an armistice.', 'Lesson 7', 7, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clangor', '/ˈklæŋɡər/', 'n.', 'Tiếng loảng xoảng, tiếng kim loại va đập vang rền', 'The deafening clangor of broadswords against bronze shields echoed through the mountain pass long before the dust of battle settled.', 'Lesson 7', 7, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clapper', '/ˈklæpər/', 'n.', 'Quả lắc chuông', 'Corroded by centuries of ocean mist, the heavy iron clapper broke loose from the harbor bell, silencing the town''s primary storm warning.', 'Lesson 7', 7, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clasp', '/klæsp/', 'v.', 'Nắm chặt, siết chặt; cái móc cài', 'Trembling with solemn conviction, the young diplomat clasped the parchment treaty as if it were the sole barrier preventing total war.', 'Lesson 7', 7, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'claustrophobia', '/ˌklɔːstrəˈfoʊbiə/', 'n.', 'Hội chứng sợ không gian kín hẹp', 'Submarine crew members must undergo rigorous psychological evaluations to ensure they do not suffer from latent claustrophobia during protracted deep-sea patrols.', 'Lesson 7', 7, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cleave', '/kliːv/', 'v.', 'Chẻ đôi, chia rẽ; hoặc bám chặt lấy', 'Deep ideological disagreements over federal taxation threatened to cleave the young republic into irreconcilable regional factions.', 'Lesson 7', 7, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clemency', '/ˈklemənsi/', 'n.', 'Lòng khoan dung, sự khoan hồng nhân từ', 'Despite public outrage over the seditious uprising, the monarch exercised clemency by commuting the conspirators'' death sentences to exile.', 'Lesson 7', 7, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clench', '/klentʃ/', 'v.', 'Nghiến (răng), siết chặt (nắm tay)', 'Enduring the blistering interrogation without uttering a single betraying name, the captive courier could only clench his jaw in defiant silence.', 'Lesson 7', 7, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clientele', '/ˌklaɪənˈtel/', 'n.', 'Tệp khách hàng, nhóm khách hàng quen', 'By specializing in rare Enlightenment manuscripts, the boutique antiquarian drew an affluent clientele of academic collectors and museum curators.', 'Lesson 7', 7, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'climactic', '/klaɪˈmæktɪk/', 'adj.', 'Mang tính cao trào, tạo nên đỉnh điểm', 'In the climactic sequence of the symphony, the brass fanfare ascends dramatically to resolve the harmonic tension established throughout the preceding movements.', 'Lesson 7', 7, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clime', '/klaɪm/', 'n.', 'Xứ sở, miền khí hậu', 'Disillusioned by the damp gray skies of London, the Romantic poet journeyed to an idyllic Mediterranean clime to seek restorative warmth and creative solace.', 'Lesson 7', 7, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'clique', '/kliːk/', 'n.', 'Bè phái, nhóm cánh hẩu khép kín', 'An entrenched clique of senior cabinet ministers monopolized key economic decisions, effectively freezing out junior legislators and reformist advisers.', 'Lesson 7', 7, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cloister', '/ˈklɔɪstər/', 'v.', 'Sống ẩn dật, giam mình tách biệt; tu viện', 'Tired of court intrigues and bureaucratic exhaustion, the retired statesman chose to cloister himself in his countryside estate to write his memoirs.', 'Lesson 7', 7, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cloying', '/ˈklɔɪɪŋ/', 'adj.', 'Ngọt ngấy, quá ủy mị gây ngán ngẩm', 'Literary critics condemned the Victorian melodrama for its cloying sentimentality, arguing that unearned emotionalism detracted from its moral thesis.', 'Lesson 7', 7, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coagulate', '/koʊˈæɡjəleɪt/', 'v.', 'Làm đông tụ, vón cục lại', 'When snake venom containing powerful hemotoxins enters the bloodstream, it causes fibrinogen to coagulate instantly, provoking fatal thrombosis.', 'Lesson 7', 7, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coalesce', '/ˌkoʊəˈles/', 'v.', 'Hợp nhất, kết tụ thành một khối thống nhất', 'Astrophysicists hypothesize that planetary bodies originated when microscopic grains of cosmic dust coalesced under gravitational attraction over billions of years.', 'Lesson 7', 7, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coalition', '/ˌkoʊəˈlɪʃən/', 'n.', 'Khối liên minh, sự liên minh giữa các đảng phái', 'To pass the landmark environmental legislation, progressive lawmakers forged a historic coalition with moderate agrarian representatives.', 'Lesson 7', 7, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coddle', '/ˈkɑːdəl/', 'v.', 'Nuông chiều quá mức, cưng chiều thái quá', 'The rigorous military academy refused to coddle new recruits, believing that harsh conditions and strict discipline were essential to forging resilient commanders.', 'Lesson 7', 7, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'codicil', '/ˈkɑːdɪsɪl/', 'n.', 'Phụ lục di chúc, điều khoản bổ sung di chúc', 'Suspecting undue influence, the disinherited relatives contested the validity of a handwritten codicil executed only hours before the magnate''s demise.', 'Lesson 7', 7, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'codify', '/ˈkɑːdɪfaɪ/', 'v.', 'Hệ thống hóa thành luật lệ, pháp điển hóa', 'The Napoleonic Code was groundbreaking because it systematically codified civil liberties, property rights, and uniform judicial procedures across post-revolutionary France.', 'Lesson 7', 7, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coercion', '/koʊˈɜːrʒən/', 'n.', 'Sự ép buộc, cưỡng chế bằng vũ lực hoặc đe dọa', 'International human rights monitors argued that the treaty signed under implicit military coercion lacked legal legitimacy and should be nullified.', 'Lesson 7', 7, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cogent', '/ˈkoʊdʒənt/', 'adj.', 'Có sức thuyết phục, chặt chẽ, đanh thép', 'In a cogent critique of contemporary fiscal policy, the economist demonstrated how unregulated speculative lending precipitates severe banking crises.', 'Lesson 7', 7, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cogitate', '/ˈkɒdʒ.ɪ.teɪt/', 'v.', 'Suy ngẫm, suy nghĩ thấu đáo', 'Before issuing his landmark judicial opinion, the Chief Justice retreated to his rural estate to cogitate on the constitutional limits of executive emergency decrees.', 'Lesson 7', 7, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cognate', '/ˈkɒɡ.neɪt/', 'adj.', 'Cùng nguồn gốc, có họ hàng gần', 'Comparative philologists demonstrated that English ''father'' and Latin ''pater'' are cognate words descended from a single Proto-Indo-European root.', 'Lesson 7', 7, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cognitive', '/ˈkɒɡ.nə.tɪv/', 'adj.', 'Thuộc về nhận thức', 'Developmental psychologists observed that interactive bilingual immersion significantly enhances executive function and cognitive flexibility in young children.', 'Lesson 7', 7, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cognizance', '/ˈkɒɡ.nɪ.zəns/', 'n.', 'Sự nhận biết, sự thẩm tri', 'The international war crimes tribunal took judicial cognizance of satellite imagery documenting deliberate attacks on civilian infrastructure.', 'Lesson 7', 7, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cohere', '/kəʊˈhɪər/', 'v.', 'Gắn kết chặt chẽ, mạch lạc', 'Although the archival manuscript contained fragmented testimonies from disparate witnesses, its core narrative threads cohere into a devastating chronicle of the siege.', 'Lesson 7', 7, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cohesion', '/kəʊˈhiː.ʒən/', 'n.', 'Sự gắn kết, tính liên kết', 'Sociologists argue that widening income inequality erodes civic cohesion, fostering mutual suspicion among disparate economic classes.', 'Lesson 7', 7, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coiffure', '/kwɑːˈfjʊər/', 'n.', 'Kiểu tóc cầu kỳ', 'In aristocratic portraits of the French court, noblewomen displayed towering powdered coiffures adorned with miniature porcelain ships and silk flora.', 'Lesson 7', 7, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coin', '/kɔɪn/', 'v.', 'Đặt ra, sáng tạo ra (từ ngữ, thuật ngữ)', 'Confronted by totalitarian atrocities unprecedented in legal history, jurist Raphael Lemkin was forced to coin the term ''genocide'' in 1944.', 'Lesson 7', 7, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coincidence', '/kəʊˈɪn.sɪ.dəns/', 'n.', 'Sự trùng hợp ngẫu nhiên', 'Historians dismissed the assertion that the simultaneous rebellions across three continents were a mere coincidence, pointing to synchronized grain shortages driven by volcanic eruptions.', 'Lesson 7', 7, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'colander', '/ˈkɒl.ən.dər/', 'n.', 'Cái rổ có lỗ thoát nước', 'Archaeologists excavating Pompeian culinary ruins recovered a remarkably preserved bronze colander perforated with intricate geometric drainage patterns.', 'Lesson 7', 7, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collaborate', '/kəˈlæb.ə.reɪt/', 'v.', 'Hợp tác, cộng tác', 'To map the migration corridors of polar megafauna, climatologists and marine ecologists must collaborate across national and institutional boundaries.', 'Lesson 7', 7, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collage', '/ˈkɒl.ɑːʒ/', 'n.', 'Nghệ thuật cắt dán, tác phẩm ghép mảnh', 'Dadaist artists assembled visceral collages of battlefield photographs, propaganda pamphlets, and industrial scrap to protest the senseless carnage of the Great War.', 'Lesson 7', 7, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collate', '/kəˈleɪt/', 'v.', 'Đối chiếu và sắp xếp tài liệu', 'Before publishing the definitive scholarly edition, textual critics spent years collating variant readings across dozens of medieval folios.', 'Lesson 7', 7, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collateral', '/kəˈlæt.ər.əl/', 'n.', 'Tài sản thế chấp', 'Because the tenant farmers possessed no real estate to offer as collateral, commercial lenders routinely denied them the capital needed to modernize their equipment.', 'Lesson 7', 7, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'colloquial', '/kəˈləʊ.kwi.əl/', 'adj.', 'Thông tục, mang tính khẩu ngữ', 'The novelist''s dialogue achieves authentic emotional resonance by blending archaic pastoral cadences with brisk, colloquial city banter.', 'Lesson 7', 7, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compound', '/ˈkɒm.paʊnd/', 'n.', 'Hợp chất, phức hợp', 'When synthetic chemists exposed the volatile organic compound to ultraviolet radiation, its molecular bonds destabilized into inert gaseous byproducts.', 'Lesson 7', 7, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'collusion', '/kəˈluː.ʒən/', 'n.', 'Sự câu kết, sự thông đồng bí mật', 'The investigative commission uncovered systemic collusion between maritime shipping cartels and regional port officials to suppress commercial competition.', 'Lesson 7', 7, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'colossal', '/kəˈlɒs.əl/', 'adj.', 'Khổng lồ, to lớn dị thường', 'Deep beneath the ocean floor, sonar surveys detected a colossal caldera whose prehistoric collapse triggered global volcanic winters.', 'Lesson 7', 7, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comatose', '/ˈkəʊ.mə.təʊs/', 'adj.', 'Hôn mê, bất tỉnh', 'Suffering from severe cerebral hypoxia after the climbing accident, the mountaineer remained comatose for days while physicians monitored his brainstem reflexes.', 'Lesson 7', 7, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'combustible', '/kəmˈbʌs.tə.bəl/', 'adj.', 'Dễ cháy, dễ phát hỏa', 'Federal fire safety mandates require industrial warehouses to store combustible solvents in reinforced, temperature-regulated containment cells.', 'Lesson 7', 7, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comely', '/ˈkʌm.li/', 'adj.', 'Duyên dáng, thanh tú, ưa nhìn', 'In Thomas Hardy’s pastoral narratives, the protagonist is described as a comely country maiden whose rustic elegance contrasts sharply with Victorian vanity.', 'Lesson 7', 7, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comeuppance', '/kʌmˈʌp.əns/', 'n.', 'Sự trừng phạt thích đáng, quả báo', 'The tyrannical mill owner finally met his comeuppance when a unified labor strike and subsequent government audits stripped him of his industrial monopoly.', 'Lesson 7', 7, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commandeer', '/ˌkɒm.ənˈdɪər/', 'v.', 'Trưng dụng, trưng thu quân sự', 'As enemy regiments closed in on the capital, besieged commanders invoked martial law to commandeer commercial locomotives for civilian evacuation.', 'Lesson 7', 7, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commemorate', '/kəˈmem.ə.reɪt/', 'v.', 'Kỷ niệm, tưởng niệm', 'The municipal assembly commissioned an obsidian memorial wall to commemorate the abolitionist reformers who organized the clandestine escape routes.', 'Lesson 7', 7, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commensurate', '/kəˈmen.sjər.ət/', 'adj.', 'Tương xứng, phù hợp', 'The university provost maintained that faculty compensation and research grants must be commensurate with institutional performance and scholarly impact.', 'Lesson 7', 7, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commiserate', '/kəˈmɪz.ə.reɪt/', 'v.', 'Bày tỏ sự cảm thông, chia sẻ nỗi buồn', 'Gathered around the hearth after the harvest failed, impoverished homesteaders could only commiserate over their mounting bank debts and blighted crops.', 'Lesson 7', 7, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'commodious', '/kəˈməʊ.di.əs/', 'adj.', 'Rộng rãi, thoáng đãng', 'The architect designed a commodious lecture hall with tiered acoustic seating capable of comfortably accommodating over five hundred scholars.', 'Lesson 7', 7, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'communal', '/ˈkɒm.jə.nəl/', 'adj.', 'Thuộc về cộng đồng, dùng chung', 'Traditional Andean agrarian societies relied on communal irrigation networks maintained collectively by all village households.', 'Lesson 7', 7, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compact', '/ˈkɒm.pækt/', 'adj.', 'Nhỏ gọn, kết cấu chặt chẽ', 'To withstand gale-force Arctic winds, the explorers erected a compact dome tent engineered from interlocking carbon-fiber struts.', 'Lesson 7', 7, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comparable', '/ˈkɒm.pər.ə.bəl/', 'adj.', 'Có thể so sánh được, tương đương', 'Economists studying inflationary spirals found that post-war monetary instability in the Weimar Republic had few comparable precedents in modern history.', 'Lesson 7', 7, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compatible', '/kəmˈpæt.ə.bəl/', 'adj.', 'Tương thích, hòa hợp', 'Ecological philosophers debated whether unrestrained industrial consumerism is fundamentally compatible with global carbon neutrality.', 'Lesson 7', 7, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compelling', '/kəmˈpel.ɪŋ/', 'adj.', 'Có sức thuyết phục cao, hấp dẫn', 'The paleoclimatologist presented compelling empirical data demonstrating an unmistakable correlation between atmospheric carbon concentrations and prehistoric extinction events.', 'Lesson 7', 7, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compensatory', '/ˌkɒm.penˈseɪ.tər.i/', 'adj.', 'Có tính bù đắp, bồi thường', 'The appellate court upheld a multi-million-dollar compensatory settlement to mitigate the economic harm suffered by displaced coastal fisheries.', 'Lesson 7', 7, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compile', '/kəmˈpaɪl/', 'v.', 'Biên soạn, thu thập và tổng hợp', 'It took decades for lexicographers to compile thousands of dialectal citations into the comprehensive historical dictionary of the English language.', 'Lesson 7', 7, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complacency', '/kəmˈpleɪ.sən.si/', 'n.', 'Sự tự mãn, chủ quan', 'Prolonged fiscal surplus bred political complacency, blinding municipal policymakers to mounting infrastructure deficits until the bridges failed.', 'Lesson 7', 7, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complaisant', '/kəmˈpleɪ.zənt/', 'adj.', 'Chiều chuộng, hay nhân nhượng, dễ dãi', 'Eager to secure corporate sponsorships, the complaisant university trustees ratified the commercial contract without imposing any academic safeguards.', 'Lesson 7', 7, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complement', '/ˈkɒm.plɪ.mənt/', 'n.', 'Phần bổ sung, vật hoàn thiện', 'In physiological psychology, quantitative brain scans serve as an indispensable complement to qualitative behavioral observation.', 'Lesson 7', 7, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complementary', '/ˌkɒm.plɪˈmen.tər.i/', 'adj.', 'Bổ trợ lẫn nhau, tương hỗ', 'The botanist demonstrated that nitrogen-fixing legumes and deep-rooted grasses establish complementary rhizosphere relationships that enrich nutrient-poor soils.', 'Lesson 7', 7, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compliance', '/kəmˈplaɪ.əns/', 'n.', 'Sự tuân thủ, sự phục tùng', 'Regulatory agencies threatened severe financial sanctions if the chemical conglomerate failed to demonstrate full compliance with hazardous waste disposal statutes.', 'Lesson 7', 7, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compliant', '/kəmˈplaɪ.ənt/', 'adj.', 'Dễ phục tùng, ngoan ngoãn tuân thủ', 'Authoritarian regimes depend upon a compliant judiciary to rubber-stamp executive decrees and suppress dissent under the guise of legal procedure.', 'Lesson 7', 7, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'complicity', '/kəmˈplɪs.ə.ti/', 'n.', 'Sự đồng lõa, sự tòng phạm', 'Declassified diplomatic cables exposed the foreign ministry''s tacit complicity in financing covert paramilitary operations overseas.', 'Lesson 7', 7, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'component', '/kəmˈpəʊ.nənt/', 'n.', 'Thành phần, bộ phận cấu thành', 'Rigorous empirical replication remains an essential component of modern scientific methodology, guarding against flawed experimental designs.', 'Lesson 7', 7, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'composure', '/kəmˈpəʊ.ʒər/', 'n.', 'Sự điềm tĩnh, sự tự chủ', 'Despite virulent heckling from partisan demonstrators outside the parliament, the prime minister maintained her composure throughout the policy address.', 'Lesson 7', 7, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comprehensive', '/ˌkɒm.prɪˈhen.sɪv/', 'adj.', 'Toàn diện, bao quát', 'The environmental agency released a comprehensive longitudinal study assessing the cumulative ecological impacts of hydraulic fracturing on municipal aquifers.', 'Lesson 7', 7, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compress', '/kəmˈpres/', 'v.', 'Nén lại, ép chặt', 'Subduction zones at convergent tectonic plate boundaries compress marine sediments under tremendous geothermal pressure, converting them into metamorphic schist.', 'Lesson 7', 7, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'comprise', '/kəmˈpraɪz/', 'v.', 'Bao gồm, gồm có', 'The interdisciplinary research consortium will comprise geneticists, computational statisticians, and clinical oncologists from across four continents.', 'Lesson 7', 7, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compromise', '/ˈkɒm.prə.maɪz/', 'n.', 'Sự thỏa hiệp, sự dàn xếp', 'Historians consider the Great Compromise of 1787 crucial to the formation of the American republic, as it established proportional representation in the House alongside equal representation in the Senate.', 'Lesson 7', 7, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compunction', '/kəmˈpʌŋk.ʃən/', 'n.', 'Sự cắn rứt lương tâm, sự ân hận', 'Driven by ruthless corporate ambition, the unscrupulous financier raided the pension funds of thousands of factory workers without a twinge of compunction.', 'Lesson 7', 7, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'compute', '/kəmˈpjuːt/', 'v.', 'Tính toán, ước tính bằng số liệu', 'Early mechanical calculating machines designed by Charles Babbage relied on brass gear trains to compute polynomial mathematical tables with unprecedented precision.', 'Lesson 7', 7, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concave', '/kɒnˈkeɪv/', 'adj.', 'Lõm, cong vào trong', 'Astronomical observatories utilize massive concave mirrors to gather distant photons from faint celestial objects and converge them onto sensitive charge-coupled detectors.', 'Lesson 7', 7, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concede', '/kənˈsiːd/', 'v.', 'Thừa nhận, nhượng bộ, chịu thua', 'After forensic auditing uncovered incontrovertible discrepancies in the campaign ledgers, the incumbent was forced to concede defeat before the final ballots were tallied.', 'Lesson 8', 8, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conceit', '/kənˈsiːt/', 'n.', 'Tính tự phụ, thói kiêu ngạo; ẩn dụ nghệ thuật cầu kỳ', 'The metaphysical poet structured his entire elegy around an elaborate conceit comparing two parting lovers to the twin legs of a draftsman''s compass.', 'Lesson 8', 8, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concentric', '/kənˈsentrɪk/', 'adj.', 'Đồng tâm', 'Dendrochronologists analyzed the concentric growth rings of the ancient bristlecone pine to reconstruct centuries of severe drought and erratic climatic shifts.', 'Lesson 8', 8, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conception', '/kənˈsepʃn/', 'n.', 'Quan niệm, nhận thức, sự hình thành ý tưởng', 'The political philosopher argued that the Enlightenment’s conception of universal human rights emerged not from divine revelation, but from an unprecedented faith in human rationality.', 'Lesson 8', 8, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concerted', '/kənˈsɜːrtɪd/', 'adj.', 'Phối hợp chặt chẽ, có tính hiệp lực', 'Only through a concerted multilateral effort could the coalition nations enforce maritime sanctions and curb illegal trafficking across the disputed strait.', 'Lesson 8', 8, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concession', '/kənˈseʃn/', 'n.', 'Sự nhượng bộ, điều nhượng bộ', 'Labor union negotiators refused to ratify the proposed agreement until corporate management made a meaningful concession regarding overtime wages and workplace safety.', 'Lesson 8', 8, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conciliatory', '/kənˈsɪliətɔːri/', 'adj.', 'Có tính hòa giải, nhằm xoa dịu', 'In an effort to de-escalate diplomatic tensions following the border skirmish, the foreign minister delivered a conciliatory address emphasizing historical cultural ties and shared economic interests.', 'Lesson 8', 8, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'concise', '/kənˈsaɪs/', 'adj.', 'Ngắn gọn, súc tích', 'The executive summary offered a concise yet remarkably comprehensive appraisal of the firm''s fiscal liabilities, entirely omitting superfluous financial jargon.', 'Lesson 8', 8, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'contrived', '/kənˈtraɪvd/', 'adj.', 'Gượng ép, thiếu tự nhiên, sắp đặt vụng về', 'Literary critics dismissed the third act of the Victorian melodrama as utterly contrived, noting that the sudden discovery of a lost will resolved the protagonists'' dilemmas far too conveniently.', 'Lesson 8', 8, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'controvert', '/ˌkɑːntrəˈvɜːrt/', 'v.', 'Bác bỏ, tranh cãi, phủ nhận', 'The defense attorney introduced newly uncovered surveillance footage and forensic telemetry to controvert the prosecution''s claim that the defendant had been present at the crime scene.', 'Lesson 8', 8, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'contusion', '/kənˈtuːʒn/', 'n.', 'Vết đụng giập, vết bầm tím', 'Although radiological scans revealed no skeletal fractures after the equestrian fall, the deep contusion across the athlete''s ribs caused persistent respiratory discomfort for weeks.', 'Lesson 8', 8, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conundrum', '/kəˈnʌndrəm/', 'n.', 'Vấn đề nan giải, câu đố hóc búa', 'Urban demographers confront the perplexing conundrum of modernizing decrepit municipal infrastructure while preventing the rapid economic displacement of long-standing working-class residents.', 'Lesson 8', 8, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convene', '/kənˈviːn/', 'v.', 'Triệu tập, nhóm họp', 'When regional cease-fire negotiations collapsed, the Secretary-General exercised his statutory prerogative to convene an extraordinary emergency summit of regional leaders.', 'Lesson 8', 8, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convention', '/kənˈvenʃn/', 'n.', 'Quy ước, tập quán, hội nghị', 'By defiantly abandoning the nineteenth-century convention of the omniscient narrator, the modernist novelist presented an unstable, fractured subjective reality.', 'Lesson 8', 8, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conventional', '/kənˈvenʃənl/', 'adj.', 'Theo tập quán, truyền thống, thông thường', 'Rejecting conventional agronomic doctrines that favored heavy chemical inputs, the sustainable farm demonstrated that biodiverse crop rotation restored exhausted topsoil far more effectively.', 'Lesson 8', 8, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'converge', '/kənˈvɜːrdʒ/', 'v.', 'Hội tụ, cùng hướng về một điểm', 'During the spring migratory surge, millions of shorebirds converge upon the nutrient-rich Delaware Bay mudflats to feed on horseshoe crab eggs before continuing their arctic journey.', 'Lesson 8', 8, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conversant', '/kənˈvɜːrsnt/', 'adj.', 'Thông thạo, am tường, hiểu biết sâu sắc', 'To effectively litigate high-stakes patent disputes in modern biotechnology, an intellectual property lawyer must be thoroughly conversant with recombinant gene therapies and CRISPR editing.', 'Lesson 8', 8, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'converse', '/ˈkɑːnvɜːrs/', 'n.', 'Điều ngược lại, mệnh đề đảo', 'While robust economic development frequently reinforces democratic institutions, comparative political scientists note that the converse is not guaranteed, as authoritarian regimes can also achieve industrial growth.', 'Lesson 8', 8, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convert', '/kənˈvɜːrt/', 'v.', 'Chuyển đổi, biến đổi, cải đạo', 'Photovoltaic panels convert incident solar photons directly into electrical potential by freeing bound electrons within doped crystalline silicon wafers.', 'Lesson 8', 8, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convex', '/ˌkɑːnˈveks/', 'adj.', 'Lồi (hình học, quang học)', 'Unlike diverging concave lenses that spread optical rays outward, a convex magnifying lens refracts incident light inward toward a single concentrated focal point.', 'Lesson 8', 8, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conveyance', '/kənˈveɪəns/', 'n.', 'Sự vận chuyển, phương tiện chuyên chở, sự truyền tải', 'In nineteenth-century industrial London, the horse-drawn omnibus became the indispensable conveyance for clerks and artisans commuting from outlying hamlets to the central banking district.', 'Lesson 8', 8, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'conviction', '/kənˈvɪkʃn/', 'n.', 'Niềm tin mãnh liệt; phán quyết có tội', 'The abolitionist orator delivered his polemic with such unyielding moral conviction that even the most hardened skeptics in the assembly were compelled to reexamine their complicity in slavery.', 'Lesson 8', 8, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convivial', '/kənˈvɪviəl/', 'adj.', 'Vui vẻ, thân thiện, mang không khí hội hè ấm cúng', 'The ambassador fostered a convivial atmosphere at the diplomatic banquet, recognizing that informal camaraderie over fine dining could untangle disputes that formal summit protocols had failed to resolve.', 'Lesson 8', 8, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convoke', '/kənˈvoʊk/', 'v.', 'Triệu tập (hội nghị, đại hội)', 'Faced with an empty treasury and nationwide agrarian insurrections, King Louis XVI was reluctantly compelled to convoke the Estates-General at Versailles in May 1789.', 'Lesson 8', 8, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'convoluted', '/ˈkɑːnvəluːtɪd/', 'adj.', 'Rối rắm, phức tạp, quanh co', 'Forensic accountants spent months untangling the conglomerate''s convoluted network of shell corporations, which had been deliberately crafted to conceal offshore tax evasions.', 'Lesson 8', 8, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coquette', '/koʊˈket/', 'n.', 'Người phụ nữ lẳng lơ, thích tán tỉnh trêu đùa', 'In eighteenth-century satirical comedies, the playwright often juxtaposed the earnest, principled heroine against a calculating coquette who toyed with men''s affections solely for social elevation.', 'Lesson 8', 8, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cordial', '/ˈkɔːrdʒəl/', 'adj.', 'Thân ái, chân thành, niềm nở', 'Despite their vehement jurisprudential disagreements on constitutional interpretation, the two appellate judges maintained an exceptionally cordial relationship outside the courtroom.', 'Lesson 8', 8, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cordon', '/ˈkɔːrdn/', 'n.', 'Hàng rào cảnh sát, vòng đai phong tỏa', 'Heavily armed national guard units established an impenetrable security cordon around the capitol rotunda while ballots were being certified.', 'Lesson 8', 8, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cornucopia', '/ˌkɔːrnjuˈkoʊpiə/', 'n.', 'Nguồn dồi dào, sự phong phú vô tận', 'The newly unsealed state department archives provided an unexpected cornucopia of classified diplomatic cables for historians documenting Cold War backchannel negotiations.', 'Lesson 8', 8, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corollary', '/ˈkɔːrəleri/', 'n.', 'Hệ quả tất yếu, hệ luận', 'As an inevitable corollary to the rapid expansion of coal-powered manufacturing, industrial towns suffered catastrophic spikes in childhood pulmonary illnesses.', 'Lesson 8', 8, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coronation', '/ˌkɔːrəˈneɪʃn/', 'n.', 'Lễ đăng quang, lễ lên ngôi', 'The sumptuous coronation of Empress Elizabeth of Russia in 1742 showcased the imperial court''s westernized architectural grandeur to visiting foreign envoys.', 'Lesson 8', 8, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corporeal', '/kɔːrˈpɔːriəl/', 'adj.', 'Thuộc thể xác, hữu hình, có bản thể vật chất', 'In Neoplatonic philosophy, the soul is conceived as an immortal entity trapped temporarily within the frailties and illusions of the corporeal world.', 'Lesson 8', 8, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corpulent', '/ˈkɔːrpjələnt/', 'adj.', 'To béo, mập mạp', 'The political cartoonist lampooned the guild master as a corpulent plutocrat whose vast physical bulk stood in grotesque contrast to the emaciated textile weavers he employed.', 'Lesson 8', 8, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'correlation', '/ˌkɔːrəˈleɪʃn/', 'n.', 'Mối tương quan, sự liên hệ lẫn nhau', 'Longitudinal epidemiological studies established a distinct correlation between chronic exposure to fine particulate pollution and heightened incidence of neurodegenerative decline.', 'Lesson 8', 8, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corroborate', '/kəˈrɑːbəreɪt/', 'v.', 'Chứng thực, củng cố (bằng chứng, lời khai)', 'Geophysicists analyzed seismic reverberation data from deep borehole arrays to corroborate the computational model of mantle convection plumes.', 'Lesson 8', 8, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corrode', '/kəˈroʊd/', 'v.', 'Ăn mòn, gặm mòn, hủy hoại dần', 'Over decades of neglect, acidic rainfall and airborne industrial contaminants conspired to corrode the structural girders supporting the historic railway terminal.', 'Lesson 8', 8, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corrosive', '/kəˈroʊsɪv/', 'adj.', 'Ăn mòn, có tính tàn phá, hủy hoại dần', 'Political theorists argued that pervasive disinformation and institutional distrust exert a corrosive influence on the deliberative norms necessary for self-governance.', 'Lesson 8', 8, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'corrugated', '/ˈkɔːrəɡeɪtɪd/', 'adj.', 'Gợn sóng, có nếp gấp lượn sóng', 'Industrial packaging designers relied on corrugated fiberboard because its arched, wave-like fluting delivers remarkable compression strength while remaining extraordinarily lightweight.', 'Lesson 8', 8, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cosmopolitan', '/ˌkɑːzməˈpɑːlɪtən/', 'adj.', 'Mang tính quốc tế, có tầm nhìn toàn cầu, am hiểu thế giới', 'Hellenistic Alexandria emerged as a remarkably cosmopolitan metropolis, drawing scholars, astronomers, and merchants from across the Mediterranean basin and the Near East.', 'Lesson 8', 8, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'coterie', '/ˈkoʊtəri/', 'n.', 'Nhóm kín, nhóm người cùng chí hướng khép kín', 'The philosophical treatise was initially circulated only within an exclusive coterie of Cambridge mathematicians and logicians before gaining wider academic acclaim.', 'Lesson 8', 8, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'countenance', '/ˈkaʊntənəns/', 'n.', 'Sắc mặt, vẻ mặt, diện mạo; sự tán thành', 'Despite enduring hours of hostile interrogation by the parliamentary committee, the former prime minister maintained a placid countenance that revealed neither panic nor indignation.', 'Lesson 8', 8, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'countermand', '/ˌkaʊntərˈmænd/', 'v.', 'Hủy bỏ mệnh lệnh, phản lệnh', 'Realizing that the vanguard regiment was walking directly into a concealed crossfire, the brigadier general dispatched an orderly to immediately countermand the offensive order.', 'Lesson 8', 8, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'culvert', '/ˈkʌlvərt/', 'n.', 'Cống ngầm qua đường, rãnh thoát nước', 'When torrential monsoon rains breached the hillside drainage basin, debris clogged the stone culvert beneath the railway tracks, washing out the roadbed.', 'Lesson 8', 8, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cumbersome', '/ˈkʌmbərsəm/', 'adj.', 'Cồng kềnh, nặng nề, phiền toái', 'Early sixteenth-century diving apparatus proved so cumbersome and restrictive that undersea salvagers could barely maneuver along the seabed without risking asphyxiation.', 'Lesson 8', 8, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cumulative', '/ˈkjuːmjəleɪtɪv/', 'adj.', 'Tích lũy, dồn tụ, lũy tích', 'Marine biologists warned that the cumulative impact of chemical runoff, rising sea surface temperatures, and ocean acidification was pushing fragile coral reef ecosystems past tipping points.', 'Lesson 8', 8, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denounce', '/dɪˈnaʊns/', 'v.', 'Lên án kịch liệt, tố cáo công khai', 'Standing before the national congress, the civil rights activist boldly denounced the discriminatory housing legislation as an intolerable assault on constitutional equality.', 'Lesson 8', 8, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cupidity', '/kjuːˈpɪdəti/', 'n.', 'Lòng tham lam của cải, tính hám lợi', 'Driven by unbridled cupidity during the speculative mania, unscrupulous real estate promoters sold thousands of acres of uninhabitable swampland to gullible investors.', 'Lesson 8', 8, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'curator', '/kjʊˈreɪtər/', 'n.', 'Giám tuyển, người phụ trách bảo tàng hoặc bộ sưu tập', 'Working alongside restoration scientists, the museum curator authenticated the provenance of the newly attributed Baroque oil sketch using infrared reflectography.', 'Lesson 8', 8, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'curmudgeon', '/kərˈmʌdʒən/', 'n.', 'Người hay gắt gỏng, kẻ khó tính cay nghiệt', 'Despite his literary reputation as a snarling curmudgeon who abhorred public acclaim, the aging novelist quietly mentored dozens of aspiring young authors without charge.', 'Lesson 8', 8, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cursive', '/ˈkɜːrsɪv/', 'adj.', 'Chữ viết thảo, kiểu viết nối nét', 'Archivists struggled to transcribe the magistrate''s hasty cursive handwriting, which flowed in looping eighteenth-century script across the water-damaged parchment.', 'Lesson 8', 8, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cursory', '/ˈkɜːrsəri/', 'adj.', 'Nhanh, lướt qua, không kỹ lưỡng', 'A cursory inspection of the archival manuscripts failed to reveal the subtle marginalia that later proved crucial to deciphering the author''s true intent.', 'Lesson 8', 8, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'curtail', '/kɜːrˈteɪl/', 'v.', 'Cắt bớt, rút ngắn, hạn chế', 'In response to mounting inflationary pressures and widening budget deficits, the ministry was forced to curtail public expenditures on infrastructure.', 'Lesson 8', 8, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cynical', '/ˈsɪnɪkl/', 'adj.', 'Hoài nghi, cay độc, thiếu tin tưởng vào lòng tốt', 'Hardened by decades of political corruption and broken campaign promises, the electorate adopted an increasingly cynical view of government reform initiatives.', 'Lesson 8', 8, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'cynosure', '/ˈsaɪnəʃʊr/', 'n.', 'Trung tâm của sự chú ý, tâm điểm ngưỡng mộ', 'With its soaring cantilevered arches and iridescent glass facade, the newly inaugurated concert hall quickly became the architectural cynosure of the entire metropolis.', 'Lesson 8', 8, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dabble', '/ˈdæbl/', 'v.', 'Học đòi, tham gia một cách tài tử, không chuyên sâu', 'Although the Renaissance polymath chose to dabble in alchemy and astrology during his youth, his lasting intellectual legacy rested upon rigorous empirical mathematics.', 'Lesson 8', 8, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dais', '/ˈdeɪɪs/', 'n.', 'Bục danh dự, bục phát biểu', 'Ascending the velvet-draped dais at the front of the council chamber, the chancellor prepared to deliver his annual address to the assembled foreign dignitaries.', 'Lesson 8', 8, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dank', '/dæŋk/', 'adj.', 'Ẩm thấp, lạnh lẽo và khó chịu', 'Deep within the medieval fortress''s subterranean vaults, centuries of archival parchment were slowly degraded by the dank, unventilated air.', 'Lesson 8', 8, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dapper', '/ˈdæpər/', 'adj.', 'Gọn gàng, bảnh bao, tươm tất', 'Attired in a bespoke three-piece tweed suit and polished leather brogues, the dapper literary critic commanded immediate respect upon entering the lecture hall.', 'Lesson 8', 8, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dappled', '/ˈdæpld/', 'adj.', 'Lốm đốm, loang lổ bóng râm và ánh sáng', 'Midday sunlight filtering through the dense canopy of ancient oaks cast a dappled pattern of gold and deep shadow across the forest path.', 'Lesson 8', 8, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'daub', '/dɔːb/', 'v.', 'Phết, trét, bôi cẩu thả', 'Rejecting classical smoothing techniques, the neo-expressionist painter used a wooden spatula to daub thick impasto swathes of crimson across the canvas.', 'Lesson 8', 8, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'daunt', '/dɔːnt/', 'v.', 'Làm nản lòng, làm thoái chí', 'Neither the vast expanse of the frozen polar tundra nor the perilous threat of blizzards could daunt the resolute polar explorers.', 'Lesson 8', 8, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dauntless', '/ˈdɔːntləs/', 'adj.', 'Dũng cảm, kiên cường, bất khuất', 'Celebrated in maritime lore, the dauntless captain steered his battered frigate straight through the hurricane to rescue the stranded whaling fleet.', 'Lesson 8', 8, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dawdle', '/ˈdɔːdl/', 'v.', 'Nhởn nhơ, lãng phí thời gian, chậm chạp', 'With the tide rising swiftly toward the cliff base, the marine surveyors could not dawdle while gathering intertidal specimen samples.', 'Lesson 8', 8, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deadlock', '/ˈdedlɑːk/', 'n.', 'Sự đình trệ, tình trạng bế tắc hoàn toàn', 'Bipartisan congressional negotiations reached an intractable deadlock when both committees refused to concede on key statutory spending caps.', 'Lesson 8', 8, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deadpan', '/ˈdedpæn/', 'adj.', 'Thản nhiên, tỉnh bơ, không biểu cảm', 'Delivering devastating satirical commentary with a completely deadpan demeanor, the essayist maintained an unsmiling gravity that amplified the humor.', 'Lesson 8', 8, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dearth', '/dɜːrθ/', 'n.', 'Sự khan hiếm, tình trạng thiếu thốn', 'An acute dearth of dependable documentary records from the early medieval kingdom forces contemporary historians to rely heavily on archaeological fragments.', 'Lesson 8', 8, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debacle', '/deɪˈbɑːkl/', 'n.', 'Thất bại thảm hại, sự sụp đổ hoàn toàn', 'Plagued by critical software errors and unprecedented cost overruns, the highly publicized satellite deployment unravelled into an embarrassing public relations debacle.', 'Lesson 8', 8, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debase', '/dɪˈbeɪs/', 'v.', 'Làm giảm giá trị, làm suy đồi phẩm chất', 'To finance prolonged foreign conflicts, the Roman emperor ordered the imperial mint to debase silver denarii with inferior alloys of copper and tin.', 'Lesson 8', 8, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debauch', '/dɪˈbɔːtʃ/', 'v.', 'Làm đồi bại, sa đọa, làm hư hỏng', 'Exploiting the young nobleman''s sudden inheritance, unprincipled courtiers conspired to debauch his senses with illicit gambling and lavish revelry.', 'Lesson 8', 8, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debilitate', '/dɪˈbɪlɪteɪt/', 'v.', 'Làm suy nhược, làm kiệt quệ', 'A protracted drought threatened to debilitate the agrarian regional economy, exhausting groundwater reservoirs and stunting seasonal crop yields.', 'Lesson 8', 8, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debonair', '/ˌdebəˈner/', 'adj.', 'Lịch lãm, hào hoa, phong nhã', 'Possessing an easy elegance and quick cosmopolitan wit, the debonair ambassador put rival emissaries at ease during the contentious peace summit.', 'Lesson 8', 8, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debris', '/dəˈbriː/', 'n.', 'Mảnh vỡ, đống đổ nát, tàn tích', 'Following the seismic shockwave, geological teams carefully examined the volcanic debris strewn across the caldera to reconstruct the eruption sequence.', 'Lesson 8', 8, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debunk', '/ˌdiːˈbʌŋk/', 'v.', 'Vạch trần, bóc trần sự sai lệch', 'Through methodical spectroscopic analysis, the astrophysicist managed to debunk the sensational hypothesis that celestial signals originated from intelligent alien life.', 'Lesson 8', 8, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'debutante', '/ˈdebjuːtɑːnt/', 'n.', 'Thiếu nữ quý tộc lần đầu ra mắt giới thượng lưu', 'In Edwardian London, an aristocratic debutante was expected to observe strict rules of etiquette upon her presentation at the royal court.', 'Lesson 8', 8, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decadence', '/ˈdekədəns/', 'n.', 'Sự suy đồi, tình trạng sa đọa đạo đức hoặc văn hóa', 'Moral philosophers argued that the unchecked decadence of the gilded elite inevitably blinded them to the simmering grievances of the working class.', 'Lesson 8', 8, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decapitate', '/dɪˈkæpɪteɪt/', 'v.', 'Chặt đầu, xử trảm', 'During the zenith of the French Revolution, the radical Jacobin regime voted to decapitate King Louis XVI upon the scaffold in the Place de la Révolution.', 'Lesson 8', 8, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decelerate', '/ˌdiːˈseləreɪt/', 'v.', 'Giảm tốc độ, đi chậm lại', 'As monetary policymakers tightened credit to curb speculative bubbles, industrial investment and wage growth began to decelerate precipitously.', 'Lesson 8', 8, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deciduous', '/dɪˈsɪdʒuəs/', 'adj.', 'Rụng lá hằng năm, sớm rụng', 'Unlike the evergreen conifers dominating boreal landscapes, deciduous broadleaf trees enter winter dormancy by shedding their foliage to minimize moisture loss.', 'Lesson 8', 8, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decimate', '/ˈdesɪmeɪt/', 'v.', 'Tàn phá nặng nề, tiêu diệt số lượng lớn', 'The arrival of European pathogens such as smallpox proceeded to decimate indigenous populations who possessed no acquired immunological resistance.', 'Lesson 8', 8, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detergent', '/dɪˈtɜːrdʒənt/', 'n.', 'Chất tẩy rửa', 'Environmental chemists demonstrated that phosphorus-rich synthetic detergent runoff accelerates harmful algal blooms that deplete dissolved oxygen in aquatic habitats.', 'Lesson 8', 8, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decipher', '/dɪˈsaɪfər/', 'v.', 'Giải mã, làm sáng tỏ điều phức tạp', 'Working in seclusion at Bletchley Park, cryptanalysts designed early electromechanical computing devices to decipher encrypted Enigma military communications.', 'Lesson 8', 8, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'declivity', '/dɪˈklɪvəti/', 'n.', 'Dốc thoai thoải xuống, sườn dốc xuống', 'Heavy seasonal rains saturated the steep declivity above the mountain hamlet, causing dislodged boulders and mud to cascade down the hillside.', 'Lesson 8', 8, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decollete', '/ˌdeɪkɑːlˈteɪ/', 'adj.', 'Khoét sâu cổ áo', 'The portrait sparked aristocratic controversy for depicting the young marchioness in a daringly decollete velvet evening bodice.', 'Lesson 8', 8, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decomposition', '/ˌdiːˌkɑːmpəˈzɪʃn/', 'n.', 'Sự phân hủy, quá trình phân rã', 'Forest saprophytes play an indispensable ecological role by driving the decomposition of fallen timber into bioavailable soil nutrients.', 'Lesson 8', 8, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decorum', '/dɪˈkɔːrəm/', 'n.', 'Sự đúng mực, phép lịch sự, phong thái đoan trang', 'Even when enduring aggressive questioning during senate hearings, the judicial nominee preserved impeccable decorum and spoke in measured, respectful tones.', 'Lesson 8', 8, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decoy', '/ˈdiːkɔɪ/', 'n.', 'Mồi nhử, vật nghi binh đánh lạc hướng', 'Allied commanders positioned dummy inflatable tanks along the coastline to serve as an elaborate decoy, deceiving axis reconnaissance regarding the true invasion site.', 'Lesson 8', 8, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decrepit', '/dɪˈkrepɪt/', 'adj.', 'Già yếu, rệu rã, mục nát', 'The rural community struggled to preserve its decrepit timber covered bridge after decades of weathering and structural rot weakened its floor joists.', 'Lesson 8', 8, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decrepitude', '/dɪˈkrepɪtuːd/', 'n.', 'Tình trạng già yếu, sự rệu rã, tình trạng đổ nát', 'Once a resplendent symbol of imperial prestige, the abandoned palace succumbed to architectural decrepitude as weeds cracked its marble terraces.', 'Lesson 8', 8, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'decry', '/dɪˈkraɪ/', 'v.', 'Công khai chỉ trích, lên án', 'Humanitarian observers stepped forward to decry the arbitrary detention of peaceful demonstrators as an egregious violation of basic civil liberties.', 'Lesson 8', 8, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deducible', '/dɪˈduːsəbl/', 'adj.', 'Có thể suy luận được từ thông tin sẵn có', 'From the periodic dimming of the star''s stellar luminosity, the presence of an orbiting gas giant was readily deducible without direct telescopic imaging.', 'Lesson 8', 8, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deface', '/dɪˈfeɪs/', 'v.', 'Làm hư hại bề mặt, bôi bẩn làm mất mỹ quan', 'Outraged citizens condemned the vandals who conspired to deface the bronze war memorial with crude markings overnight.', 'Lesson 8', 8, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defame', '/dɪˈfeɪm/', 'v.', 'Phỉ báng, bôi nhọ thanh danh', 'In his opening statement, the barrister argued that sensationalist tabloids printed falsehoods specifically designed to defame the prime minister''s personal integrity.', 'Lesson 8', 8, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'default', '/dɪˈfɔːlt/', 'n.', 'Sự vỡ nợ, sự không thực hiện được nghĩa vụ', 'Fearing sovereign default on national sovereign bonds, credit rating agencies downgraded the country''s debt to junk status.', 'Lesson 8', 8, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defeatist', '/dɪˈfiːtɪst/', 'adj.', 'Bi quan, có tư tưởng chủ bại', 'The prime minister urged the wartime cabinet to banish all defeatist rhetoric and focus instead on mobilizing industrial capacity for national defense.', 'Lesson 8', 8, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defection', '/dɪˈfekʃn/', 'n.', 'Sự đào ngũ, sự phản bội đào tẩu', 'The sudden defection of the chief nuclear scientist dealt a catastrophic blow to the regime''s clandestine weapons development program.', 'Lesson 8', 8, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defer', '/dɪˈfɜːr/', 'v.', 'Trì hoãn, hoãn lại', 'Confronted by inconclusive clinical trial results, the regulatory panel voted to defer final approval of the therapeutic compound until further data emerged.', 'Lesson 8', 8, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deference', '/ˈdefərəns/', 'n.', 'Sự tôn kính, sự chiều theo ý kiến người khác vì nể trọng', 'Showing great deference to constitutional precedent, the appellate judges refrained from overturning the longstanding common-law doctrine.', 'Lesson 8', 8, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defiance', '/dɪˈfaɪəns/', 'n.', 'Sự thách thức, thái độ bất tuân công khai', 'Standing resolutely before an unyielding military cordon, the factory strikers raised their banners in collective defiance of the martial decree.', 'Lesson 8', 8, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defile', '/dɪˈfaɪl/', 'v.', 'Làm ô uế, báng bổ sự thanh khiết', 'Environmental advocates filed a federal suit against the chemical manufacturer for permitting toxic industrial effluent to defile the pristine river basin.', 'Lesson 8', 8, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'definitive', '/dɪˈfɪnətɪv/', 'adj.', 'Dứt khoát, mang tính quyết định, có thẩm quyền tối hậu', 'Scholars universally regarded the professor''s monumental archival study as the definitive historical treatment of the diplomatic crisis of 1914.', 'Lesson 8', 8, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deflect', '/dɪˈflekt/', 'v.', 'Làm lệch hướng, chuyển hướng', 'Rather than addressing the auditor''s pointed inquiries regarding the misallocated funds, the spokesperson attempted to deflect scrutiny by questioning the committee''s political impartiality.', 'Lesson 9', 9, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defoliate', '/diːˈfoʊ.li.eɪt/', 'v.', 'Làm rụng lá, làm trơ cành', 'During the prolonged counterinsurgency campaign, military strategists authorized chemical spraying to defoliate dense jungle canopies and strip enemy fighters of natural concealment.', 'Lesson 9', 9, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defray', '/dɪˈfreɪ/', 'v.', 'Thanh toán, chi trả (chi phí)', 'The civic endowment was established specifically to defray tuition expenses and laboratory fees for promising underprivileged scholars pursuing doctoral research.', 'Lesson 9', 9, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deft', '/deft/', 'adj.', 'Khéo léo, nhanh nhẹn, tinh tế', 'Through deft diplomatic maneuvering and subtle textual compromises, the veteran envoy negotiated a landmark ceasefire without surrendering sovereign territory.', 'Lesson 9', 9, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defunct', '/dɪˈfʌŋkt/', 'adj.', 'Không còn tồn tại, ngừng hoạt động', 'Archival researchers examined surviving ledgers from the defunct trading guild, reconstructing how catastrophic banking panics caused its sudden dissolution in 1873.', 'Lesson 9', 9, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'defuse', '/diːˈfjuːz/', 'v.', 'Tháo ngòi nổ, xoa dịu căng thẳng', 'The foreign minister convened emergency bilateral talks in Geneva to defuse mounting cross-border hostility before military mobilizations escalated into open warfare.', 'Lesson 9', 9, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'degenerate', '/dɪˈdʒen.ə.reɪt/', 'v.', 'Thoái hóa, suy đồi, biến chất', 'In his critique of republican governance, the philosopher warned that unchecked factional polarization would inevitably cause democratic deliberations to degenerate into mob rule.', 'Lesson 9', 9, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'degradation', '/ˌdeɡ.rəˈdeɪ.ʃən/', 'n.', 'Sự suy thoái, sự xuống cấp', 'Marine biologists attributed the rapid ecological degradation of coral barrier reefs to rising sea temperatures, agricultural runoff, and coastal industrialization.', 'Lesson 9', 9, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dehydrate', '/diːˈhaɪ.dreɪt/', 'v.', 'Làm mất nước, làm khô cạn', 'Prolonged exposure to the scorching desert winds threatened to dehydrate the stranded geological survey team, compelling them to ration their dwindling water supplies with extreme parsimony.', 'Lesson 9', 9, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deify', '/ˈdiː.ɪ.faɪ/', 'v.', 'Tôn sùng như thần, thần thánh hóa', 'Seeking to legitimize autocratic authority and command unquestioning obedience, ancient imperial dynasties routinely orchestrated religious rituals to deify deceased sovereigns.', 'Lesson 9', 9, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deign', '/deɪn/', 'v.', 'Hạ mình, chiếu cố làm điều gì', 'Convinced of his patrician lineage and aesthetic superiority, the reclusive composer would not deign to respond to critical reviews penned by municipal journalists.', 'Lesson 9', 9, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delectable', '/dɪˈlek.tə.bəl/', 'adj.', 'Ngon lành, thú vị, hấp dẫn', 'Attendants at the renaissance feast marvelled at the delectable pastries infused with saffron and almond paste, which were presented on ornate silver platters beneath candlelit vaults.', 'Lesson 9', 9, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delete', '/dɪˈliːt/', 'v.', 'Xóa bỏ, gạch bỏ', 'Before releasing the historical transcripts to the public, the intelligence review board was legally required to delete redacted paragraphs containing classified operative identities.', 'Lesson 9', 9, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deleterious', '/ˌdel.əˈtɪr.i.əs/', 'adj.', 'Có hại, độc hại, gây tổn hại', 'Longitudinal epidemiological studies established that chronic sleep fragmentation exerts deleterious effects on cardiovascular health and executive cognitive functioning.', 'Lesson 9', 9, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deliberate', '/dɪˈlɪb.ər.ət/', 'adj.', 'Có tính toán, thận trọng, cố ý', 'The constitutional framers instituted overlapping bicameral review as a deliberate mechanism to slow legislative passage and guard against impulsive popular passions.', 'Lesson 9', 9, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delineate', '/dɪˈlɪn.i.eɪt/', 'v.', 'Phác họa, mô tả chi tiết, phân định rõ', 'The boundary treaty signed in Paris sought to delineate disputed territorial borders along natural alpine ridges, eliminating jurisdictional ambiguities between neighboring states.', 'Lesson 9', 9, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delirium', '/dɪˈlɪr.i.əm/', 'n.', 'Sự mê sảng, trạng thái cuồng loạn', 'Plagued by virulent septic fever, the wounded soldier lapsed into a state of restless delirium, hallucinating phantom voices and reliving artillery barrages.', 'Lesson 9', 9, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delude', '/dɪˈluːd/', 'v.', 'Lừa dối, đánh lừa, làm cho lầm tưởng', 'Authoritarian regimes frequently employ fabricated economic statistics to delude the citizenry into believing that national production remains robust amid catastrophic shortages.', 'Lesson 9', 9, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deluge', '/ˈdel.juːdʒ/', 'n.', 'Trận đại hồng thủy, sự tràn ngập dồn dập', 'When torrential monsoon storms shattered the earthen reservoir walls, an unstoppable deluge inundated downstream farming communities and wrecked regional transportation infrastructure.', 'Lesson 9', 9, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delusion', '/dɪˈluː.ʒən/', 'n.', 'Ảo tưởng, niềm tin sai lầm', 'Blind to impending fiscal bankruptcy, the company''s executive board clung to the stubborn delusion that consumer demand for obsolete technology would miraculously rebound.', 'Lesson 9', 9, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'delve', '/delv/', 'v.', 'Đào sâu, nghiên cứu kỹ lưỡng', 'To resolve the longstanding anthropological enigma, the research team had to delve into centuries of church baptismal registries and colonial census rolls.', 'Lesson 9', 9, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demagogue', '/ˈdem.ə.ɡɑːɡ/', 'n.', 'Kẻ mị dân, nhà chính trị kích động quần chúng', 'Historians observed that the populist demagogue rose to power by scapegoating ethnic minorities and exploiting widespread economic distress with incendiary rhetoric.', 'Lesson 9', 9, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demean', '/dɪˈmiːn/', 'v.', 'Hạ thấp phẩm giá, làm nhục', 'Advocates for penal reform argued that subjecting incarcerated individuals to degrading public humiliation served only to demean their human spirit without deterring future crime.', 'Lesson 9', 9, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demeanor', '/dɪˈmiː.nər/', 'n.', 'Cử chỉ, thái độ, phong thái', 'Despite hostile interruptions from opposition lawmakers, the prime minister maintained a remarkably composed demeanor, answering contentious allegations with measured cadence.', 'Lesson 9', 9, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demented', '/dɪˈmen.tɪd/', 'adj.', 'Loạn trí, điên cuồng, mất trí', 'Cut off from communication in the arctic wasteland, the stranded expedition commander succumbed to demented suspicions, imagining insubordination among his most dutiful officers.', 'Lesson 9', 9, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demise', '/dɪˈmaɪz/', 'n.', 'Cái chết, sự sụp đổ, sự lụi tàn', 'Archaeological excavations confirmed that abrupt megadroughts and resource overexploitation precipitated the sudden demise of the once-flourishing Bronze Age civilization.', 'Lesson 9', 9, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demolition', '/ˌdem.əˈlɪʃ.ən/', 'n.', 'Sự phá hủy, sự đánh sập', 'Civic heritage coalitions mobilized intense public opposition against the planned demolition of the historic Beaux-Arts opera house in favor of a commercial parking garage.', 'Lesson 9', 9, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demoniac', '/dɪˈmoʊ.ni.æk/', 'adj.', 'Ma quỷ, cuồng loạn, quỷ ám', 'In Mary Shelley''s gothic narrative, Victor Frankenstein beheld his monstrous creation with horror, recoiling from the creature''s demoniac grimace and unnatural physical stature.', 'Lesson 9', 9, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demur', '/dɪˈmɜːr/', 'v.', 'Phản đối, ngần ngại, do dự', 'Although the cabinet advocated immediate martial law, the chief justice did not hesitate to demur, insisting that constitutional safeguards could not be suspended during peacetime.', 'Lesson 9', 9, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demure', '/dɪˈmjʊr/', 'adj.', 'Kín đáo, e dè, thùy mị', 'Behind her modest attire and demure bearing lay an astute political mind that deftly orchestrated backchannel negotiations between hostile factional leaders.', 'Lesson 9', 9, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'demystify', '/diːˈmɪs.tɪ.faɪ/', 'v.', 'Làm sáng tỏ, làm rõ (điều phức tạp)', 'The documentary series aimed to demystify complex macroeconomic monetary policies, translating abstruse econometric modeling into lucid visual concepts for ordinary citizens.', 'Lesson 9', 9, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denigrate', '/ˈden.ɪ.ɡreɪt/', 'v.', 'Gièm pha, bôi nhọ, hạ thấp phẩm giá', 'Rather than evaluating the merits of the breakthrough cosmological hypothesis, established academics unfairly sought to denigrate the young astronomer''s empirical methodology.', 'Lesson 9', 9, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denizen', '/ˈden.ɪ.zən/', 'n.', 'Cư dân, động thực vật bản địa', 'Adapted to survive in perpetual darkness beneath extreme hydrostatic pressure, the viperfish reigns as a formidable denizen of the oceanic bathypelagic zone.', 'Lesson 9', 9, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denotation', '/ˌdiː.noʊˈteɪ.ʃən/', 'n.', 'Nghĩa đen, định nghĩa trực tiếp', 'While the literal denotation of the word ''sanctuary'' signifies a sacred place or protective shelter, its poetic connotation frequently evokes spiritual solace and redemption.', 'Lesson 9', 9, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'denouement', '/deɪˈnuː.mɑː/', 'n.', 'Hồi kết, đoạn kết mở nút (cốt truyện)', 'In the gripping denouement of the courtroom thriller, a long-hidden diary is produced that conclusively proves the accused diplomat had been framed by corporate conspirators.', 'Lesson 9', 9, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depict', '/dɪˈpɪkt/', 'v.', 'Miêu tả, khắc họa, thể hiện', 'Nineteenth-century realist painters eschewed idealized pastoral mythologies to depict the grueling physical toil endured by agrarian laborers during the autumn wheat harvest.', 'Lesson 9', 9, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deplete', '/dɪˈpliːt/', 'v.', 'Làm cạn kiệt, làm suy giảm', 'Industrial extraction of groundwater has outpaced natural recharge rates, threatening to deplete deep subterranean aquifers essential for continental agriculture.', 'Lesson 9', 9, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deplore', '/dɪˈplɔːr/', 'v.', 'Lên án mạnh mẽ, than trách sâu sắc', 'International human rights monitors issued a joint declaration to deplore the unlawful imprisonment of independent journalists and the suppression of judicial independence.', 'Lesson 9', 9, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deploy', '/dɪˈplɔɪ/', 'v.', 'Triển khai, dàn quân, huy động', 'To contain the virulent bacterial outbreak before it crossed regional borders, health authorities moved quickly to deploy epidemiology units and mobile laboratory field units.', 'Lesson 9', 9, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depose', '/dɪˈpoʊz/', 'v.', 'Phế truất, cách chức', 'Prompted by years of systematic corruption and economic collapse, a coalition of civilian leaders and military dissidents moved to depose the autocratic head of state.', 'Lesson 9', 9, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deposition', '/ˌdep.əˈzɪʃ.ən/', 'n.', 'Lời khai hữu thệ, sự phế truất, sự lắng đọng', 'During her videotaped deposition, the corporate whistleblower confirmed under oath that pharmaceutical executives had known about severe adverse drug side effects for years.', 'Lesson 9', 9, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depravity', '/dɪˈpræv.ə.ti/', 'n.', 'Sự suy đồi đạo đức, tính đồi bại', 'Philosophical treatises examining wartime atrocities argue that prolonged exposure to dehumanizing brutality can erode conscience and foster shocking moral depravity.', 'Lesson 9', 9, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deprecate', '/ˈdep.rə.keɪt/', 'v.', 'Phản đối kịch liệt, xem nhẹ', 'Fiscal conservatives in the senate rose to deprecate the omnibus expenditure bill, warning that unfunded municipal subsidies would accelerate national debt accumulation.', 'Lesson 9', 9, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depreciate', '/dɪˈpriː.ʃi.eɪt/', 'v.', 'Giảm giá trị, sụt giảm giá trị', 'When international commodity markets collapsed, capital flight caused the export-reliant nation''s currency to depreciate precipitously against the reserve currency.', 'Lesson 9', 9, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'depredation', '/ˌdep.rəˈdeɪ.ʃən/', 'n.', 'Sự cướp bóc, sự tàn phá hủy hoại', 'Centuries of relentless coastal depredation by North African corsairs forced Mediterranean islanders to abandon unprotected fishing ports for fortified hill retreats.', 'Lesson 9', 9, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deranged', '/dɪˈreɪndʒd/', 'adj.', 'Loạn trí, hoảng loạn, điên loạn', 'Forensic psychiatric examiners concluded that the accused was deeply deranged at the moment of the assault, suffering from acute psychotic breaks that impaired reality testing.', 'Lesson 9', 9, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'derelict', '/ˈder.ə.lɪkt/', 'adj.', 'Bị bỏ hoang, tiêu điều, lơ là trách nhiệm', 'Following decades of deindustrialization, the derelict iron foundry stood decaying along the riverbank, its shattered skylights framing rust-encrusted machinery.', 'Lesson 9', 9, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deride', '/dɪˈraɪd/', 'v.', 'Chế nhạo, giễu cợt, khinh bỉ', 'Conservative medical authorities initially chose to deride Ignaz Semmelweis''s handwashing mandates, mocking the revolutionary idea that physician hygiene prevented fatal puerperal fever.', 'Lesson 9', 9, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'derivative', '/dɪˈrɪv.ə.tɪv/', 'adj.', 'Bắt chước, không có tính nguyên bản', 'Art critics conceded that the painter possessed impeccable brush technique, yet they ultimately judged the exhibition to be derivative of early twentieth-century Cubist masterpieces.', 'Lesson 9', 9, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dermatologist', '/ˌdɜːr.məˈtɑː.lə.dʒɪst/', 'n.', 'Bác sĩ da liễu, chuyên gia da liễu', 'Detecting asymmetrical borders and varied pigmentation during a routine dermoscopic examination, the attentive dermatologist performed an immediate excision to evaluate the suspect lesion.', 'Lesson 9', 9, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'derogatory', '/dɪˈrɑːɡətɔːri/', 'adj.', 'Mang tính xúc phạm, làm giảm uy tín hoặc coi thường', 'The editorial drew widespread condemnation for its derogatory characterization of immigrant workers, which critics argued stoked xenophobia rather than contributing to constructive policy debates.', 'Lesson 9', 9, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'descant', '/dɪsˈkænt/', 'v.', 'Bàn luận hoặc thuyết giảng chi tiết về một chủ đề', 'During his evening lectures, the venerable classicist would often descant at length upon the rhetorical subtleties of Cicero''s orations.', 'Lesson 9', 9, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'descry', '/dɪˈskraɪ/', 'v.', 'Nhìn thấy hoặc phát hiện ra từ xa hoặc lờ mờ', 'Scanning the storm-tossed horizon through his spyglass, the navigator managed to descry the faint, flickering beacon of the coastal lighthouse.', 'Lesson 9', 9, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desecrate', '/ˈdesɪkreɪt/', 'v.', 'Mạo phạm, bôi nhọ hoặc làm ô uế nơi thiêng liêng', 'Vandals who breached the cathedral compound sought to desecrate the sanctuary by toppling centuries-old marble altars and defacing religious iconography.', 'Lesson 9', 9, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desiccate', '/ˈdesɪkeɪt/', 'v.', 'Làm khô cạn, rút hết độ ẩm hoặc sấy khô hoàn toàn', 'Prolonged meteorological drought threatened to desiccate the fertile wetland ecosystem, leaving migratory waterfowl without vital foraging grounds.', 'Lesson 9', 9, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desolate', '/ˈdesələt/', 'adj.', 'Hoang vắng, tiêu điều, cô độc tuyệt vọng', 'Following the abrupt closure of the iron foundry, the boomtown was reduced to a desolate expanse of boarded storefronts and windswept avenues.', 'Lesson 9', 9, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despise', '/dɪˈspaɪz/', 'v.', 'Khinh rẻ, coi thường hoặc ghét cay ghét đắng', 'Though the sycophantic courtiers flattered the monarch to his face, they secretly despised his petty vindictiveness and capricious cruelty.', 'Lesson 9', 9, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despoil', '/dɪˈspɔɪl/', 'v.', 'Cướp đoạt, tước đoạt hoặc bóc lột của cải', 'Unregulated strip-mining operations threatened to despoil the pristine river basin, stripping indigenous communities of both their ancestral homeland and ecological sustenance.', 'Lesson 9', 9, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despondent', '/dɪˈspɑːndənt/', 'adj.', 'Nản lòng, thoái chí hoặc tuyệt vọng', 'After successive laboratory explosions ruined months of synthesis trials, the young chemist grew despondent, questioning the fundamental viability of his hypothesis.', 'Lesson 9', 9, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'despot', '/ˈdespət/', 'n.', 'Kẻ bạo chúa, người cầm quyền độc tài và tàn bạo', 'Refusing to tolerate any semblance of dissent, the military despot dismantled the independent judiciary and shuttered opposition printing presses.', 'Lesson 9', 9, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'destitute', '/ˈdestɪtuːt/', 'adj.', 'Cực kì nghèo khổ, bần cùng, thiếu thốn', 'The catastrophic deflation of the agrarian economy left thousands of tenant sharecroppers entirely destitute, dependent on meager municipal rations.', 'Lesson 9', 9, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'desultory', '/ˈdesəltɔːri/', 'adj.', 'Rời rạc, không có hệ thống hoặc mục đích rõ ràng', 'The congressional hearing produced little actionable insight because the committee engaged in desultory questioning rather than pursuing a cohesive investigative line.', 'Lesson 9', 9, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detached', '/dɪˈtætʃt/', 'adj.', 'Khách quan, vô tư, không bị cảm xúc chi phối', 'A supreme court justice is expected to maintain a detached demeanor, weighing contentious constitutional disputes purely through statutory analysis rather than partisan sentiment.', 'Lesson 9', 9, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'determination', '/dɪˌtɜːrmɪˈneɪʃn/', 'n.', 'Sự quyết tâm kiên định hoặc sự xác định chính xác', 'The paleontologist''s relentless determination to excavate the fossilized strata eventually yielded an intact specimen that revolutionized avian evolutionary taxonomy.', 'Lesson 9', 9, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deterrent', '/dɪˈtɜːrənt/', 'n.', 'Vật ngăn chặn, biện pháp răn đe', 'Geopolitical analysts maintain that a well-enforced regime of multilateral economic sanctions serves as an indispensable deterrent against cross-border aggression.', 'Lesson 9', 9, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detonation', '/ˌdetəˈneɪʃn/', 'n.', 'Sự phát nổ, sự kích nổ', 'Seismographic stations across the continent recorded the precise tremor generated by the underground detonation of the experimental ordinance.', 'Lesson 9', 9, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detraction', '/dɪˈtrækʃn/', 'n.', 'Sự gièm pha, bôi nhọ hoặc làm giảm uy tín', 'The pioneering astronomer endured years of malicious detraction from entrenched academic peers before orbital photographs indisputably confirmed her stellar models.', 'Lesson 9', 9, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'detrimental', '/ˌdetrɪˈmentl/', 'adj.', 'Có hại, gây tổn hại hoặc bất lợi', 'Agronomists warned that the excessive application of synthetic nitrogen fertilizers exerts detrimental effects on subterranean microbiomes and local aquifer purity.', 'Lesson 9', 9, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'deviate', '/ˈdiːvieɪt/', 'v.', 'Chệch hướng, làm khác đi so với lộ trình hoặc tiêu chuẩn', 'When thermal fluctuations caused the automated spacecraft to deviate slightly from its orbital corridor, onboard guidance thrusters fired immediate correctional pulses.', 'Lesson 9', 9, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devious', '/ˈdiːviəs/', 'adj.', 'Láu cá, quỷ quyệt, quanh co không trung thực', 'The minister utilized devious backroom stratagems and confidential leakages to undermine his cabinet rivals without exposing himself to public scrutiny.', 'Lesson 9', 9, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devise', '/dɪˈvaɪz/', 'v.', 'Phát minh, sáng chế, đặt ra kế hoạch', 'Ecological engineers must devise novel desalination architectures that reduce caloric energy consumption while protecting fragile littoral marine habitats.', 'Lesson 9', 9, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devoid', '/dɪˈvɔɪd/', 'adj.', 'Hoàn toàn không có, trống rỗng', 'The author''s stark prose style was purposefully devoid of sentimental embellishment, lending the harrowing war chronicle an air of unvarnished documentary realism.', 'Lesson 9', 9, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devotee', '/ˌdevəˈtiː/', 'n.', 'Người say mê cuồng nhiệt, tín đồ trung thành', 'As an impassioned devotee of Renaissance polyphony, the maestro spent decades scouring monastic archives for forgotten choral manuscripts.', 'Lesson 9', 9, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'devout', '/dɪˈvaʊt/', 'adj.', 'Sùng đạo, thành tâm mộ đạo', 'The pilgrim community adhered to devout traditions of predawn meditation and communal fasting, seeking spiritual transcendence away from modern distractions.', 'Lesson 9', 9, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dexterous', '/ˈdekstrəs/', 'adj.', 'Khéo léo, thuần thục, tinh xảo', 'The watchmaker''s dexterous manipulation of microscopic gears and escapements required decades of meticulous manual apprenticeship.', 'Lesson 9', 9, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diabolical', '/ˌdaɪəˈbɑːlɪkl/', 'adj.', 'Tàn ác như quỷ dữ, thâm hiểm độc ác', 'The prosecutor unmasked the syndicate''s diabolical scheme to adulterate neonatal pharmaceuticals with inert solvents to inflate corporate profit margins.', 'Lesson 9', 9, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diagnosis', '/ˌdaɪəɡˈnoʊsɪs/', 'n.', 'Sự chẩn đoán bệnh trạng hoặc căn nguyên vấn đề', 'Molecular pathology enabled clinicians to render an definitive genetic diagnosis long before clinical symptoms of the neuromuscular disease manifested.', 'Lesson 9', 9, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discomfit', '/dɪsˈkʌmfɪt/', 'v.', 'Làm bối rối, làm lúng túng, khiến bồn chồn', 'The investigative reporter''s pointed questions regarding undisclosed offshore accounts visibly discomfited the corporate spokesperson during the press conference.', 'Lesson 9', 9, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discomposure', '/ˌdɪskəmˈpoʊʒər/', 'n.', 'Sự mất bình tĩnh, sự bối rối hoặc mất tự chủ', 'Despite his aristocratic poise, the ambassador could not conceal his discomposure when confronted with intercepted cables exposing his covert alliances.', 'Lesson 9', 9, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disconcert', '/ˌdɪskənˈsɜːrt/', 'v.', 'Làm bối rối, làm lúng túng hoặc làm mất tự nhiên', 'The sudden and unprovoked resignation of the lead defense attorney threatened to disconcert the entire legal defense team on the eve of the trial.', 'Lesson 9', 9, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disconsolate', '/dɪsˈkɑːnsələt/', 'adj.', 'U sầu, đau buồn khôn xiết, không thể an ủi', 'In the wake of the devastating shipwreck, disconsolate families congregated upon the stormy bluffs, staring hopelessly into the unforgiving surf.', 'Lesson 9', 9, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discord', '/ˈdɪskɔːrd/', 'n.', 'Sự bất hòa, sự xung đột hoặc âm thanh nghịch tai', 'Simmering sectarian discord between rival factions paralyzed the transitional government and stalled constitutional negotiations.', 'Lesson 9', 9, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discordant', '/dɪsˈkɔːrdənt/', 'adj.', 'Bất hòa, trái ngược hoặc chói tai, không hòa hợp', 'The speaker''s inflammatory rhetoric introduced a discordant element into what had otherwise been a harmonious diplomatic symposium.', 'Lesson 9', 9, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discount', '/dɪsˈkaʊnt/', 'v.', 'Xem nhẹ, không coi trọng hoặc chiết khấu, giảm giá', 'Climatologists warned national policymakers not to discount subtle shifts in ocean currents, which could trigger catastrophic regional weather disruptions.', 'Lesson 9', 9, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discourse', '/ˈdɪskɔːrs/', 'n.', 'Bài diễn thuyết, đàm thoại hoặc diễn ngôn học thuật', 'Enlightenment philosophers maintained that civil discourse governed by rational inquiry is the indispensable bedrock of a thriving democratic republic.', 'Lesson 9', 9, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discredit', '/dɪsˈkredɪt/', 'v.', 'Làm mất uy tín, làm giảm độ tin cậy hoặc bác bỏ', 'Subsequent laboratory replications failed to substantiate the controversial findings, effectively discrediting the physicist''s revolutionary claims.', 'Lesson 9', 9, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discrepancy', '/dɪˈskrepənsi/', 'n.', 'Sự khác biệt, sự không nhất quán giữa các con số hoặc dữ kiện', 'Forensic auditors identified a glaring discrepancy between the corporate ledger and the taxable revenue declared to the federal treasury.', 'Lesson 9', 9, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discrete', '/dɪˈskriːt/', 'adj.', 'Riêng biệt, rời rạc, độc lập với nhau', 'Cognitive neuroscientists demonstrated that episodic memory and motor procedural skill are mediated by discrete neural circuits within the cerebral cortex.', 'Lesson 9', 9, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discretion', '/dɪˈskreʃn/', 'n.', 'Quyền tự do quyết định hoặc sự thận trọng kín đáo', 'The statutory statute confers broad administrative discretion upon the environmental commissioner to adjust emission caps during ecological emergencies.', 'Lesson 9', 9, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discriminating', '/dɪˈskrɪmɪneɪtɪŋ/', 'adj.', 'Có óc phán đoán tốt, biết phân biệt tinh tế', 'The gallery curator possessed a discriminating eye for composition, instantly distinguishing authentic Renaissance canvasses from late romantic imitations.', 'Lesson 9', 9, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'discursive', '/dɪˈskɜːrsɪv/', 'adj.', 'Lan man, không tập trung, dông dài', 'Though packed with erudite allusions, the author''s discursive treatise wandered aimlessly across disparate theological debates without ever answering its core thesis.', 'Lesson 9', 9, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disdain', '/dɪsˈdeɪn/', 'n.', 'Sự khinh miệt, thái độ coi thường', 'The patrician aristocracy viewed the rising merchant class with open disdain, scoffing at their commercial fortunes as vulgar and unrefined.', 'Lesson 9', 9, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disembark', '/ˌdɪsɪmˈbɑːrk/', 'v.', 'Xuống tàu, máy bay hoặc các phương tiện vận tải', 'Upon anchoring in the sheltered harbor, the weary expeditionary crew prepared to disembark and establish an inland encampment.', 'Lesson 9', 9, 93),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disenfranchise', '/ˌdɪsɪnˈfræntʃaɪz/', 'v.', 'Tước quyền công dân, đặc biệt là quyền bầu cử', 'Arbitrary residency requirements and restrictive voter identification laws were historically leveraged to disenfranchise vulnerable minority populations.', 'Lesson 9', 9, 94),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disengage', '/ˌdɪsɪnˈɡeɪdʒ/', 'v.', 'Tháo rời, tách ra hoặc rút lui', 'Recognizing that the regional insurgency was drawing imperial forces into an unwinnable quagmire, the field commander chose to disengage his battalions and fortify the frontier.', 'Lesson 9', 9, 95),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disfigure', '/dɪsˈfɪɡjər/', 'v.', 'Làm biến dạng, làm mất đi vẻ thẩm mỹ vốn có', 'Centuries of industrial air pollution and atmospheric acid deposition have begun to corrode and disfigure the intricate limestone relief sculptures of the cathedral facade.', 'Lesson 9', 9, 96),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disgorge', '/dɪsˈɡɔːrdʒ/', 'v.', 'Nôn ra, tuôn ra hoặc xả ra lượng lớn', 'When the subterranean lava tube finally fractured under tectonic pressure, the volcanic caldera began to disgorge colossal torrents of basaltic magma.', 'Lesson 9', 9, 97),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disgruntle', '/dɪsˈɡrʌntl/', 'v.', 'Làm cho bực bội, bất mãn hoặc cau có', 'The administration''s arbitrary suspension of customary health benefits did much to disgruntle the factory workforce and trigger wildcat walkouts.', 'Lesson 9', 9, 98),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dishearten', '/dɪsˈhɑːrtn/', 'v.', 'Làm nản lòng, làm mất đi niềm tin và nhuệ khí', 'The persistent denial of federal grant renewals threatened to dishearten the young epidemiological researchers studying antimicrobial resistance.', 'Lesson 9', 9, 99),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disheveled', '/dɪˈʃevld/', 'adj.', 'Luộm thuộm, xộc xệch, rối bời (đầu tóc, quần áo)', 'Emerging from weeks of solitary confinement in the damp dungeon, the prisoner stood before the magistrates with gaunt cheeks and disheveled garments.', 'Lesson 9', 9, 100),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disinclination', '/ˌdɪsˌɪnklɪˈneɪʃn/', 'n.', 'Sự miễn cưỡng, sự ngần ngại, sự thiếu hào hứng', 'Despite lucrative commercial offers from private industry, the veteran astronomer demonstrated a clear disinclination to abandon her university laboratory and academic research.', 'Lesson 10', 10, 1),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disingenuous', '/ˌdɪsɪnˈdʒɛnjuəs/', 'adj.', 'Không chân thật, xảo trá, giả vờ ngây ngô', 'Editorial writers condemned the diplomat''s remarks as disingenuous, arguing that he knowingly feigned ignorance of the border skirmishes to avert international sanctions.', 'Lesson 10', 10, 2),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disinter', '/ˌdɪsɪnˈtɜːr/', 'v.', 'Khai quật, quật mộ, đưa ra ánh sáng', 'Authorized by a court order, forensic pathologists arrived at dawn to disinter the victim''s remains in hopes of uncovering toxicological evidence overlooked decades earlier.', 'Lesson 10', 10, 3),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disinterested', '/dɪsˈɪntrəstɪd/', 'adj.', 'Công tâm, vô tư, không vụ lợi', 'To guarantee an equitable arbitration, the treaty required disputes to be mediated by a disinterested tribunal with no stake in regional commerce.', 'Lesson 10', 10, 4),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disjointed', '/dɪsˈdʒɔɪntɪd/', 'adj.', 'Rời rạc, đứt đoạn, thiếu mạch lạc', 'Suffering from high fever and exhaustion, the explorer delivered a disjointed narrative whose abrupt chronological jumps left the rescue crew perplexed.', 'Lesson 10', 10, 5),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dislodge', '/dɪsˈlɑːdʒ/', 'v.', 'Đánh bật, trục xuất, làm bật ra khỏi vị trí', 'Torrents of glacial meltwater surged through the narrow ravine, dislodging massive granite boulders that had rested undisturbed along the canyon floor for centuries.', 'Lesson 10', 10, 6),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismantle', '/dɪsˈmæntl/', 'v.', 'Tháo dỡ, triệt hạ cấu trúc hoặc hệ thống', 'Following the historic nonproliferation treaty, international atomic inspectors oversaw specialized teams tasked with safely dismantling the decommissioned plutonium enrichment plant.', 'Lesson 10', 10, 7),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismay', '/dɪsˈmeɪ/', 'n.', 'Sự mất tinh thần, nỗi thất vọng pha lẫn âu lo', 'To the profound dismay of environmental scientists, the regulatory commission voted to weaken emissions caps despite overwhelming empirical data indicating escalating global temperatures.', 'Lesson 10', 10, 8),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismember', '/dɪsˈmɛmbər/', 'v.', 'Phân chia lãnh thổ, cắt xẻ tứ chi', 'The victorious coalition convened at the peace congress with the explicit intention to dismember the defeated empire into several autonomous border provinces.', 'Lesson 10', 10, 9),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dismiss', '/dɪsˈmɪs/', 'v.', 'Gạt bỏ, bác bỏ, coi nhẹ', 'Establishment astronomers originally dismissed the amateur stargazer''s planetary observations as instrument error until subsequent satellite imagery confirmed the presence of a new asteroid belt.', 'Lesson 10', 10, 10),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disparage', '/dɪˈspærɪdʒ/', 'v.', 'Gièm pha, miệt thị, hạ thấp giá trị', 'Traditionalist art critics routinely disparaged modern abstract painting, claiming that nonrepresentational canvases required neither technical mastery nor aesthetic discipline.', 'Lesson 10', 10, 11),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disparate', '/ˈdɪspərət/', 'adj.', 'Khác biệt căn bản, hoàn toàn dị biệt', 'The interdisciplinary research seminar brought together scholars from disparate disciplines—including computational linguistics, behavioral economics, and cultural anthropology—to investigate human decision-making.', 'Lesson 10', 10, 12),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disparity', '/dɪˈspærɪti/', 'n.', 'Sự chênh lệch lớn, sự bất bình đẳng', 'A comprehensive public health audit revealed a stark disparity in access to specialized pediatric care between prosperous metropolitan centers and impoverished rural counties.', 'Lesson 10', 10, 13),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispassionate', '/dɪsˈpæʃənət/', 'adj.', 'Khách quan, điềm tĩnh, không thiên vị', 'A reliable constitutional jurist must adopt a dispassionate posture, interpreting statutory texts through legal precedent rather than personal political convictions.', 'Lesson 10', 10, 14),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispatch', '/dɪˈspætʃ/', 'v.', 'Phái đi, gửi đi nhanh chóng', 'Upon receiving intelligence of an unauthorized naval intrusion, the admiralty immediately dispatched three reconnaissance frigates to patrol the contested territorial waters.', 'Lesson 10', 10, 15),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispel', '/dɪˈspɛl/', 'v.', 'Xua tan, dẹp bỏ hoài nghi hoặc nỗi sợ', 'Rigorous longitudinal data published in the medical journal helped dispel widespread public misconceptions regarding the safety and efficacy of mRNA vaccines.', 'Lesson 10', 10, 16),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disperse', '/dɪˈspɜːrs/', 'v.', 'Phân tán, giải tán, rải rác khắp nơi', 'Once the torrential rain subsided and the autumn winds gathered strength, the seeds of the milkweed pod were dispersed across the prairie landscape.', 'Lesson 10', 10, 17),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dispirited', '/dɪˈspɪrɪtɪd/', 'adj.', 'Chán nản, nản lòng, nhụt chí', 'Plagued by unending supply shortages and brutal winter storms, the dispirited garrison lost the will to resist the encroaching besiegers.', 'Lesson 10', 10, 18),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disputatious', '/ˌdɪspjuːˈteɪʃəs/', 'adj.', 'Hiếu biện, thích tranh luận, hay cãi cọ', 'Known for his disputatious temperament, the young parliamentarian turned every routine budgetary discussion into a ferocious philosophical quarrel.', 'Lesson 10', 10, 19),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disquiet', '/dɪsˈkwaɪət/', 'n.', 'Sự bất an, nỗi âu lo, cảm giác bồn chồn', 'Unconfirmed reports of troop movements along the northern frontier sowed deep disquiet among urban shopkeepers, prompting many to hoard essential foodstuffs.', 'Lesson 10', 10, 20),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissection', '/dɪˈsɛkʃn/', 'n.', 'Sự mổ xẻ, sự phân tích chi tiết', 'The literary theorist’s rigorous dissection of the author''s early poetry revealed hidden autobiographical allegories beneath seemingly pastoral motifs.', 'Lesson 10', 10, 21),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissemble', '/dɪˈsɛmbl/', 'v.', 'Che giấu, ngụy tạo, giấu giếm cảm xúc thật', 'Unable to dissemble her profound indignation any longer, the whistleblower stood before the congressional committee and exposed the corporation''s toxic dumping practices.', 'Lesson 10', 10, 22),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'disseminate', '/dɪˈsɛmɪneɪt/', 'v.', 'Phổ biến, lan truyền, truyền bá rộng rãi', 'During the early decades of the printing revolution, underground broadsides helped disseminate radical democratic ideals to literate working-class citizens.', 'Lesson 10', 10, 23),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissent', '/dɪˈsɛnt/', 'v.', 'Bất đồng quan điểm, phản đối ý kiến chính thống', 'In her sharply worded opinion, Justice Harlan dissented from the ruling, arguing passionately that racial segregation statutes violated the core equal protection guarantees of the Constitution.', 'Lesson 10', 10, 24),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissertation', '/ˌdɪsərˈteɪʃn/', 'n.', 'Luận án, luận văn nghiên cứu chuyên sâu', 'To complete his doctoral dissertation in maritime economic history, Arthur spent years in Lisbon transcribing sixteenth-century spice trade ledgers.', 'Lesson 10', 10, 25),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissident', '/ˈdɪsɪdənt/', 'n.', 'Người bất đồng chính kiến, người phản kháng', 'Despite continuous surveillance and house arrest, the prominent dissident published clandestine tracts denouncing the junta''s suppression of basic civil liberties.', 'Lesson 10', 10, 26),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissimulate', '/dɪˈsɪmjuleɪt/', 'v.', 'Che đậy, ngụy trang suy nghĩ hoặc cảm xúc', 'Skilled in the treacherous etiquette of the royal court, the ambitious duke learned to dissimulate his contempt for the prime minister beneath lavish praise.', 'Lesson 10', 10, 27),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissipate', '/ˈdɪsɪpeɪt/', 'v.', 'Xua tan, tiêu tan, phung phí năng lượng hoặc tài nguyên', 'As midday heat warmed the coastal valley, the dense blanket of maritime fog began to dissipate, uncovering the sparkling waters of the bay.', 'Lesson 10', 10, 28),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissolute', '/ˈdɪsəluːt/', 'adj.', 'Phóng đãng, trụy lạc, trác táng', 'Historical chroniclers depicted the young monarch''s court as notoriously dissolute, dominated by lavish midnight revels and reckless financial mismanagement.', 'Lesson 10', 10, 29),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissolution', '/ˌdɪsəˈluːʃn/', 'n.', 'Sự giải tán, sự giải thể, sự tan rã', 'The sudden dissolution of the governing parliamentary coalition precipitated an early national election amidst severe financial turmoil.', 'Lesson 10', 10, 30),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissonance', '/ˈdɪsənəns/', 'n.', 'Sự bất hòa, sự nghịch tai, mâu thuẫn nhận thức', 'The modern composer juxtaposed traditional orchestral melodies with abrupt chromatic dissonance to mirror the disorienting pace of industrialized urban life.', 'Lesson 10', 10, 31),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dissuade', '/dɪˈsweɪd/', 'v.', 'Khuyên can, can ngăn', 'Recognizing the peril of traversing the alpine pass during a sudden blizzard, the veteran sherpa managed to dissuade the expedition from proceeding further.', 'Lesson 10', 10, 32),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distant', '/ˈdɪstənt/', 'adj.', 'Xa cách, lạnh nhạt, xa xôi', 'Deeply shaken by the courtroom revelations, the defendant withdrew into himself, offering only distant and monosyllabic answers to his defense attorney''s inquiries.', 'Lesson 10', 10, 33),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distend', '/dɪˈstɛnd/', 'v.', 'Làm căng phồng, sưng phồng, giãn nở', 'Emergency veterinarians noted that the ingested foreign obstruction had caused the canine''s abdomen to distend dangerously, requiring immediate surgical intervention.', 'Lesson 10', 10, 34),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distill', '/dɪˈstɪl/', 'v.', 'Chưng cất, đúc kết tinh túy', 'In her seminal work on jurisprudence, the legal philosopher managed to distill thousands of pages of convoluted statutory case law into three fundamental moral principles.', 'Lesson 10', 10, 35),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distinction', '/dɪˈstɪŋkʃn/', 'n.', 'Sự phân biệt, nét đặc trưng, sự ưu tú', 'The epistemologist emphasized a crucial distinction between empirical claims verified through sensory experience and purely deductive truths arrived at by logical deduction.', 'Lesson 10', 10, 36),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distort', '/dɪˈstɔːrt/', 'v.', 'Xuyên tạc, bóp méo, làm biến dạng', 'Critics accused the sensationalist documentary of deliberately distorting the anthropological record to portray a peaceful indigenous community as inherently warlike.', 'Lesson 10', 10, 37),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'distraught', '/dɪˈstrɔːt/', 'adj.', 'Quẫn trí, hoảng loạn, đau khổ tột cùng', 'Distraught by news of the catastrophic shipwreck off the cape, desperate families huddled together on the windswept pier praying for word of survivors.', 'Lesson 10', 10, 38),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diurnal', '/daɪˈɜːrnl/', 'adj.', 'Hoạt động ban ngày, thuộc về ban ngày', 'While many desert rodents emerge only at night to escape lethal thermal stress, diurnal species like the antelope ground squirrel possess specialized physiological adaptations for foraging under the midday sun.', 'Lesson 10', 10, 39),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diva', '/ˈdiːvə/', 'n.', 'Nữ danh ca opera, người tự phụ kiêu kỳ', 'Famed both for her peerless vocal agility and her imperious backstage conduct, the operatic diva commanded total deference from conductors and stagehands alike.', 'Lesson 10', 10, 40),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diverge', '/daɪˈvɜːrdʒ/', 'v.', 'Phân kỳ, rẽ ra các hướng khác nhau', 'Although both evolutionary lineages originated from a common proto-primate ancestor, their anatomical adaptations began to diverge sharply following the formation of the Rift Valley.', 'Lesson 10', 10, 41),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divergent', '/daɪˈvɜːrdʒənt/', 'adj.', 'Khác biệt, bất đồng, phân kỳ', 'The macroeconomic panel presented strikingly divergent forecasts regarding post-war recovery, with one faction anticipating rapid industrial rebound and the other predicting entrenched stagflation.', 'Lesson 10', 10, 42),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diverse', '/daɪˈvɜːrs/', 'adj.', 'Đa dạng, muôn vẻ, phong phú', 'The ancient imperial capital drew merchant caravans from diverse geographic regions, blending Central Asian textile craftsmanship with Mediterranean metallurgical techniques.', 'Lesson 10', 10, 43),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diversion', '/daɪˈvɜːrʒn/', 'n.', 'Sự làm chệch hướng, hoạt động giải trí tiêu khiển', 'The general ordered an infantry regiment to feign a river crossing as a tactical diversion, thereby drawing enemy reserves away from the primary assault corridor.', 'Lesson 10', 10, 44),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'diversity', '/daɪˈvɜːrsɪti/', 'n.', 'Tính đa dạng, sự phong phú', 'Ecological studies confirm that high levels of botanical diversity significantly enhance the resilience of temperate grassland communities against severe climatic disruptions.', 'Lesson 10', 10, 45),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divest', '/daɪˈvɛst/', 'v.', 'Tước bỏ, thoái vốn, tước đoạt quyền lợi', 'Under mounting ethical pressure from student organizations, the university board of trustees voted unanimously to divest its multi-billion-dollar endowment from overseas mining conglomerates.', 'Lesson 10', 10, 46),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divine', '/dɪˈvaɪn/', 'v.', 'Đoán biết bằng trực giác, tiên đoán', 'Drawing upon decades of maritime navigation, the seasoned captain seemed able to divine shifting ocean currents simply by observing subtle variations in wave crests and foam patterns.', 'Lesson 10', 10, 47),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'divulge', '/daɪˈvʌldʒ/', 'v.', 'Tiết lộ, để lộ thông tin bí mật', 'Bound by professional oaths and rigorous state secrecy acts, the cipher clerk refused to divulge the cryptographic keys used to decipher intercepted diplomatic cables.', 'Lesson 10', 10, 48),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'docile', '/ˈdoʊsaɪl/', 'adj.', 'Dễ bảo, ngoan ngoãn, thuần phục', 'Over generations of selective breeding, pastoralists converted the aggressive wild aurochs into a docile domestic breed capable of plowing rocky terraced slopes.', 'Lesson 10', 10, 49),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doctrinaire', '/ˌdɑːktrɪˈnɛr/', 'adj.', 'Giáo điều, cứng nhắc, bám chấp lý thuyết', 'The treasury secretary’s doctrinaire commitment to unregulated free-market dogma blindfolded him to the systemic liquidity crises crippling rural credit cooperatives.', 'Lesson 10', 10, 50),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doctrine', '/ˈdɒktrɪn/', 'n.', 'Học thuyết, giáo lý', 'The Monroe Doctrine asserted that any further European colonization in the Western Hemisphere would be viewed as an act of hostility toward the United States.', 'Lesson 10', 10, 51),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'document', '/ˈdɒkjument/', 'v.', 'Ghi chép tài liệu, thu thập bằng chứng', 'Anthropologists spent decades in the Amazon basin to meticulously document the endangered oral traditions and botanical remedies of indigenous healers.', 'Lesson 10', 10, 52),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doff', '/dɒf/', 'v.', 'Cởi bỏ mũ, ngả mũ chào', 'As the funeral cortege passed through the village square, the solemn townsfolk stepped forward to doff their hats in quiet reverence.', 'Lesson 10', 10, 53),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dogged', '/ˈdɒɡɪd/', 'adj.', 'Kiên cường, bền bỉ, gan góc', 'Through years of archival dead ends and bureaucratic obstruction, the investigative journalist pursued the corruption scandal with dogged determination.', 'Lesson 10', 10, 54),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doggerel', '/ˈdɒɡərəl/', 'n.', 'Thơ vần vè vụng về, thơ dở', 'Dismissing the political pamphlet as mere doggerel, the literary critic argued that its clumsy couplets and irregular meter lacked artistic merit.', 'Lesson 10', 10, 55),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dogmatic', '/dɒɡˈmætɪk/', 'adj.', 'Giáo điều, độc đoán', 'Rather than encouraging open empirical debate, the committee chairman adopted a dogmatic stance, summarily rejecting any hypothesis that challenged conventional wisdom.', 'Lesson 10', 10, 56),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doldrums', '/ˈdɒldrəmz/', 'n.', 'Tình trạng đình trệ, cảnh ảm đạm', 'Targeted public investments in renewable infrastructure finally helped lift the regional manufacturing sector out of its prolonged economic doldrums.', 'Lesson 10', 10, 57),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doleful', '/ˈdəʊlfl/', 'adj.', 'U sầu, buồn thảm, ai oán', 'The solitary cellist played a doleful elegy whose melancholic cadences echoed mournfully through the cavernous sanctuary.', 'Lesson 10', 10, 58),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dolt', '/dəʊlt/', 'n.', 'Kẻ khờ dại, người ngu ngốc', 'Though political rivals unfairly dismissed him as a bumbling dolt, the premier quietly outmaneuvered his opponents through shrewd parliamentary tactics.', 'Lesson 10', 10, 59),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'domicile', '/ˈdɒmɪsaɪl/', 'n.', 'Nơi cư trú, nơi thường trú', 'To claim statutory tax exemption, the expatriate was required to furnish legal records establishing that her permanent domicile remained overseas.', 'Lesson 10', 10, 60),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'domineer', '/ˌdɒmɪˈnɪər/', 'v.', 'Áp chế, hống hách, lấn át', 'The imperious party leader sought to domineer over junior legislators, demanding absolute allegiance on every contentious policy vote.', 'Lesson 10', 10, 61),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'don', '/dɒn/', 'v.', 'Mặc vào, khoác lên', 'Before venturing onto the lunar surface, astronauts were required to don pressurized suits engineered to withstand extreme thermal fluctuations.', 'Lesson 10', 10, 62),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'doodle', '/ˈduːdl/', 'v.', 'Vẽ nguệch ngoạc, vẽ lơ đãng', 'Distracted by the monotonous rhythm of the maritime inquiry, the witness began to doodle intricate nautical charts on the margins of his transcript.', 'Lesson 10', 10, 63),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dormant', '/ˈdɔːmənt/', 'adj.', 'Ngủ yên, tạm thời bất hoạt', 'Seismologists warned that although the stratovolcano had lain dormant for three centuries, magma accumulation indicated a catastrophic eruption was brewing.', 'Lesson 10', 10, 64),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dormer', '/ˈdɔːmə/', 'n.', 'Cửa sổ mái sổ ra', 'Sunlight filtered through the high dormer of the colonial garret, casting sharp geometric shadows across the weathered pine floorboards.', 'Lesson 10', 10, 65),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dossier', '/ˈdɒsieɪ/', 'n.', 'Hồ sơ tài liệu chi tiết', 'Naval counterintelligence compiled an exhaustive dossier chronicling the covert communication channels exploited by foreign espionage rings.', 'Lesson 10', 10, 66),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dote', '/dəʊt/', 'v.', 'Cưng chiều hết mực, yêu quý mù quáng', 'Despite the young aristocrat''s scandalous reputation, his wealthy aunt continued to dote upon him, funding his lavish excursions abroad.', 'Lesson 10', 10, 67),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'douse', '/daʊs/', 'v.', 'Dội nước làm ướt sũng, dập tắt lửa', 'Before evacuating the alpine outpost, rangers had to thoroughly douse the campfire with buckets of snow to prevent a brushfire.', 'Lesson 10', 10, 68),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dowdy', '/ˈdaʊdi/', 'adj.', 'Luộm thuộm, lỗi mốt, quê mùa', 'Surrounded by aristocrats in embroidered silk robes, the foreign envoy appeared conspicuously dowdy in his plain woolen broadcloth suit.', 'Lesson 10', 10, 69),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'downcast', '/ˈdaʊnkɑːst/', 'adj.', 'Chán nản, thất vọng, ủ rũ', 'When news arrived that the peace negotiations had abruptly collapsed, the weary delegates returned to their quarters in downcast spirits.', 'Lesson 10', 10, 70),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drab', '/dræb/', 'adj.', 'Xám xịt, nhạt nhẽo, buồn tẻ', 'The post-industrial docklands were dominated by drab concrete warehouses and rusting cranes that stood bleak against the winter sky.', 'Lesson 10', 10, 71),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'draconian', '/drəˈkəʊniən/', 'adj.', 'Hà khắc, cực kỳ nghiêm ngặt', 'Civil rights organizations petitioned the international court against the state''s draconian surveillance statutes, alleging severe violations of privacy.', 'Lesson 10', 10, 72),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dregs', '/dreɡz/', 'n.', 'Cặn bã, phần thừa thãi vô giá trị', 'By the winter of 1777, the besieged garrison had consumed their reserves and were reduced to drinking the foul dregs of stagnant cisterns.', 'Lesson 10', 10, 73),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drivel', '/ˈdrɪvl/', 'n.', 'Chuyện nhảm nhí, lời nói vô nghĩa', 'The eminent philosopher refused to dignify the sensationalist pamphlet with a rebuttal, dismissing its conspiracy theories as unlettered drivel.', 'Lesson 10', 10, 74),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'droll', '/drəʊl/', 'adj.', 'Khôi hài, hóm hỉnh kỳ quặc', 'With dry wit and deadpan delivery, the satirical columnist offered a droll commentary on the absurdities of metropolitan high society.', 'Lesson 10', 10, 75),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drone', '/drəʊn/', 'v.', 'Nói giọng đều đều buồn ngủ, kêu vo ve', 'As the parliamentary clerk continued to drone through the dozens of technical amendments, several legislators quietly dozed in their benches.', 'Lesson 10', 10, 76),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dross', '/drɒs/', 'n.', 'Xỉ kim loại, cặn bã vô giá trị', 'The metallurgist carefully skimmed the oxidized dross from the molten silver before pouring the purified metal into casting molds.', 'Lesson 10', 10, 77),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'drudgery', '/ˈdrʌdʒəri/', 'n.', 'Công việc cực nhọc, sự vất vả nhàm chán', 'Prior to the mechanization of agriculture, weeding sprawling cotton fields by hand represented an unremitting drudgery for farm laborers.', 'Lesson 10', 10, 78),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dubious', '/ˈdjuːbiəs/', 'adj.', 'Đáng nghi, mơ hồ, hoài nghi', 'Independent economic analysts remained deeply dubious of the central bank''s inflation forecast, citing volatile global commodity prices.', 'Lesson 10', 10, 79),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ductile', '/ˈdʌktaɪl/', 'adj.', 'Dễ uốn, dễ dát mỏng, dễ uốn nắn', 'Because gold is exceptionally ductile, a single ounce can be drawn into an ultrafine wire extending over fifty miles without fracturing.', 'Lesson 10', 10, 80),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dulcet', '/ˈdʌlsɪt/', 'adj.', 'Êm dịu, ngọt ngào, thánh thót', 'The contralto''s dulcet voice resonated through the stone amphitheater, soothing the tense crowd gathered in the piazza.', 'Lesson 10', 10, 81),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dumbfound', '/dʌmˈfaʊnd/', 'v.', 'Làm chết lặng, làm sửng sốt', 'The astronomer''s revelation that the distant galaxy exhibited impossible orbital mechanics served to dumbfound the astrophysics community.', 'Lesson 10', 10, 82),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dupe', '/djuːp/', 'v.', 'Lừa gạt, đánh lừa', 'By forging official government seals and falsifying deeds, the con artist managed to dupe unsuspecting investors into funding fictitious railroad lines.', 'Lesson 10', 10, 83),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'duplicity', '/djuːˈplɪsəti/', 'n.', 'Tính hai lòng, sự xảo trá', 'The declassified memos exposed the cabinet minister''s duplicity, showing that he secretly courted foreign monopolists while publicly decrying their predatory practices.', 'Lesson 10', 10, 84),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'duration', '/djuˈreɪʃn/', 'n.', 'Thời lượng, khoảng thời gian tồn tại', 'Because the polar night extends for the entire duration of the arctic winter, expedition members must cope with relentless psychological strain.', 'Lesson 10', 10, 85),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'duress', '/djuˈres/', 'n.', 'Sự ép buộc, sự cưỡng ép', 'The tribunal nullified the treaty after uncovering evidence that the sovereign had signed under physical duress and imminent threat of bombardment.', 'Lesson 10', 10, 86),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dutiful', '/ˈdjuːtɪfl/', 'adj.', 'Tận tụy, làm tròn bổn phận, biết vâng lời', 'Throughout four decades of turbulent naval service, the admiral remained a dutiful commander who placed constitutional loyalty above political ambition.', 'Lesson 10', 10, 87),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dwarf', '/dwɔːf/', 'v.', 'Làm lu mờ, thu nhỏ lại khi so sánh', 'The staggering scale of the transcontinental railway project threatened to dwarf all previous civil engineering achievements in the nation''s history.', 'Lesson 10', 10, 88),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dwindle', '/ˈdwɪndl/', 'v.', 'Thu hẹp dần, cạn kiệt dần, suy giảm', 'As annual rainfall plummeted and aquifer levels dropped, municipal water reserves began to dwindle to precarious thresholds.', 'Lesson 10', 10, 89),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'dynamic', '/daɪˈnæmɪk/', 'adj.', 'Năng động, luôn biến đổi, năng tiến', 'Ecologists increasingly conceptualize estuaries as dynamic transitional biomes whose species diversity depends on continuous tidal fluctuations.', 'Lesson 10', 10, 90),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'earthy', '/ˈɜːθi/', 'adj.', 'Mộc mạc, chân chất, có mùi đất', 'Chaucer''s Canterbury Tales is celebrated for combining courtly romance with the earthy, ribald humor of fourteenth-century English commoners.', 'Lesson 10', 10, 91),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ebb', '/eb/', 'v.', 'Suy thoái dần, rút dần, tàn lụi', 'As wartime fervor began to ebb across the republic, citizen assemblies voiced escalating dissatisfaction with heavy taxation and trade restrictions.', 'Lesson 10', 10, 92),
  ('e8f7c92b-8a1e-4c3d-b5e2-0a1b2c3d4e5f', 'ebullient', '/ɪˈbʌliənt/', 'adj.', 'Sôi nổi, hân hoan, tràn đầy năng lượng', 'The orchestra delivered an ebullient rendition of the symphony''s finale, eliciting a roaring standing ovation from the captivated audience.', 'Lesson 10', 10, 93);
